import { Router, type IRouter } from "express";
import { and, desc, eq } from "drizzle-orm";
import { z } from "zod/v4";
import { alertPreferences, alerts, weeklySummaries } from "@workspace/shared/schema";
import {
  GetAlertPreferencesResponse,
  GetAlertsResponse,
  GetLatestWeeklySummaryResponse,
  MarkAlertReadResponse,
  SubmitAlertFeedbackBody,
  SubmitAlertFeedbackResponse,
  UpdateAlertPreferenceBody,
  UpdateAlertPreferenceResponse,
} from "@workspace/api-zod";
import { db } from "../db/connection";
import { requireAuth } from "../middlewares/security";
import { apiError } from "../lib/errors";
import { ALERT_PREFERENCE_TYPES } from "../services/alerts";

const router: IRouter = Router();
router.use(requireAuth);

router.get("/alerts", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const rows = await db.select().from(alerts).where(eq(alerts.userId, req.session.userId!))
    .orderBy(desc(alerts.createdAt));
  rows.sort((a, b) =>
    Number(a.readAt !== null) - Number(b.readAt !== null) ||
    b.createdAt.getTime() - a.createdAt.getTime(),
  );
  res.json(GetAlertsResponse.parse({ data: rows }));
});

router.post("/alerts/:id/read", async (req, res): Promise<void> => {
  const id = z.string().uuid().safeParse(req.params.id);
  if (!id.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Alerta inválido.");
    return;
  }
  const [row] = await db.update(alerts).set({ readAt: new Date(), updatedAt: new Date() })
    .where(and(eq(alerts.id, id.data), eq(alerts.userId, req.session.userId!)))
    .returning({ id: alerts.id });
  if (!row) {
    apiError(res, 404, "NOT_FOUND", "Alerta não encontrado.");
    return;
  }
  res.json(MarkAlertReadResponse.parse({ data: { ok: true } }));
});

router.post("/alerts/:id/feedback", async (req, res): Promise<void> => {
  const id = z.string().uuid().safeParse(req.params.id);
  const feedback = SubmitAlertFeedbackBody.safeParse(req.body);
  if (!id.success || !feedback.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Feedback inválido.");
    return;
  }
  const [row] = await db.update(alerts).set({ useful: feedback.data.useful, updatedAt: new Date() })
    .where(and(eq(alerts.id, id.data), eq(alerts.userId, req.session.userId!)))
    .returning({ id: alerts.id });
  if (!row) {
    apiError(res, 404, "NOT_FOUND", "Alerta não encontrado.");
    return;
  }
  res.json(SubmitAlertFeedbackResponse.parse({ data: { ok: true } }));
});

router.get("/alert-preferences", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const rows = await db.select({ type: alertPreferences.type, enabled: alertPreferences.enabled })
    .from(alertPreferences).where(eq(alertPreferences.userId, req.session.userId!));
  const stored = new Map(rows.map((row) => [row.type, row.enabled]));
  const data = ALERT_PREFERENCE_TYPES.map((type) => ({ type, enabled: stored.get(type) ?? true }));
  res.json(GetAlertPreferencesResponse.parse({ data }));
});

router.put("/alert-preferences", async (req, res): Promise<void> => {
  const parsed = UpdateAlertPreferenceBody.safeParse(req.body);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Preferência inválida.");
    return;
  }
  const userId = req.session.userId!;
  const { type, enabled } = parsed.data;
  await db.insert(alertPreferences).values({ userId, type, enabled }).onConflictDoUpdate({
    target: [alertPreferences.userId, alertPreferences.type],
    set: { enabled, updatedAt: new Date() },
  });
  const rows = await db.select({ type: alertPreferences.type, enabled: alertPreferences.enabled })
    .from(alertPreferences).where(eq(alertPreferences.userId, userId));
  const stored = new Map(rows.map((row) => [row.type, row.enabled]));
  const data = ALERT_PREFERENCE_TYPES.map((preferenceType) => ({
    type: preferenceType, enabled: stored.get(preferenceType) ?? true,
  }));
  res.json(UpdateAlertPreferenceResponse.parse({ data }));
});

router.get("/summaries/weekly/latest", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const [summary] = await db.select().from(weeklySummaries).where(eq(weeklySummaries.userId, req.session.userId!))
    .orderBy(desc(weeklySummaries.weekStart), desc(weeklySummaries.createdAt)).limit(1);
  res.json(GetLatestWeeklySummaryResponse.parse({ data: summary ?? null }));
});

export default router;
