import type { Transaction } from "@workspace/shared/schema";

export type TransactionCorrection = Pick<Partial<Transaction>, "categoryId" | "isTransfer" | "notes"> & { applyToSimilar?: boolean };
type Editable = Pick<Transaction, "id" | "categoryId" | "categorySource" | "categoryConfidence" | "isTransfer" | "notes">;
export function planTransactionCorrection(target: Editable, similar: Editable[], update: TransactionCorrection, now: Date) {
  const selected = {
    ...(update.categoryId !== undefined ? { categoryId: update.categoryId, categorySource: "user" as const, categoryConfidence: null } : {}),
    ...(update.isTransfer !== undefined ? { isTransfer: update.isTransfer } : {}),
    ...(update.notes !== undefined ? { notes: update.notes } : {}),
  };
  const selectedChanged = Object.entries(selected).some(([key, value]) => target[key as keyof Editable] !== value);
  const similarIds = update.applyToSimilar && update.categoryId ? similar.filter((item) =>
    item.id !== target.id && item.categorySource !== "user"
    && (item.categoryId !== update.categoryId || item.categorySource !== "user_rule" || item.categoryConfidence !== null),
  ).map((item) => item.id) : [];
  return { selected: { ...selected, updatedAt: now }, selectedChanged, similarIds, updatedCount: Number(selectedChanged) + similarIds.length };
}
