import { sql } from "drizzle-orm";
import {
  pgTable, uuid, text, timestamp, bigint, integer, boolean, date,
  real, jsonb, index, uniqueIndex,
} from "drizzle-orm/pg-core";
import { createInsertSchema, createSelectSchema } from "drizzle-zod";
import { z } from "zod/v4";

const base = () => ({
  id: uuid("id").defaultRandom().primaryKey(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});
const editable = () => ({
  ...base(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$onUpdate(() => new Date()),
});
const cents = (name: string) => bigint(name, { mode: "number" });
const day = (name: string) => date(name, { mode: "string" });
const instant = (name: string) => timestamp(name, { withTimezone: true });

export const users = pgTable("users", {
  ...editable(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  name: text("name"),
  timezone: text("timezone").notNull().default("America/Sao_Paulo"),
  plan: text("plan", { enum: ["free", "premium"] }).notNull().default("free"),
  monthlyIncomeOverrideCents: cents("monthly_income_override_cents"),
  savingsTargetCents: cents("savings_target_cents").notNull().default(0),
  aiQuestionsUsed: integer("ai_questions_used").notNull().default(0),
  aiQuestionsPeriod: text("ai_questions_period"),
});

const owner = () => uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" });
const owned = () => ({ ...editable(), userId: owner() });

// The session table is intentionally managed by connect-pg-simple, not Drizzle.
export const connections = pgTable("connections", {
  ...owned(),
  provider: text("provider", { enum: ["mock", "pluggy", "manual"] }).notNull(),
  providerItemId: text("provider_item_id"),
  institutionName: text("institution_name").notNull(),
  institutionLogoUrl: text("institution_logo_url"),
  status: text("status", { enum: ["syncing", "active", "error", "needs_reauth", "revoked"] }).notNull(),
  consentExpiresAt: instant("consent_expires_at"),
  lastSyncedAt: instant("last_synced_at"),
  lastErrorCode: text("last_error_code"),
}, (t) => [index("connections_user_idx").on(t.userId)]);

export const accounts = pgTable("accounts", {
  ...owned(),
  connectionId: uuid("connection_id").notNull().references(() => connections.id, { onDelete: "cascade" }),
  providerAccountId: text("provider_account_id"),
  type: text("type", { enum: ["checking", "savings", "credit_card", "cash"] }).notNull(),
  name: text("name").notNull(),
  balanceCents: cents("balance_cents").notNull(),
  creditLimitCents: cents("credit_limit_cents"),
  availableLimitCents: cents("available_limit_cents"),
  billCloseDate: day("bill_close_date"),
  billDueDate: day("bill_due_date"),
  isHidden: boolean("is_hidden").notNull().default(false),
}, (t) => [
  index("accounts_user_idx").on(t.userId),
  uniqueIndex("accounts_connection_provider_idx").on(t.connectionId, t.providerAccountId),
]);

export const categories = pgTable("categories", {
  ...editable(),
  userId: uuid("user_id").references(() => users.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  kind: text("kind", { enum: ["expense", "income", "transfer", "review"] }).notNull(),
  icon: text("icon").notNull(),
  color: text("color").notNull(),
  sortOrder: integer("sort_order").notNull(),
}, (t) => [index("categories_user_idx").on(t.userId)]);

export const recurrences = pgTable("recurrences", {
  ...owned(),
  accountId: uuid("account_id").references(() => accounts.id, { onDelete: "set null" }),
  kind: text("kind", { enum: ["subscription", "fixed_bill", "income"] }).notNull(),
  label: text("label").notNull(),
  merchantKey: text("merchant_key").notNull(),
  expectedAmountCents: cents("expected_amount_cents").notNull(),
  previousAmountCents: cents("previous_amount_cents"),
  frequency: text("frequency", { enum: ["monthly"] }).notNull().default("monthly"),
  dayOfMonth: integer("day_of_month").notNull(),
  nextExpectedDate: day("next_expected_date").notNull(),
  status: text("status", { enum: ["active", "ignored"] }).notNull(),
  source: text("source", { enum: ["detected", "user"] }).notNull(),
}, (t) => [index("recurrences_user_idx").on(t.userId)]);

export const bills = pgTable("bills", {
  ...owned(),
  accountId: uuid("account_id").notNull().references(() => accounts.id, { onDelete: "cascade" }),
  providerBillId: text("provider_bill_id"),
  closeDate: day("close_date").notNull(),
  dueDate: day("due_date").notNull(),
  totalCents: cents("total_cents").notNull(),
  minimumPaymentCents: cents("minimum_payment_cents"),
  paidCents: cents("paid_cents").notNull().default(0),
  status: text("status", { enum: ["open", "closed", "paid", "partially_paid"] }).notNull(),
}, (t) => [
  index("bills_user_idx").on(t.userId),
  uniqueIndex("bills_account_provider_idx").on(t.accountId, t.providerBillId),
]);

export const transactions = pgTable("transactions", {
  ...owned(),
  accountId: uuid("account_id").notNull().references(() => accounts.id, { onDelete: "cascade" }),
  providerTransactionId: text("provider_transaction_id"),
  providerStableId: text("provider_stable_id"),
  providerCategory: text("provider_category"),
  dedupeKey: text("dedupe_key").notNull(),
  date: day("date").notNull(),
  descriptionRaw: text("description_raw").notNull(),
  merchantKey: text("merchant_key").notNull(),
  merchantName: text("merchant_name"),
  amountCents: cents("amount_cents").notNull(),
  paymentMethod: text("payment_method", { enum: ["pix", "boleto", "card", "ted", "debit", "other"] }).notNull(),
  counterpartType: text("counterpart_type", { enum: ["person", "company"] }),
  counterpartName: text("counterpart_name"),
  counterpartDocMasked: text("counterpart_doc_masked"),
  categoryId: uuid("category_id").notNull().references(() => categories.id),
  categorySource: text("category_source", { enum: ["user", "user_rule", "system_rule", "provider", "ai", "default"] }).notNull(),
  categoryConfidence: real("category_confidence"),
  isTransfer: boolean("is_transfer").notNull().default(false),
  transferPairId: uuid("transfer_pair_id"),
  isBillPayment: boolean("is_bill_payment").notNull().default(false),
  installmentNumber: integer("installment_number"),
  installmentTotal: integer("installment_total"),
  installmentGroupKey: text("installment_group_key"),
  recurrenceId: uuid("recurrence_id").references(() => recurrences.id, { onDelete: "set null" }),
  billId: uuid("bill_id").references(() => bills.id, { onDelete: "set null" }),
  notes: text("notes"),
  deletedAt: instant("deleted_at"),
}, (t) => [
  index("transactions_user_idx").on(t.userId),
  index("transactions_user_date_idx").on(t.userId, t.date.desc()),
  uniqueIndex("transactions_account_dedupe_idx").on(t.accountId, t.dedupeKey),
  index("transactions_user_category_date_idx").on(t.userId, t.categoryId, t.date),
  index("transactions_user_merchant_idx").on(t.userId, t.merchantKey),
]);

export const categoryRules = pgTable("category_rules", {
  ...owned(),
  merchantKey: text("merchant_key").notNull(),
  categoryId: uuid("category_id").notNull().references(() => categories.id),
  createdFromTransactionId: uuid("created_from_transaction_id").references(() => transactions.id, { onDelete: "set null" }),
}, (t) => [
  index("category_rules_user_idx").on(t.userId),
  uniqueIndex("category_rules_user_merchant_idx").on(t.userId, t.merchantKey),
]);

export const budgets = pgTable("budgets", {
  ...owned(),
  categoryId: uuid("category_id").notNull().references(() => categories.id),
  month: text("month").notNull(),
  limitCents: cents("limit_cents").notNull(),
}, (t) => [
  index("budgets_user_idx").on(t.userId),
  uniqueIndex("budgets_user_category_month_idx").on(t.userId, t.categoryId, t.month),
]);

export const goals = pgTable("goals", {
  ...owned(),
  name: text("name").notNull(),
  targetCents: cents("target_cents").notNull(),
  targetDate: day("target_date"),
  savedCents: cents("saved_cents").notNull().default(0),
  monthlyContributionCents: cents("monthly_contribution_cents").notNull().default(0),
  status: text("status", { enum: ["active", "done", "archived"] }).notNull(),
}, (t) => [index("goals_user_idx").on(t.userId)]);

export const debts = pgTable("debts", {
  ...owned(),
  name: text("name").notNull(),
  kind: text("kind", { enum: ["card_revolving", "overdraft", "personal_loan", "other"] }).notNull(),
  balanceCents: cents("balance_cents").notNull(),
  monthlyRateBps: integer("monthly_rate_bps").notNull(),
  rateIsEstimated: boolean("rate_is_estimated").notNull().default(true),
  minimumPaymentCents: cents("minimum_payment_cents").notNull(),
  source: text("source", { enum: ["detected", "user"] }).notNull(),
  accountId: uuid("account_id").references(() => accounts.id, { onDelete: "set null" }),
  confirmed: boolean("confirmed").notNull().default(false),
}, (t) => [
  index("debts_user_idx").on(t.userId),
  uniqueIndex("debts_detected_user_account_kind_idx").on(t.userId, t.accountId, t.kind).where(sql`${t.source} = 'detected'`),
]);

export const debtPlans = pgTable("debt_plans", {
  ...owned(),
  strategy: text("strategy", { enum: ["avalanche", "snowball"] }).notNull(),
  monthlyBudgetCents: cents("monthly_budget_cents").notNull(),
  active: boolean("active").notNull(),
  startedAt: day("started_at").notNull(),
}, (t) => [index("debt_plans_user_idx").on(t.userId)]);

export const alerts = pgTable("alerts", {
  ...owned(),
  type: text("type").notNull(),
  severity: text("severity", { enum: ["info", "warning", "critical"] }).notNull(),
  title: text("title").notNull(),
  body: text("body").notNull(),
  payload: jsonb("payload").notNull(),
  dedupeKey: text("dedupe_key").notNull(),
  readAt: instant("read_at"),
  useful: boolean("useful"),
}, (t) => [
  index("alerts_user_idx").on(t.userId),
  uniqueIndex("alerts_user_dedupe_idx").on(t.userId, t.dedupeKey),
]);

export const alertPreferences = pgTable("alert_preferences", {
  ...owned(),
  type: text("type").notNull(),
  enabled: boolean("enabled").notNull().default(true),
}, (t) => [
  index("alert_preferences_user_idx").on(t.userId),
  uniqueIndex("alert_preferences_user_type_idx").on(t.userId, t.type),
]);

export const chatConversations = pgTable("chat_conversations", {
  ...owned(),
}, (t) => [index("chat_conversations_user_idx").on(t.userId)]);

export const chatMessages = pgTable("chat_messages", {
  ...owned(),
  conversationId: uuid("conversation_id").notNull().references(() => chatConversations.id, { onDelete: "cascade" }),
  role: text("role", { enum: ["user", "assistant"] }).notNull(),
  content: text("content").notNull(),
  citedTransactionIds: uuid("cited_transaction_ids").array().notNull().default(sql`'{}'::uuid[]`),
  toolTrace: jsonb("tool_trace").notNull().default([]),
  feedback: text("feedback", { enum: ["up", "down", "wrong"] }),
}, (t) => [index("chat_messages_user_idx").on(t.userId)]);

export const weeklySummaries = pgTable("weekly_summaries", {
  ...owned(),
  weekStart: day("week_start").notNull(),
  payload: jsonb("payload").notNull(),
  text: text("text").notNull(),
}, (t) => [index("weekly_summaries_user_idx").on(t.userId)]);

export const auditLog = pgTable("audit_log", {
  ...base(),
  userId: uuid("user_id").notNull(), // Deliberately no FK: deletion audit must survive.
  action: text("action").notNull(),
  metadata: jsonb("metadata").notNull(),
}, (t) => [index("audit_log_user_idx").on(t.userId)]);

export const webhookEvents = pgTable("webhook_events", {
  ...base(),
  eventId: text("event_id").notNull().unique(),
  event: text("event").notNull(),
  itemId: text("item_id").notNull(),
  receivedAt: instant("received_at").notNull().defaultNow(),
  processedAt: instant("processed_at"),
});

export const insertUserSchema = createInsertSchema(users).omit({ id: true, createdAt: true, updatedAt: true });
export const selectUserSchema = createSelectSchema(users).omit({ passwordHash: true });
export const insertConnectionSchema = createInsertSchema(connections).omit({ id: true, createdAt: true, updatedAt: true });
export const insertAccountSchema = createInsertSchema(accounts).omit({ id: true, createdAt: true, updatedAt: true });
export const insertCategorySchema = createInsertSchema(categories).omit({ id: true, createdAt: true, updatedAt: true });
export const insertRecurrenceSchema = createInsertSchema(recurrences).omit({ id: true, createdAt: true, updatedAt: true });
export const insertBillSchema = createInsertSchema(bills).omit({ id: true, createdAt: true, updatedAt: true });
export const insertTransactionSchema = createInsertSchema(transactions).omit({ id: true, createdAt: true, updatedAt: true });
export const insertCategoryRuleSchema = createInsertSchema(categoryRules).omit({ id: true, createdAt: true, updatedAt: true });
export const insertBudgetSchema = createInsertSchema(budgets).omit({ id: true, createdAt: true, updatedAt: true });
export const insertGoalSchema = createInsertSchema(goals).omit({ id: true, createdAt: true, updatedAt: true });
export const insertDebtSchema = createInsertSchema(debts).omit({ id: true, createdAt: true, updatedAt: true });
export const insertDebtPlanSchema = createInsertSchema(debtPlans).omit({ id: true, createdAt: true, updatedAt: true });
export const insertAlertSchema = createInsertSchema(alerts).omit({ id: true, createdAt: true, updatedAt: true });
export const insertAlertPreferenceSchema = createInsertSchema(alertPreferences).omit({ id: true, createdAt: true, updatedAt: true });
export const insertChatConversationSchema = createInsertSchema(chatConversations).omit({ id: true, createdAt: true, updatedAt: true });
export const insertChatMessageSchema = createInsertSchema(chatMessages).omit({ id: true, createdAt: true, updatedAt: true });
export const insertWeeklySummarySchema = createInsertSchema(weeklySummaries).omit({ id: true, createdAt: true, updatedAt: true });
export const insertAuditLogSchema = createInsertSchema(auditLog).omit({ id: true, createdAt: true });
export const insertWebhookEventSchema = createInsertSchema(webhookEvents).omit({ id: true, createdAt: true });

export const signupSchema = z.object({
  name: z.string().trim().min(1, "Informe seu nome.").max(120),
  email: z.email("Informe um e-mail válido.").trim().toLowerCase().max(254),
  password: z.string().min(8, "A senha deve ter pelo menos 8 caracteres.").max(72),
  acceptedTerms: z.literal(true, { error: "Aceite os termos e a política de privacidade." }),
});
export const loginSchema = signupSchema.pick({ email: true, password: true });

export type User = typeof users.$inferSelect;
export type InsertUser = z.infer<typeof insertUserSchema>;
export type Connection = typeof connections.$inferSelect;
export type Account = typeof accounts.$inferSelect;
export type Category = typeof categories.$inferSelect;
export type Transaction = typeof transactions.$inferSelect;
export type CategoryRule = typeof categoryRules.$inferSelect;
export type Recurrence = typeof recurrences.$inferSelect;
export type Bill = typeof bills.$inferSelect;
export type Budget = typeof budgets.$inferSelect;
export type Goal = typeof goals.$inferSelect;
export type Debt = typeof debts.$inferSelect;
export type DebtPlan = typeof debtPlans.$inferSelect;
export type Alert = typeof alerts.$inferSelect;
export type AlertPreference = typeof alertPreferences.$inferSelect;
export type ChatConversation = typeof chatConversations.$inferSelect;
export type ChatMessage = typeof chatMessages.$inferSelect;
export type WeeklySummary = typeof weeklySummaries.$inferSelect;
export type AuditLog = typeof auditLog.$inferSelect;
export type WebhookEvent = typeof webhookEvents.$inferSelect;
