import { Router, type IRouter, type Request } from "express";
import { and, desc, eq, inArray, sql } from "drizzle-orm";
import { z } from "zod/v4";
import { chatConversations, chatMessages, transactions, users } from "@workspace/shared/schema";
import {
  GetAssistantUsageResponse,
  GetLatestAssistantConversationResponse,
  SendAssistantMessageBody,
  SendAssistantMessageResponse,
  SubmitAssistantMessageFeedbackBody,
  SubmitAssistantMessageFeedbackResponse,
} from "@workspace/api-zod";
import { db } from "../db/connection";
import { transactionQuery } from "../db/repositories/transactions";
import { assistantRateLimit, requireAuth } from "../middlewares/security";
import { apiError } from "../lib/errors";
import { localDate, TIMEZONE } from "../lib/dates";
import { assistantUsageFor, canAskAssistant, nextAssistantUsage } from "../services/assistant-usage";
import { loadAssistantMaskingContext, createAssistantToolExecutor, maskAssistantQuestion } from "../assistant/tools";
import { replacePrivatePersonKeys, runAssistantToolLoop, AssistantResponseError } from "../assistant/loop";

const router: IRouter = Router();
router.use(requireAuth);

function usageFromRow(row: Pick<typeof users.$inferSelect, "plan" | "aiQuestionsUsed" | "aiQuestionsPeriod">, now: Date) {
  return assistantUsageFor({
    plan: row.plan,
    aiQuestionsUsed: row.aiQuestionsUsed,
    aiQuestionsPeriod: row.aiQuestionsPeriod,
  }, now);
}

function traceTransactionIds(toolTrace: unknown): string[] {
  if (!Array.isArray(toolTrace)) return [];
  return toolTrace.flatMap((entry) => {
    if (!entry || typeof entry !== "object" || !("transactionIds" in entry) || !Array.isArray(entry.transactionIds)) return [];
    return entry.transactionIds.filter((id: unknown): id is string => typeof id === "string" && z.uuid().safeParse(id).success);
  });
}

async function citationsFor(userId: string, ids: string[]) {
  if (ids.length === 0) return [];
  const rows = await transactionQuery(userId, [inArray(transactions.id, [...new Set(ids)])]);
  return rows.map((row) => ({
    id: row.id,
    date: row.date,
    merchantName: row.merchantName ?? row.merchantKey,
    description: row.counterpartType === "person"
      ? row.merchantName ?? row.merchantKey
      : row.descriptionRaw,
    amountCents: row.amountCents,
    categoryName: row.categoryName,
    accountName: row.accountName,
  }));
}

async function discardFailedAssistantRequest(
  req: Request,
  userId: string,
  conversationId: string,
  userMessageId: string,
  period: string,
) {
  try {
    await db.transaction(async (tx) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
      await tx.delete(chatMessages).where(and(
        eq(chatMessages.id, userMessageId),
        eq(chatMessages.userId, userId),
        eq(chatMessages.role, "user"),
      ));
      const [remaining] = await tx.select({ id: chatMessages.id }).from(chatMessages)
        .where(and(eq(chatMessages.userId, userId), eq(chatMessages.conversationId, conversationId))).limit(1);
      if (!remaining) {
        await tx.delete(chatConversations).where(and(
          eq(chatConversations.id, conversationId),
          eq(chatConversations.userId, userId),
        ));
      }
      await tx.update(users).set({
        aiQuestionsUsed: sql`greatest(${users.aiQuestionsUsed} - 1, 0)`,
      }).where(and(eq(users.id, userId), eq(users.aiQuestionsPeriod, period)));
    });
  } catch (error) {
    req.log.error({ errName: error instanceof Error ? error.name : "UnknownError" }, "Assistant request cleanup failed");
  }
}

async function latestConversation(userId: string) {
  const [conversation] = await db.select().from(chatConversations)
    .where(eq(chatConversations.userId, userId))
    .orderBy(desc(chatConversations.updatedAt), desc(chatConversations.createdAt))
    .limit(1);
  if (!conversation) return { conversationId: null, messages: [] };

  const rows = (await db.select().from(chatMessages)
    .where(and(eq(chatMessages.userId, userId), eq(chatMessages.conversationId, conversation.id)))
    .orderBy(desc(chatMessages.createdAt), desc(chatMessages.id))
    .limit(10)).reverse();
  const context = await loadAssistantMaskingContext(userId);
  const privateNames = Object.fromEntries(context.privateNamesByKey);
  const data = await Promise.all(rows.map(async (message) => {
    const citedTransactions = message.role === "assistant"
      ? await citationsFor(userId, message.citedTransactionIds)
      : [];
    const allowedIds = new Set(citedTransactions.map((transaction) => transaction.id));
    return {
      id: message.id,
      role: message.role,
      content: message.role === "assistant" ? replacePrivatePersonKeys(message.content, privateNames) : message.content,
      citedTransactionIds: message.citedTransactionIds.filter((id) => allowedIds.has(id)),
      citedTransactions,
      feedback: message.feedback,
      createdAt: message.createdAt,
    };
  }));
  return { conversationId: conversation.id, messages: data };
}

router.get("/assistant/usage", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const now = new Date();
  const [user] = await db.select({
    plan: users.plan,
    aiQuestionsUsed: users.aiQuestionsUsed,
    aiQuestionsPeriod: users.aiQuestionsPeriod,
  }).from(users).where(eq(users.id, req.session.userId!)).limit(1);
  if (!user) {
    apiError(res, 404, "NOT_FOUND", "Usuário não encontrado.");
    return;
  }
  res.json(GetAssistantUsageResponse.parse({ data: usageFromRow(user, now) }));
});

router.get("/assistant/conversations/latest", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const result = await latestConversation(req.session.userId!);
  res.json(GetLatestAssistantConversationResponse.parse({
    data: { conversationId: result.conversationId, messages: result.messages },
  }));
});

router.post("/assistant/messages", assistantRateLimit, async (req, res): Promise<void> => {
  const parsed = SendAssistantMessageBody.safeParse(req.body);
  if (!parsed.success || !z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Escreva uma pergunta com até 3.000 caracteres.");
    return;
  }

  const userId = req.session.userId!;
  const now = new Date();
  const context = await loadAssistantMaskingContext(userId);
  let conversationId: string;
  let userMessageRow: typeof chatMessages.$inferSelect;
  let usage: ReturnType<typeof assistantUsageFor>;
  let modelHistory: Array<{ role: "user" | "assistant"; content: string }> = [];
  let previousToolIds: string[] = [];

  try {
    const reserved = await db.transaction(async (tx) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
      const [user] = await tx.select({
        id: users.id,
        plan: users.plan,
        name: users.name,
        aiQuestionsUsed: users.aiQuestionsUsed,
        aiQuestionsPeriod: users.aiQuestionsPeriod,
      }).from(users).where(eq(users.id, userId)).limit(1);
      if (!user) return { kind: "error" as const, code: "NOT_FOUND" as const };
      const currentUsage = usageFromRow(user, now);
      if (!canAskAssistant(currentUsage)) return { kind: "error" as const, code: "AI_LIMIT_REACHED" as const };

      let conversation: typeof chatConversations.$inferSelect | undefined;
      if (parsed.data.conversationId) {
        [conversation] = await tx.select().from(chatConversations).where(and(
          eq(chatConversations.id, parsed.data.conversationId),
          eq(chatConversations.userId, userId),
        )).limit(1);
        if (!conversation) return { kind: "error" as const, code: "CONVERSATION_NOT_FOUND" as const };
      } else {
        [conversation] = await tx.insert(chatConversations).values({ userId }).returning();
      }
      const nextUsage = nextAssistantUsage(currentUsage);
      await tx.update(users).set({
        aiQuestionsUsed: nextUsage.used,
        aiQuestionsPeriod: nextUsage.period,
        updatedAt: now,
      }).where(eq(users.id, userId));
      const [savedUserMessage] = await tx.insert(chatMessages).values({
        userId,
        conversationId: conversation!.id,
        role: "user",
        content: parsed.data.message,
        citedTransactionIds: [],
        toolTrace: [],
      }).returning();
      await tx.update(chatConversations).set({ updatedAt: now }).where(and(
        eq(chatConversations.id, conversation!.id),
        eq(chatConversations.userId, userId),
      ));
      const recentMessages = await tx.select().from(chatMessages).where(and(
        eq(chatMessages.userId, userId),
        eq(chatMessages.conversationId, conversation!.id),
      )).orderBy(desc(chatMessages.createdAt), desc(chatMessages.id)).limit(11);
      const ordered = recentMessages.reverse();
      const savedId = savedUserMessage!.id;
      modelHistory = ordered.filter((message) => message.id !== savedId).slice(-10).map((message) => ({
        role: message.role,
        content: message.role === "user" ? maskAssistantQuestion(message.content, context) : message.content,
      }));
      previousToolIds = ordered.filter((message) => message.role === "assistant")
        .flatMap((message) => traceTransactionIds(message.toolTrace));
      return { kind: "ok" as const, conversationId: conversation!.id, userMessage: savedUserMessage!, usage: nextUsage };
    });

    if (reserved.kind === "error") {
      if (reserved.code === "AI_LIMIT_REACHED") {
        apiError(res, 429, "AI_LIMIT_REACHED", "Você usou suas 20 perguntas deste mês. O limite gratuito será renovado no próximo mês.");
        return;
      }
      apiError(res, 404, reserved.code,
        reserved.code === "CONVERSATION_NOT_FOUND" ? "Conversa não encontrada." : "Usuário não encontrado.");
      return;
    }
    conversationId = reserved.conversationId;
    userMessageRow = reserved.userMessage;
    usage = reserved.usage;
  } catch (error) {
    req.log.error({ errName: error instanceof Error ? error.name : "UnknownError" }, "Assistant usage reservation failed");
    apiError(res, 500, "ASSISTANT_UNAVAILABLE", "Não foi possível iniciar a resposta agora. Tente novamente.");
    return;
  }

  try {
    const result = await runAssistantToolLoop({
      userMessage: maskAssistantQuestion(parsed.data.message, context),
      history: modelHistory,
      today: localDate(now),
      timezone: TIMEZONE,
      plan: usage.plan,
      executeTool: createAssistantToolExecutor(userId, now, context),
      previouslyAuthorizedTransactionIds: previousToolIds,
    });
    const citations = await citationsFor(userId, result.citedTransactionIds);
    const citationIds = citations.map((citation) => citation.id);
    const [assistantMessageRow] = await db.insert(chatMessages).values({
      userId,
      conversationId,
      role: "assistant",
      content: result.answer,
      citedTransactionIds: citationIds,
      toolTrace: result.toolTrace,
    }).returning();
    await db.update(chatConversations).set({ updatedAt: new Date() }).where(and(
      eq(chatConversations.id, conversationId),
      eq(chatConversations.userId, userId),
    ));
    const privateNames = {
      ...Object.fromEntries(context.privateNamesByKey),
      ...result.privateNamesByKey,
    };
    const assistantMessage = {
      id: assistantMessageRow!.id,
      role: "assistant" as const,
      content: replacePrivatePersonKeys(result.answer, privateNames),
      citedTransactionIds: citationIds,
      citedTransactions: citations,
      feedback: assistantMessageRow!.feedback,
      createdAt: assistantMessageRow!.createdAt,
    };
    const userMessage = {
      id: userMessageRow.id,
      role: "user" as const,
      content: userMessageRow.content,
      citedTransactionIds: [],
      citedTransactions: [],
      feedback: null,
      createdAt: userMessageRow.createdAt,
    };
    res.json(SendAssistantMessageResponse.parse({
      data: { conversationId, userMessage, assistantMessage, usage },
    }));
  } catch (error) {
    if (error instanceof AssistantResponseError) {
      await discardFailedAssistantRequest(req, userId, conversationId, userMessageRow.id, usage.period);
      apiError(res, 502, "ASSISTANT_INVALID_RESPONSE", "Não consegui montar uma resposta confiável desta vez. Tente novamente.");
      return;
    }
    await discardFailedAssistantRequest(req, userId, conversationId, userMessageRow.id, usage.period);
    req.log.error({ errName: error instanceof Error ? error.name : "UnknownError" }, "Assistant model request failed");
    apiError(res, 502, "ASSISTANT_UNAVAILABLE", "O assistente está indisponível no momento. Tente novamente em instantes.");
  }
});

router.post("/assistant/messages/:id/feedback", async (req, res): Promise<void> => {
  const id = z.uuid().safeParse(req.params.id);
  const feedback = SubmitAssistantMessageFeedbackBody.safeParse(req.body);
  if (!id.success || !feedback.success || !z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Feedback inválido.");
    return;
  }
  const [row] = await db.update(chatMessages).set({ feedback: feedback.data.feedback, updatedAt: new Date() })
    .where(and(
      eq(chatMessages.id, id.data),
      eq(chatMessages.userId, req.session.userId!),
      eq(chatMessages.role, "assistant"),
    )).returning({ id: chatMessages.id });
  if (!row) {
    apiError(res, 404, "NOT_FOUND", "Resposta não encontrada.");
    return;
  }
  res.json(SubmitAssistantMessageFeedbackResponse.parse({ data: { ok: true } }));
});

export default router;
