import express, { type Express, type ErrorRequestHandler } from "express";
import helmet from "helmet";
import session from "express-session";
import connectPgSimple from "connect-pg-simple";
import pinoHttp from "pino-http";
import { fileURLToPath } from "node:url";
import router from "./routes";
import { pool } from "./db/connection";
import { logger } from "./lib/logger";
import { verifyOrigin, apiRateLimit } from "./middlewares/security";
import { apiError } from "./lib/errors";

export const SESSION_COOKIE = "financas.sid";
const PgStore = connectPgSimple(session);

export function createApp(options: { sessionSecret?: string; testing?: boolean } = {}): Express {
  const secret = options.sessionSecret ?? process.env.SESSION_SECRET;
  if (!secret) throw new Error("SESSION_SECRET is required.");
  const app = express();
  app.set("trust proxy", 1);
  app.disable("x-powered-by");
  app.use(helmet());
  if (!options.testing) {
    app.use(pinoHttp({
      logger,
      serializers: {
        req: (req) => ({ id: req.id, method: req.method, url: req.url?.split("?")[0] }),
        res: (res) => ({ statusCode: res.statusCode }),
      },
    }));
  }
  app.use(express.json({ limit: "32kb" }));
  const store = new PgStore({
    pool,
    tableName: "session",
    createTableIfMissing: true,
    pruneSessionInterval: options.testing ? false : 900,
  });
  app.locals.sessionStore = store;
  app.use(session({
    name: SESSION_COOKIE,
    store,
    secret,
    resave: false,
    saveUninitialized: false,
    rolling: true,
    cookie: {
      httpOnly: true,
      sameSite: "lax",
      secure: process.env.NODE_ENV === "production",
      maxAge: 7 * 24 * 60 * 60 * 1000,
      path: "/",
    },
  }));
  app.use("/api/v1", verifyOrigin);
  app.use("/api/v1", apiRateLimit);
  app.use("/api", router);
  app.use("/api", (_req, res) => apiError(res, 404, "NOT_FOUND", "Recurso não encontrado."));
  if (process.env.NODE_ENV === "production") {
    const clientDir = fileURLToPath(new URL("../../client/dist/public/", import.meta.url));
    app.use(express.static(clientDir));
    app.get("/{*path}", (_req, res) => res.sendFile(`${clientDir}index.html`));
  }
  const handleError: ErrorRequestHandler = (err, req, res, _next) => {
    if (err instanceof SyntaxError && "body" in err) {
      apiError(res, 400, "VALIDATION_ERROR", "Envie um JSON válido.");
      return;
    }
    // Do not serialize error details: database errors can contain personal data.
    if (!options.testing) req.log?.error("Request failed");
    apiError(res, 500, "INTERNAL_ERROR", "Não foi possível concluir. Tente novamente.");
  };
  app.use(handleError);
  return app;
}
