import { z } from "zod/v4";
import type { Category, CategoryRule, Transaction } from "@workspace/shared/schema";
import { normalizeDescription } from "./normalization";

export type CategoryCatalog = Pick<Category, "id" | "name">[];
export type CategorizationDecision = Pick<Transaction, "id" | "categoryId" | "categorySource" | "categoryConfidence">;
export type CategorizationItem = Pick<Transaction, "id" | "merchantKey" | "descriptionRaw" | "amountCents" | "date" | "paymentMethod" | "counterpartType" | "counterpartName" | "providerCategory" | "categorySource">;
export type CategoryPrediction = { id: string; categoryName: string; confidence: number };

// SPEC §7.4: preserve row order and the word boundaries, not merchant_key.
export const SYSTEM_RULES = [
  { category: "Pagamento de fatura", patterns: [/\bPAGAMENTO (DE )?FATURA\b/i, /\bPGTO (DE )?CARTAO\b/i, /\bPAGAMENTO RECEBIDO\b/i] },
  { category: "Salário", incomingOnly: true, patterns: [/\bSALARIO\b/i, /\bFOLHA\b/i] },
  { category: "Aplicação e resgate", patterns: [/\bAPLICACAO\b/i, /\bRESGATE\b/i, /\bCDB\b/i, /\bTESOURO\b/i, /\bCAIXINHA\b/i, /\bCOFRINHO\b/i] },
  { category: "Juros e encargos", patterns: [/\bJUROS\b/i, /\bENCARGOS\b/i, /\bMULTA\b/i, /\bROTATIVO\b/i] },
  { category: "Tarifas e impostos", patterns: [/\bTARIFA\b/i, /\bIOF\b/i, /\bANUIDADE\b/i, /\bIPVA\b/i, /\bIPTU\b/i, /\bDARF\b/i] },
  { category: "Delivery", patterns: [/\bUBER EATS\b/i, /\bIFOOD\b/i, /\bRAPPI\b/i, /\bZE DELIVERY\b/i, /\bAIQFOME\b/i] },
  { category: "Transporte", patterns: [/\bUBER\b/i, /\b99 ?(APP|POP|TAXI)\b/i, /\bCABIFY\b/i, /\bMETRO\b/i, /\bSUPERVIA\b/i, /\bRIOCARD\b/i, /\bBILHETE UNICO\b/i] },
  { category: "Assinaturas", patterns: [/\bNETFLIX\b/i, /\bSPOTIFY\b/i, /\bDISNEY\b/i, /\bHBO ?MAX\b/i, /\bPRIME VIDEO\b/i, /\bAMAZON PRIME\b/i, /\bYOUTUBE\b/i, /\bAPPLE COM BILL\b/i, /\bGOOGLE ONE\b/i, /\bDEEZER\b/i, /\bGLOBOPLAY\b/i, /\bPARAMOUNT\b/i] },
  { category: "Saúde e bem-estar", patterns: [/\bSMART ?FIT\b/i, /\bBLUEFIT\b/i, /\bWELLHUB\b/i, /\bGYMPASS\b/i, /\bTOTALPASS\b/i, /\bDROGASIL\b/i, /\bDROGARIA\b/i, /\bDROGA ?RAIA\b/i, /\bPAGUE MENOS\b/i, /\bFARMACIA\b/i] },
  { category: "Combustível", patterns: [/\bPOSTO\b/i, /\bSHELL\b/i, /\bIPIRANGA\b/i, /\bPETROBRAS\b/i] },
  { category: "Compras", patterns: [/\bMERCADO ?LIVRE\b/i, /\bAMAZON\b/i, /\bMAGALU\b/i, /\bMAGAZINE LUIZA\b/i, /\bSHOPEE\b/i, /\bSHEIN\b/i, /\bALIEXPRESS\b/i, /\bAMERICANAS\b/i, /\bCASAS BAHIA\b/i, /\bELETRO\w*/i] },
  { category: "Mercado", patterns: [/\bCARREFOUR\b/i, /\bASSAI\b/i, /\bATACADAO\b/i, /\bPAO DE ACUCAR\b/i, /\bZONA SUL\b/i, /\bGUANABARA\b/i, /\bPREZUNIC\b/i, /\bHORTIFRUTI\b/i, /\bSUPERMERC\w*/i, /\bMERCADO\b/i, /\bMERCADINHO\b/i] },
  { category: "Contas da casa", patterns: [/\bENEL\b/i, /\bLIGHT\b/i, /\bCEMIG\b/i, /\bCOPEL\b/i, /\bCPFL\b/i, /\bSABESP\b/i, /\bCEDAE\b/i, /\bAGUAS DO RIO\b/i, /\bCOMGAS\b/i, /\bNATURGY\b/i, /\bVIVO\b/i, /\bCLARO\b/i, /\bTIM\b/i, /\bOI\b/i, /\bNET SERVICOS\b/i] },
  { category: "Moradia", patterns: [/\bCOND\b/i, /\bCONDOMINIO\b/i, /\bALUGUEL\b/i, /\bIMOBILIARIA\b/i] },
  { category: "Restaurantes", patterns: [/\bRESTAURANTE\b/i, /\bLANCHONETE\b/i, /\bBAR\b/i, /\bPADARIA\b/i, /\bCAFE\b/i, /\bMCDONALDS\b/i, /\bBURGER KING\b/i, /\bOUTBACK\b/i, /\bSTARBUCKS\b/i] },
  { category: "Lazer", patterns: [/\bCINEMARK\b/i, /\bKINOPLEX\b/i, /\bINGRESSO\b/i, /\bSYMPLA\b/i, /\bEVENTIM\b/i] },
];

const providerAliases: Record<string, string[]> = {
  "Moradia": ["Housing", "Rent", "Condominium"],
  "Contas da casa": ["Utilities", "Electricity", "Water", "Internet", "Telephone", "Telecommunications"],
  "Mercado": ["Groceries", "Supermarket", "Supermarkets", "Grocery"],
  "Restaurantes": ["Restaurants", "Food and drinks", "Food and beverages", "Restaurant"],
  "Delivery": ["Food delivery", "Delivery"],
  "Transporte": ["Transportation", "Transport", "Public transportation", "Taxi", "Ride sharing"],
  "Combustível": ["Fuel", "Gas stations"],
  "Saúde e bem-estar": ["Health", "Healthcare", "Pharmacy", "Fitness", "Wellness"],
  "Educação": ["Education"], "Assinaturas": ["Subscriptions"],
  "Lazer": ["Entertainment", "Leisure"], "Compras": ["Shopping", "Electronics"],
  "Vestuário": ["Clothing"], "Cuidados pessoais": ["Personal care"], "Pets": ["Pets"],
  "Viagem": ["Travel"], "Tarifas e impostos": ["Bank fees", "Fees", "Taxes"],
  "Juros e encargos": ["Interest", "Interest and charges"],
  "Presentes e doações": ["Gifts", "Donations"], "Outros gastos": ["Other expenses"],
  "Salário": ["Salary", "Payroll", "Wages"], "Outras receitas": ["Income", "Other income"],
  "Transferência entre contas": ["Transfers", "Account transfer"],
  "Pagamento de fatura": ["Credit card payment"], "Aplicação e resgate": ["Investments", "Investment"],
};
const providerMap = new Map(Object.entries(providerAliases).flatMap(([category, aliases]) =>
  [category, ...aliases].map((alias) => [normalizeDescription(alias), category] as const)));
const providerLabels = new Map(Object.entries(providerAliases).flatMap(([category, aliases]) =>
  [category, ...aliases].map((alias) => [normalizeDescription(alias), alias] as const)));

export function mapProviderCategory(value: string | null, _now: Date): string | undefined {
  return value ? providerMap.get(normalizeDescription(value)) : undefined;
}
export function providerCategoryHint(value: string | null, _now: Date): string | null {
  return value ? providerLabels.get(normalizeDescription(value)) ?? null : null;
}

export function systemCategory(descriptionRaw: string, amountCents: number, merchantKey: string, _now: Date): string | undefined {
  if (merchantKey === "PIX PROPRIA") return "Transferência entre contas";
  const descriptionNorm = normalizeDescription(descriptionRaw);
  return SYSTEM_RULES.find((rule) => (!("incomingOnly" in rule) || amountCents > 0) && rule.patterns.some((p) => p.test(descriptionNorm)))?.category;
}

export function prepareCategorization(items: CategorizationItem[], catalog: CategoryCatalog,
  rules: Pick<CategoryRule, "merchantKey" | "categoryId">[], now: Date) {
  const decisions: CategorizationDecision[] = [];
  const pending: CategorizationItem[] = [];
  const ruleMap = new Map(rules.map((r) => [r.merchantKey, r.categoryId]));
  for (const item of items) {
    if (item.categorySource === "user") continue;
    const userCategory = ruleMap.get(item.merchantKey);
    const systemName = userCategory ? undefined : systemCategory(item.descriptionRaw, item.amountCents, item.merchantKey, now);
    const categoryId = userCategory ?? catalog.find((c) => c.name === systemName)?.id;
    if (categoryId) decisions.push({ id: item.id, categoryId, categorySource: userCategory ? "user_rule" : "system_rule", categoryConfidence: null });
    else pending.push(item);
  }
  return { decisions, pending };
}

const predictionSchema = z.array(z.object({
  id: z.string(), categoryName: z.string(), confidence: z.number().min(0).max(1),
}).strict()).max(50);
export function parseCategoryResponse(text: string, ids: string[], categoryNames: string[], _now: Date): CategoryPrediction[] | null {
  try {
    const parsed = predictionSchema.parse(JSON.parse(text));
    if (parsed.length !== ids.length || new Set(parsed.map((r) => r.id)).size !== ids.length
      || parsed.some((r) => !ids.includes(r.id) || !categoryNames.includes(r.categoryName))) return null;
    return parsed;
  } catch { return null; }
}

export function finishCategorization(items: CategorizationItem[], predictions: CategoryPrediction[], catalog: CategoryCatalog, now: Date): CategorizationDecision[] {
  const byId = new Map(predictions.map((r) => [r.id, r]));
  return items.filter((item) => item.categorySource !== "user").map((item): CategorizationDecision => {
    const prediction = byId.get(item.id);
    const aiCategory = prediction && prediction.confidence >= 0.6 ? catalog.find((c) => c.name === prediction.categoryName) : undefined;
    const providerCategory = catalog.find((c) => c.name === mapProviderCategory(item.providerCategory, now));
    const fallback = catalog.find((c) => c.name === (item.amountCents > 0 ? "Outras receitas" : "A revisar"));
    const chosen = aiCategory ?? providerCategory ?? fallback;
    if (!chosen) throw new Error("Category seed is incomplete.");
    return { id: item.id, categoryId: chosen.id, categorySource: aiCategory ? "ai" : providerCategory ? "provider" : "default", categoryConfidence: aiCategory ? prediction!.confidence : null };
  });
}
