import { and, eq, getTableColumns, inArray, isNull, or } from "drizzle-orm";
import type { DatabaseTransaction } from "../db/types";
import { accounts, bills, categories, debts, recurrences, transactions } from "@workspace/shared/schema";
import { localDate } from "../lib/dates";
import { reconcileBillsAndTransfers, type FinancialTransaction } from "../services/bill-transfers";
import { calculateInstallments } from "../services/installments";
import { detectMonthlyRecurrences } from "../services/recurrences";
import { planDetectedDebts } from "../services/debts";

async function readTransactions(tx: DatabaseTransaction, userId: string) {
  return tx.select({
    ...getTableColumns(transactions),
    accountType: accounts.type,
    accountName: accounts.name,
    categoryName: categories.name,
    categoryKind: categories.kind,
  }).from(transactions)
    .innerJoin(accounts, and(eq(accounts.id, transactions.accountId), eq(accounts.userId, userId)))
    .innerJoin(categories, and(eq(categories.id, transactions.categoryId), or(isNull(categories.userId), eq(categories.userId, userId))))
    .where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt)));
}

function changed<T extends object>(original: T, update: Partial<T>): boolean {
  return Object.entries(update).some(([key, value]) => original[key as keyof T] !== value);
}

export async function runFinancialRules(tx: DatabaseTransaction, userId: string, now: Date): Promise<void> {
  const today = localDate(now);
  const systemCategories = await tx.select().from(categories).where(or(isNull(categories.userId), eq(categories.userId, userId)));
  const userBills = await tx.select().from(bills).where(eq(bills.userId, userId));
  const initialTransactions = await readTransactions(tx, userId);

  const paymentAndTransfer = reconcileBillsAndTransfers(
    initialTransactions as FinancialTransaction[], userBills, systemCategories, today,
  );
  const initialById = new Map(initialTransactions.map((transaction) => [transaction.id, transaction]));
  for (const update of paymentAndTransfer.transactions) {
    const original = initialById.get(update.id);
    if (!original || !changed(original, update)) continue;
    const { id, ...fields } = update;
    await tx.update(transactions).set({ ...fields, updatedAt: now })
      .where(and(eq(transactions.userId, userId), eq(transactions.id, id), isNull(transactions.deletedAt)));
  }
  const billsById = new Map(userBills.map((bill) => [bill.id, bill]));
  for (const update of paymentAndTransfer.bills) {
    const original = billsById.get(update.id);
    if (!original || (original.paidCents === update.paidCents && original.status === update.status)) continue;
    await tx.update(bills).set({ paidCents: update.paidCents, status: update.status, updatedAt: now })
      .where(and(eq(bills.userId, userId), eq(bills.id, update.id)));
  }

  const afterBillAndTransfer = await readTransactions(tx, userId);
  const installmentResult = calculateInstallments(afterBillAndTransfer, 1, now);
  const installmentRows = new Map(afterBillAndTransfer.map((transaction) => [transaction.id, transaction]));
  for (const update of installmentResult.updates) {
    const original = installmentRows.get(update.id);
    if (!original || !changed(original, update)) continue;
    const { id, ...fields } = update;
    await tx.update(transactions).set({ ...fields, updatedAt: now })
      .where(and(eq(transactions.userId, userId), eq(transactions.id, id), isNull(transactions.deletedAt)));
  }

  const finalTransactions = await readTransactions(tx, userId);
  const existingRecurrences = await tx.select().from(recurrences).where(eq(recurrences.userId, userId));
  const candidates = detectMonthlyRecurrences(finalTransactions, existingRecurrences, now);
  for (const candidate of candidates) {
    const [existing] = await tx.select().from(recurrences).where(and(
      eq(recurrences.userId, userId), eq(recurrences.merchantKey, candidate.merchantKey),
    )).limit(1);
    if (existing?.status === "ignored" || existing?.source === "user") continue;
    let recurrenceId = existing?.id;
    if (existing) {
      const { transactionIds: _ids, ...fields } = candidate;
      if (changed(existing, fields)) {
        await tx.update(recurrences).set({ ...fields, updatedAt: now })
          .where(and(eq(recurrences.userId, userId), eq(recurrences.id, existing.id)));
      }
    } else {
      const { transactionIds: _ids, ...fields } = candidate;
      const [created] = await tx.insert(recurrences).values({ ...fields, userId, createdAt: now, updatedAt: now }).returning({ id: recurrences.id });
      recurrenceId = created?.id;
    }
    if (!recurrenceId) continue;
    const linked = finalTransactions.filter((transaction) =>
      candidate.transactionIds.includes(transaction.id) && transaction.recurrenceId !== recurrenceId).map((transaction) => transaction.id);
    if (linked.length) {
      await tx.update(transactions).set({ recurrenceId, updatedAt: now })
        .where(and(eq(transactions.userId, userId), inArray(transactions.id, linked), isNull(transactions.deletedAt)));
    }
  }

  const [debtAccounts, existingDebts] = await Promise.all([
    tx.select({
      id: accounts.id,
      name: accounts.name,
      type: accounts.type,
      balanceCents: accounts.balanceCents,
    }).from(accounts).where(eq(accounts.userId, userId)),
    tx.select({
      id: debts.id,
      accountId: debts.accountId,
      kind: debts.kind,
      source: debts.source,
      confirmed: debts.confirmed,
      monthlyRateBps: debts.monthlyRateBps,
      rateIsEstimated: debts.rateIsEstimated,
    }).from(debts).where(eq(debts.userId, userId)),
  ]);
  const debtPlan = planDetectedDebts({
    today,
    accounts: debtAccounts,
    bills: userBills,
    existingDebts,
  });
  for (const { candidate, existing, preserveRate } of debtPlan.upserts) {
    const values = {
      userId,
      name: candidate.name,
      kind: candidate.kind,
      balanceCents: candidate.balanceCents,
      monthlyRateBps: preserveRate ? existing!.monthlyRateBps : candidate.monthlyRateBps,
      rateIsEstimated: preserveRate ? existing!.rateIsEstimated : candidate.rateIsEstimated,
      minimumPaymentCents: candidate.minimumPaymentCents,
      source: "detected" as const,
      accountId: candidate.accountId,
      confirmed: existing?.confirmed ?? false,
      updatedAt: now,
    };
    if (existing) {
      await tx.update(debts).set(values)
        .where(and(eq(debts.userId, userId), eq(debts.id, existing.id)));
    } else {
      await tx.insert(debts).values({ ...values, createdAt: now });
    }
  }
  for (const id of debtPlan.removeIds) {
    await tx.delete(debts).where(and(eq(debts.userId, userId), eq(debts.id, id), eq(debts.confirmed, false)));
  }
  for (const id of debtPlan.zeroIds) {
    await tx.update(debts).set({ balanceCents: 0, updatedAt: now })
      .where(and(eq(debts.userId, userId), eq(debts.id, id), eq(debts.confirmed, true)));
  }
}
