import { normalizeDescription, plainName, sha1 } from "../services/normalization";
import { providerCategoryHint, type CategorizationItem } from "../services/categorization";
import { asDate, TIMEZONE } from "../lib/dates";

export function maskSensitiveText(value: string, personNames: string[] = []): string {
  const names = personNames.flatMap((name) => normalizeDescription(name).split(" "));
  return redactSensitiveText(normalizeDescription(redactSensitiveText(value, names)), []);
}

export type AssistantPerson = { name: string; merchantKey: string };

export function assistantPersonMap(people: AssistantPerson[]): {
  names: string[];
  privateNamesByKey: Map<string, string>;
} {
  const privateNamesByKey = new Map<string, string>();
  for (const person of people) {
    if (/^PIX P-[a-f0-9]{6}$/i.test(person.merchantKey)) {
      privateNamesByKey.set(person.merchantKey.toUpperCase(), person.name);
    }
  }
  return { names: [...new Set(people.map((person) => person.name).filter(Boolean))], privateNamesByKey };
}

export function maskAssistantUserMessage(value: string, userName: string | null, people: AssistantPerson[]): string {
  let safe = value;
  const entries = people
    .map((person) => ({ name: person.name, key: person.merchantKey }))
    .filter((person) => person.name && person.key)
    .sort((a, b) => b.name.length - a.name.length);
  if (userName) entries.unshift({ name: userName, key: "você" });
  for (const person of entries) {
    const escaped = person.name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    safe = safe.replace(new RegExp(`\\b${escaped}\\b`, "gi"), person.key);
  }
  return redactSensitiveText(safe, []);
}

function containsUntrustedInstruction(value: string): boolean {
  return /\b(?:ignore\s+(?:as?\s+)?(?:regras|instru[cç][oõ]es)|ignore\s+(?:all|previous)\s+(?:rules|instructions)|desconsidere\s+(?:as\s+)?(?:regras|instru[cç][oõ]es)|revele\s+(?:o\s+)?prompt|mostre\s+(?:o\s+)?prompt)\b/i.test(value);
}

function redactSensitiveText(value: string, personNames: string[]): string {
  let safe = value
    .replace(/\S*@\S+(?:\s+[A-Z]{2,})?/gi, "[EMAIL]")
    .replace(/(?<!\d)\d{3}[\s.]?\d{3}[\s.]?\d{3}[\s-]?\d{2}(?!\d)/g, "[DOCUMENTO]")
    .replace(/(?:\+?55[\s-]*)?\(?\d{2}\)?[\s-]*9?\d{4}[\s-]*\d{4}\b/g, "[TELEFONE]")
    .replace(/\b(?:AG(?:ENCIA)?|CONTA|CC)\s*[:.-]?\s*\d[\d\s.-]*/gi, "[CONTA]")
    .replace(/\b\d{3}\s+\d{3}\s+\d{3}\b/g, "[DOCUMENTO]")
    .replace(/\d{6,}/g, "[NUMERO]");
  for (const name of personNames) {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    safe = safe.replace(new RegExp(`\\b${escaped}\\b`, "gi"), "[PESSOA]");
  }
  return safe;
}

export function maskAssistantTransaction<T extends {
  id: string;
  date: string;
  merchantKey: string;
  merchantName: string | null;
  descriptionRaw: string;
  amountCents: number;
  categoryName: string;
  accountName: string;
  counterpartType: string | null;
  counterpartName: string | null;
}>(transaction: T, personNames: string[]) {
  const isPerson = transaction.counterpartType === "person";
  const maskedDescription = maskSensitiveText(transaction.descriptionRaw, personNames);
  const descriptionHasUntrustedText = containsUntrustedInstruction(maskedDescription);
  const personKey = /^PIX P-[a-f0-9]{6}$/i.test(transaction.merchantKey)
    ? transaction.merchantKey.toUpperCase()
    : isPerson
      ? `PIX P-${sha1(plainName(transaction.counterpartName ?? transaction.merchantKey)).slice(0, 6)}`
      : null;
  return {
    id: transaction.id,
    date: transaction.date,
    merchantName: isPerson ? personKey! : maskSensitiveText(transaction.merchantName ?? transaction.merchantKey, personNames),
    description: isPerson ? personKey! : descriptionHasUntrustedText
      ? "[TEXTO DA DESCRIÇÃO OMITIDO: INSTRUÇÃO NÃO CONFIÁVEL]"
      : maskedDescription,
    descriptionHasUntrustedText,
    amountCents: transaction.amountCents,
    categoryName: maskSensitiveText(transaction.categoryName, personNames),
    accountName: maskSensitiveText(transaction.accountName, personNames),
  };
}

export function categorizationInput(item: CategorizationItem, userName: string, now: Date) {
  const personNames = [userName, ...(item.counterpartType === "person" && item.counterpartName ? [item.counterpartName] : [])];
  const personKey = item.counterpartType === "person";
  const merchantKey = /^PIX P-[a-f0-9]{6}$/.test(item.merchantKey) || item.merchantKey === "PIX PROPRIA" ? item.merchantKey
    : personKey ? `PESSOA P-${sha1(plainName(item.counterpartName ?? item.merchantKey)).slice(0, 6)}`
    : maskSensitiveText(item.merchantKey, personNames);
  return {
    id: item.id, merchantKey, amountCents: item.amountCents, date: item.date,
    weekday: new Intl.DateTimeFormat("pt-BR", { weekday: "long", timeZone: TIMEZONE }).format(asDate(item.date)),
    paymentMethod: item.paymentMethod, counterpartType: item.counterpartType,
    // Only known taxonomy labels can be hints: free-form provider metadata may contain PII.
    providerCategory: providerCategoryHint(item.providerCategory, now),
  };
}
export type CategorizationInput = ReturnType<typeof categorizationInput>;
