import { createApp } from "./app";
import { logger } from "./lib/logger";
import { startSyncSchedule } from "./jobs/schedule";
import { startAlertSchedules } from "./jobs/alert-schedules";

const rawPort = process.env["PORT"];

if (!rawPort) {
  throw new Error(
    "PORT environment variable is required but was not provided.",
  );
}

const port = Number(rawPort);

if (Number.isNaN(port) || port <= 0) {
  throw new Error(`Invalid PORT value: "${rawPort}"`);
}

const app = createApp();
app.listen(port, (err) => {
  if (err) {
    logger.error({ errorName: err instanceof Error ? err.name : "UnknownError" }, "Error listening on port");
    process.exit(1);
  }

  logger.info({ port }, "Server listening");
  startSyncSchedule();
  startAlertSchedules();
});
