import { addDays, asDate, localDate } from "../lib/dates";

export type WeeklySummaryTransaction = {
  id: string;
  date: string;
  amountCents: number;
  categoryKind: "expense" | "income" | "transfer" | "review";
  categoryName: string;
  recurrenceId: string | null;
  isTransfer: boolean;
  isBillPayment: boolean;
  deletedAt: Date | null;
};

export type WeeklySummaryRecurrence = {
  id: string;
  label: string;
  status: "active" | "ignored";
};

export type WeeklySummaryPayload = {
  weekStart: string;
  weekEnd: string;
  spendCents: number;
  previousFourWeeksAverageCents: number;
  differenceCents: number;
  differencePercent: number | null;
  topCategories: { name: string; amountCents: number }[];
  recurrencesCharged: { label: string; amountCents: number }[];
};

function mondayOf(day: string): string {
  const weekday = asDate(day).getUTCDay();
  return addDays(day, -((weekday + 6) % 7));
}

function isSpend(row: WeeklySummaryTransaction): boolean {
  return row.deletedAt === null && row.amountCents < 0 &&
    (row.categoryKind === "expense" || row.categoryKind === "review") &&
    !row.isTransfer && !row.isBillPayment;
}

export function calculateWeeklySummary(
  transactions: WeeklySummaryTransaction[],
  recurrences: WeeklySummaryRecurrence[],
  now: Date,
): WeeklySummaryPayload {
  const today = localDate(now);
  const weekStart = mondayOf(today);
  const weekEnd = addDays(weekStart, 6);
  const previousStart = addDays(weekStart, -28);
  const spend = (start: string, end: string) => transactions
    .filter((row) => isSpend(row) && row.date >= start && row.date <= end && row.date <= today)
    .reduce((sum, row) => sum + Math.abs(row.amountCents), 0);

  const spendCents = spend(weekStart, weekEnd);
  const previousFourWeeksAverageCents = Math.round(spend(previousStart, addDays(weekStart, -1)) / 4);
  const differenceCents = spendCents - previousFourWeeksAverageCents;
  const differencePercent = previousFourWeeksAverageCents === 0
    ? null
    : Math.round((differenceCents / previousFourWeeksAverageCents) * 1000) / 10;
  const categories = new Map<string, number>();
  const activeRecurrences = new Map(recurrences.filter((row) => row.status === "active").map((row) => [row.id, row.label]));
  const recurringCharges = new Map<string, number>();
  for (const row of transactions) {
    if (!isSpend(row) || row.date < weekStart || row.date > weekEnd || row.date > today) continue;
    categories.set(row.categoryName, (categories.get(row.categoryName) ?? 0) + Math.abs(row.amountCents));
    if (row.recurrenceId && activeRecurrences.has(row.recurrenceId)) {
      const label = activeRecurrences.get(row.recurrenceId)!;
      recurringCharges.set(label, (recurringCharges.get(label) ?? 0) + Math.abs(row.amountCents));
    }
  }
  const topCategories = [...categories].map(([name, amountCents]) => ({ name, amountCents }))
    .sort((a, b) => b.amountCents - a.amountCents || a.name.localeCompare(b.name, "pt-BR"))
    .slice(0, 3);
  const recurrencesCharged = [...recurringCharges].map(([label, amountCents]) => ({ label, amountCents }))
    .sort((a, b) => b.amountCents - a.amountCents || a.label.localeCompare(b.label, "pt-BR"));
  return {
    weekStart, weekEnd, spendCents, previousFourWeeksAverageCents,
    differenceCents, differencePercent, topCategories, recurrencesCharged,
  };
}

export function limitWeeklySummaryText(text: string): string {
  const normalized = text.trim().replace(/\s+/g, " ");
  if (!normalized || normalized.length > 800) throw new Error("Invalid weekly summary text.");
  const sentences = normalized.match(/[^.!?]+[.!?]+|[^.!?]+$/g)?.map((part) => part.trim()).filter(Boolean) ?? [];
  const limited = sentences.slice(0, 4).join(" ");
  if (!limited) throw new Error("Invalid weekly summary text.");
  return limited;
}
