import { Router, type IRouter, type Request } from "express";
import { z } from "zod/v4";
import {
  GetAllowanceResponse,
  GetDashboardHomeResponse,
  GetProjectionResponse,
} from "@workspace/api-zod";
import { loadDashboardHome } from "../db/queries/dashboard";
import { apiError } from "../lib/errors";
import { requireAuth } from "../middlewares/security";

const router: IRouter = Router();
router.use(requireAuth);

function noQueryParameters(req: Request): boolean {
  return z.object({}).strict().safeParse(req.query).success;
}

router.get("/allowance", async (req, res): Promise<void> => {
  if (!noQueryParameters(req)) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const dashboard = await loadDashboardHome(req.session.userId!, new Date());
  if (!dashboard) {
    apiError(res, 401, "UNAUTHENTICATED", "Entre na sua conta para continuar.");
    return;
  }
  res.json(GetAllowanceResponse.parse({ data: dashboard.allowance }));
});

