import { and, asc, eq, getTableColumns, gte, isNull, lt, or } from "drizzle-orm";
import { budgets, categories, transactions } from "@workspace/shared/schema";
import { addMonths, monthDate } from "../../lib/dates";
import { calculateBudgetProgress } from "../../services/budgets";
import { db } from "../connection";

export async function loadBudgetEntries(userId: string, month: string) {
  const startDate = monthDate(month, 1);
  const endDate = addMonths(startDate, 1);
  const [budgetRows, spendRows] = await Promise.all([
    db.select({
      id: budgets.id,
      categoryId: budgets.categoryId,
      categoryName: categories.name,
      color: categories.color,
      month: budgets.month,
      limitCents: budgets.limitCents,
    }).from(budgets).innerJoin(categories, and(
      eq(categories.id, budgets.categoryId),
      or(isNull(categories.userId), eq(categories.userId, userId)),
    )).where(and(eq(budgets.userId, userId), eq(budgets.month, month)))
      .orderBy(asc(categories.sortOrder), asc(categories.name)),
    db.select({
      ...getTableColumns(transactions),
      categoryKind: categories.kind,
    }).from(transactions).innerJoin(categories, and(
      eq(categories.id, transactions.categoryId),
      or(isNull(categories.userId), eq(categories.userId, userId)),
    )).where(and(
      eq(transactions.userId, userId),
      gte(transactions.date, startDate),
      lt(transactions.date, endDate),
    )),
  ]);
  return calculateBudgetProgress(budgetRows, spendRows);
}
