import type { Account, Bill, Category, Transaction } from "@workspace/shared/schema";
import { normalizeDescription } from "./normalization";
import { asDate } from "../lib/dates";

export type FinancialTransaction = Pick<Transaction,
  "id" | "userId" | "accountId" | "date" | "descriptionRaw" | "merchantKey" | "merchantName" |
  "amountCents" | "categoryId" | "categorySource" | "isTransfer" | "transferPairId" |
  "isBillPayment" | "billId" | "installmentNumber" | "installmentTotal" | "installmentGroupKey" |
  "recurrenceId" | "deletedAt"
> & { accountType: Account["type"]; categoryName: string | null; categoryKind: Category["kind"] | null };

export type TransactionRuleUpdate = Pick<Transaction, "id"> & Partial<Pick<Transaction,
  "isTransfer" | "transferPairId" | "isBillPayment" | "billId" | "categoryId" | "categorySource"
>>;
export type BillRuleUpdate = Pick<Bill, "id" | "paidCents" | "status">;

const daysBetween = (a: string, b: string) => Math.abs(asDate(a).getTime() - asDate(b).getTime()) / 86_400_000;
const amountMatchesBill = (amountCents: number, bill: Bill) =>
  Math.abs(Math.abs(amountCents) - bill.totalCents) <= 100 ||
  (bill.minimumPaymentCents !== null && Math.abs(Math.abs(amountCents) - bill.minimumPaymentCents) <= 100);

export function isExpenseTransaction(transaction: Pick<Transaction, "amountCents" | "deletedAt" | "isTransfer" | "isBillPayment">, categoryKind: string | null): boolean {
  return transaction.amountCents < 0 && transaction.deletedAt === null && !transaction.isTransfer &&
    !transaction.isBillPayment && (categoryKind === "expense" || categoryKind === "review");
}

export function isIncomeTransaction(transaction: Pick<Transaction, "amountCents" | "deletedAt" | "isTransfer" | "isBillPayment">, categoryKind: string | null): boolean {
  return transaction.amountCents > 0 && transaction.deletedAt === null && !transaction.isTransfer &&
    !transaction.isBillPayment && categoryKind === "income";
}

export function reconcileBillsAndTransfers(
  transactions: FinancialTransaction[],
  bills: Bill[],
  categories: Category[],
  today: string,
): { transactions: TransactionRuleUpdate[]; bills: BillRuleUpdate[] } {
  const categoryById = new Map(categories.map((category) => [category.id, category]));
  const billCategory = categories.find((category) => category.userId === null && category.name === "Pagamento de fatura");
  const transferCategory = categories.find((category) => category.userId === null && category.name === "Transferência entre contas");
  const active = transactions.filter((transaction) => transaction.deletedAt === null);
  const changes = new Map<string, Partial<TransactionRuleUpdate>>();
  const set = (id: string, update: Partial<TransactionRuleUpdate>) => changes.set(id, { ...changes.get(id), ...update });
  const effective = (transaction: FinancialTransaction) => ({ ...transaction, ...changes.get(transaction.id) });

  for (const transaction of active) {
    let payment = false;
    let matchedBill: Bill | undefined;
    const description = normalizeDescription(transaction.descriptionRaw);
    if (transaction.accountType === "credit_card" && transaction.amountCents > 0 && /\bPAGAMENTO RECEBIDO\b/.test(description)) {
      payment = true;
      const candidates = bills.filter((bill) => bill.accountId === transaction.accountId && daysBetween(bill.dueDate, transaction.date) <= 3);
      matchedBill = candidates.find((bill) => bill.id === transaction.billId) ??
        candidates.sort((a, b) => daysBetween(a.dueDate, transaction.date) - daysBetween(b.dueDate, transaction.date) || a.id.localeCompare(b.id))[0];
    } else if (transaction.accountType !== "credit_card" && transaction.amountCents < 0) {
      const categorizedAsPayment = transaction.categoryId === billCategory?.id ||
        categoryById.get(transaction.categoryId)?.name === "Pagamento de fatura";
      const candidates = bills.filter((bill) => daysBetween(bill.dueDate, transaction.date) <= 3);
      const coincident = candidates.filter((bill) => amountMatchesBill(transaction.amountCents, bill))
        .sort((a, b) => daysBetween(a.dueDate, transaction.date) - daysBetween(b.dueDate, transaction.date) || a.id.localeCompare(b.id));
      matchedBill = coincident[0] ?? (categorizedAsPayment
        ? candidates.sort((a, b) => daysBetween(a.dueDate, transaction.date) - daysBetween(b.dueDate, transaction.date) || a.id.localeCompare(b.id))[0]
        : undefined);
      payment = categorizedAsPayment || coincident.length > 0;
    }
    const billId = payment ? matchedBill?.id ?? null : transaction.isBillPayment ? null : transaction.billId;
    if (payment !== transaction.isBillPayment || billId !== transaction.billId) set(transaction.id, { isBillPayment: payment, billId });
  }

  const eligible = active.map(effective);
  const byPair = new Map<string, FinancialTransaction[]>();
  for (const transaction of eligible) {
    if (!transaction.transferPairId) continue;
    const pair = byPair.get(transaction.transferPairId) ?? [];
    pair.push(transaction as FinancialTransaction);
    byPair.set(transaction.transferPairId, pair);
  }
  const pairedIds = new Set<string>();
  for (const [pairId, pair] of byPair) {
    const [a, b] = pair;
    const valid = pair.length === 2 && a && b && a.id !== b.id && !a.isBillPayment && !b.isBillPayment &&
      a.accountId !== b.accountId && a.amountCents === -b.amountCents && daysBetween(a.date, b.date) <= 2;
    if (valid) {
      pairedIds.add(a!.id);
      pairedIds.add(b!.id);
      for (const transaction of [a!, b!]) {
        set(transaction.id, {
          isTransfer: true,
          transferPairId: pairId,
          ...(transaction.categorySource !== "user" && transferCategory
            ? { categoryId: transferCategory.id, categorySource: "system_rule" as const }
            : {}),
        });
      }
    } else {
      for (const transaction of pair) {
        set(transaction.id, { isTransfer: false, transferPairId: null });
      }
    }
  }

  const candidates = eligible.filter((transaction) =>
    !transaction.isBillPayment && !transaction.isTransfer && !transaction.transferPairId && !pairedIds.has(transaction.id) && transaction.amountCents !== 0);
  const pairs: { a: FinancialTransaction; b: FinancialTransaction; distance: number }[] = [];
  for (let i = 0; i < candidates.length; i++) {
    const a = candidates[i]!;
    for (let j = i + 1; j < candidates.length; j++) {
      const b = candidates[j]!;
      if (a.accountId === b.accountId || Math.sign(a.amountCents) === Math.sign(b.amountCents) ||
        Math.abs(a.amountCents) !== Math.abs(b.amountCents)) continue;
      const distance = daysBetween(a.date, b.date);
      if (distance <= 2) pairs.push({ a, b, distance });
    }
  }
  pairs.sort((a, b) => a.distance - b.distance ||
    a.a.id.localeCompare(b.a.id) || a.b.id.localeCompare(b.b.id));
  const used = new Set(pairedIds);
  for (const { a, b } of pairs) {
    if (used.has(a.id) || used.has(b.id)) continue;
    const pairId = [a.id, b.id].sort()[0]!;
    used.add(a.id);
    used.add(b.id);
    for (const transaction of [a, b]) {
      set(transaction.id, {
        isTransfer: true,
        transferPairId: pairId,
        ...(transaction.categorySource !== "user" && transferCategory
          ? { categoryId: transferCategory.id, categorySource: "system_rule" as const }
          : {}),
      });
    }
  }

  const reconciled = active.map(effective);
  const billUpdates = bills.map((bill) => {
    const cardPayments = reconciled.filter((transaction) =>
      transaction.accountId === bill.accountId && transaction.accountType === "credit_card" &&
      transaction.isBillPayment && transaction.billId === bill.id && transaction.amountCents > 0);
    const paidCents = cardPayments.length
      ? cardPayments.reduce((sum, transaction) => sum + transaction.amountCents, 0)
      : reconciled.filter((transaction) =>
        transaction.accountType !== "credit_card" && transaction.isBillPayment &&
        transaction.billId === bill.id && transaction.amountCents < 0)
        .reduce((sum, transaction) => sum + Math.abs(transaction.amountCents), 0);
    const status: Bill["status"] = paidCents >= bill.totalCents ? "paid"
      : paidCents > 0 && bill.dueDate <= today ? "partially_paid"
        : bill.closeDate <= today ? "closed" : "open";
    return { id: bill.id, paidCents, status };
  });
  return {
    transactions: [...changes.entries()].map(([id, fields]) => ({ id, ...fields })),
    bills: billUpdates,
  };
}
