import { and, eq, inArray, isNull, ne, or, sql } from "drizzle-orm";
import { categories, categoryRules, transactions } from "@workspace/shared/schema";
import { db } from "../connection";
import { planTransactionCorrection, type TransactionCorrection } from "../../services/transaction-corrections";

export class CorrectionError extends Error {
  constructor(public code: "NOT_FOUND" | "CATEGORY_NOT_FOUND") { super(code); }
}
export async function correctTransaction(userId: string, id: string, update: TransactionCorrection, now: Date) {
  return db.transaction(async (tx) => {
    // The same lock as imports: automatic categorization cannot race a manual edit.
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
    const [target] = await tx.select().from(transactions).where(and(eq(transactions.userId, userId), eq(transactions.id, id), isNull(transactions.deletedAt))).limit(1);
    if (!target) throw new CorrectionError("NOT_FOUND");
    if (update.categoryId) {
      const [category] = await tx.select({ id: categories.id }).from(categories).where(and(eq(categories.id, update.categoryId), or(isNull(categories.userId), eq(categories.userId, userId)))).limit(1);
      if (!category) throw new CorrectionError("CATEGORY_NOT_FOUND");
    }
    const similar = update.applyToSimilar ? await tx.select().from(transactions).where(and(
      eq(transactions.userId, userId), eq(transactions.merchantKey, target.merchantKey),
      ne(transactions.categorySource, "user"), isNull(transactions.deletedAt),
    )) : [];
    const plan = planTransactionCorrection(target, similar, update, now);
    if (plan.selectedChanged) await tx.update(transactions).set(plan.selected).where(and(eq(transactions.userId, userId), eq(transactions.id, id)));
    if (update.applyToSimilar && update.categoryId) {
      await tx.insert(categoryRules).values({ userId, merchantKey: target.merchantKey, categoryId: update.categoryId, createdFromTransactionId: id, createdAt: now, updatedAt: now })
        .onConflictDoUpdate({ target: [categoryRules.userId, categoryRules.merchantKey], set: { categoryId: update.categoryId, createdFromTransactionId: id, updatedAt: now } });
      if (plan.similarIds.length) await tx.update(transactions).set({ categoryId: update.categoryId, categorySource: "user_rule", categoryConfidence: null, updatedAt: now })
        .where(and(eq(transactions.userId, userId), inArray(transactions.id, plan.similarIds), ne(transactions.categorySource, "user"), isNull(transactions.deletedAt)));
    }
    return plan.updatedCount;
  });
}
