import type { Transaction } from "@workspace/shared/schema";
import { addMonths, asDate, localDate, monthDate } from "../lib/dates";

export type InstallmentTransaction = Pick<Transaction,
  "id" | "accountId" | "date" | "descriptionRaw" | "merchantKey" | "merchantName" |
  "amountCents" | "installmentNumber" | "installmentTotal" | "installmentGroupKey" | "deletedAt"
> & { accountName: string };

export type InstallmentItem = {
  key: string;
  transactionId: string | null;
  accountId: string;
  accountName: string;
  merchantKey: string;
  label: string;
  date: string;
  amountCents: number;
  installmentNumber: number;
  installmentTotal: number;
  projected: boolean;
};
export type InstallmentMonth = { month: string; totalCents: number; items: InstallmentItem[] };
export type InstallmentUpdate = Pick<Transaction, "id"> & Partial<Pick<Transaction, "installmentNumber" | "installmentTotal" | "installmentGroupKey">>;
export type SimulatedInstallment = { date: string; installmentNumber: number; installmentTotal: number; amountCents: number };

type Parsed = InstallmentTransaction & { number: number; total: number; groupKey: string };

function parsedNumber(transaction: InstallmentTransaction): { number: number; total: number } | null {
  if (transaction.installmentNumber !== null || transaction.installmentTotal !== null) {
    const number = transaction.installmentNumber;
    const total = transaction.installmentTotal;
    return number !== null && total !== null && Number.isInteger(number) && Number.isInteger(total) &&
      number >= 1 && total >= 2 && number <= total ? { number, total } : null;
  }
  const match = transaction.descriptionRaw.match(/\bPARC(?:ELA)?\s?(\d{1,2})\s?(?:\/|DE)\s?(\d{1,2})\b/i);
  if (!match) return null;
  const number = Number(match[1]);
  const total = Number(match[2]);
  return number >= 1 && total >= 2 && number <= total ? { number, total } : null;
}

function installmentKey(transaction: InstallmentTransaction, number: number, total: number): string {
  const firstMonth = addMonths(transaction.date, -(number - 1)).slice(0, 7);
  return `${transaction.merchantKey}|${Math.abs(transaction.amountCents)}|${total}|${transaction.accountId}|${firstMonth}`;
}

function normalize(transaction: InstallmentTransaction): Parsed | null {
  if (transaction.deletedAt !== null) return null;
  const parsed = parsedNumber(transaction);
  if (!parsed) return null;
  return { ...transaction, ...parsed, groupKey: installmentKey(transaction, parsed.number, parsed.total) };
}

function monthRange(now: Date, months: number) {
  const start = monthDate(localDate(now), 1);
  return { start, end: addMonths(start, months) };
}

export function calculateInstallments(transactions: InstallmentTransaction[], months: number, now: Date): {
  updates: InstallmentUpdate[];
  months: InstallmentMonth[];
} {
  const range = monthRange(now, months);
  const parsed = transactions.map(normalize).filter((value): value is Parsed => value !== null);
  const groups = new Map<string, Parsed[]>();
  for (const transaction of parsed) {
    const group = groups.get(transaction.groupKey) ?? [];
    group.push(transaction);
    groups.set(transaction.groupKey, group);
  }
  const parsedById = new Map(parsed.map((transaction) => [transaction.id, transaction]));
  const updates: InstallmentUpdate[] = [];
  for (const transaction of transactions) {
    const item = parsedById.get(transaction.id);
    if (item) updates.push({ id: item.id, installmentNumber: item.number, installmentTotal: item.total, installmentGroupKey: item.groupKey });
    else if (transaction.installmentNumber !== null || transaction.installmentTotal !== null || transaction.installmentGroupKey !== null) {
      updates.push({ id: transaction.id, installmentNumber: null, installmentTotal: null, installmentGroupKey: null });
    }
  }
  const monthMap = new Map<string, InstallmentMonth>();
  for (let offset = 0; offset < months; offset++) {
    const month = addMonths(range.start, offset).slice(0, 7);
    monthMap.set(month, { month, totalCents: 0, items: [] });
  }
  const addItem = (item: InstallmentItem) => {
    if (item.date < range.start || item.date >= range.end) return;
    const month = monthMap.get(item.date.slice(0, 7));
    if (!month) return;
    month.items.push(item);
    if (item.amountCents < 0) month.totalCents += Math.abs(item.amountCents);
  };
  for (const transaction of parsed) {
    addItem({
      key: `transaction:${transaction.id}`, transactionId: transaction.id,
      accountId: transaction.accountId, accountName: transaction.accountName,
      merchantKey: transaction.merchantKey, label: transaction.merchantName || transaction.merchantKey,
      date: transaction.date, amountCents: transaction.amountCents,
      installmentNumber: transaction.number, installmentTotal: transaction.total, projected: false,
    });
  }
  for (const [groupKey, group] of groups) {
    const lastNumber = Math.max(...group.map((item) => item.number));
    const lastRows = group.filter((item) => item.number === lastNumber).sort((a, b) => b.date.localeCompare(a.date) || a.id.localeCompare(b.id));
    const last = lastRows[0]!;
    for (let number = lastNumber + 1; number <= last.total; number++) {
      const date = addMonths(last.date, number - lastNumber);
      addItem({
        key: `projection:${groupKey}:${number}`, transactionId: null,
        accountId: last.accountId, accountName: last.accountName,
        merchantKey: last.merchantKey, label: last.merchantName || last.merchantKey,
        date, amountCents: last.amountCents, installmentNumber: number,
        installmentTotal: last.total, projected: true,
      });
    }
  }
  const data = [...monthMap.values()];
  for (const month of data) {
    month.items.sort((a, b) => a.date.localeCompare(b.date) || a.label.localeCompare(b.label) || a.installmentNumber - b.installmentNumber);
  }
  return { updates, months: data };
}

export function formatMonthLabel(month: string): string {
  const [year, monthNumber] = month.split("-").map(Number);
  return new Intl.DateTimeFormat("pt-BR", { month: "short", timeZone: "UTC" })
    .format(new Date(Date.UTC(year!, monthNumber! - 1, 1))).replace(".", "");
}

export function installmentProjectionDate(anchor: string, monthsAfter: number): string {
  const date = addMonths(anchor, monthsAfter);
  return asDate(date).toISOString().slice(0, 10);
}

export function simulatePurchaseInstallments(
  totalAmountCents: number,
  installmentCount: number,
  startDate: string,
): SimulatedInstallment[] {
  if (!Number.isSafeInteger(totalAmountCents) || totalAmountCents <= 0) {
    throw new Error("Purchase amount must be a positive integer in cents.");
  }
  if (!Number.isInteger(installmentCount) || installmentCount < 1 || installmentCount > 48) {
    throw new Error("Installment count must be between 1 and 48.");
  }
  const baseAmountCents = Math.floor(totalAmountCents / installmentCount);
  const extraCents = totalAmountCents % installmentCount;
  return Array.from({ length: installmentCount }, (_, index) => ({
    date: addMonths(startDate, index),
    installmentNumber: index + 1,
    installmentTotal: installmentCount,
    amountCents: -(baseAmountCents + (index < extraCents ? 1 : 0)),
  }));
}
