import type { Recurrence } from "@workspace/shared/schema";
import { addMonths, asDate, localDate, monthDate } from "../lib/dates";

export type RecurrenceTransaction = {
  id: string;
  accountId: string;
  date: string;
  merchantKey: string;
  merchantName: string | null;
  amountCents: number;
  isTransfer: boolean;
  isBillPayment: boolean;
  installmentNumber: number | null;
  installmentTotal: number | null;
  installmentGroupKey: string | null;
  recurrenceId: string | null;
  deletedAt: Date | null;
  categoryName: string | null;
  categoryKind: string | null;
};

export type RecurrenceCandidate = Pick<Recurrence,
  "accountId" | "kind" | "label" | "merchantKey" | "expectedAmountCents" |
  "previousAmountCents" | "frequency" | "dayOfMonth" | "nextExpectedDate" | "status" | "source"
> & { transactionIds: string[] };

const dayDifference = (a: string, b: string) => Math.abs(asDate(a).getTime() - asDate(b).getTime()) / 86_400_000;

function median(values: number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle]! : Math.round((sorted[middle - 1]! + sorted[middle]!) / 2);
}

function amountWithinMedian(values: number[]): boolean {
  const sorted = values.map(Math.abs).sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  const medianTwice = sorted.length % 2 ? BigInt(sorted[middle]!) * 2n : BigInt(sorted[middle - 1]!) + BigInt(sorted[middle]!);
  if (medianTwice === 0n) return false;
  return sorted.every((value) => {
    const distanceTwice = BigInt(value) * 2n - medianTwice;
    return (distanceTwice < 0n ? -distanceTwice : distanceTwice) * 100n <= medianTwice * 15n;
  });
}

function expectedDate(today: string, latestDate: string, dayOfMonth: number): string {
  const thisMonth = today.slice(0, 7);
  let candidateMonth = thisMonth;
  const candidateFor = (month: string) => {
    const first = monthDate(month, 1);
    const lastDay = new Date(Date.UTC(asDate(first).getUTCFullYear(), asDate(first).getUTCMonth() + 1, 0)).getUTCDate();
    return monthDate(month, Math.min(dayOfMonth, lastDay));
  };
  let candidate = candidateFor(candidateMonth);
  if (candidate < today || candidate <= latestDate) {
    candidateMonth = addMonths(monthDate(candidateMonth, 1), 1).slice(0, 7);
    candidate = candidateFor(candidateMonth);
  }
  return candidate;
}

export function detectMonthlyRecurrences(
  transactions: RecurrenceTransaction[],
  existing: Recurrence[],
  now: Date,
): RecurrenceCandidate[] {
  const today = localDate(now);
  const cutoff = addMonths(today, -6);
  const existingByKey = new Map(existing.map((recurrence) => [recurrence.merchantKey, recurrence]));
  const groups = new Map<string, RecurrenceTransaction[]>();
  for (const transaction of transactions) {
    if (transaction.deletedAt !== null || transaction.date < cutoff || transaction.date > today ||
      transaction.isTransfer || transaction.isBillPayment ||
      transaction.installmentNumber !== null || transaction.installmentTotal !== null ||
      transaction.installmentGroupKey !== null || transaction.categoryKind === "transfer" ||
      !transaction.merchantKey) continue;
    const group = groups.get(transaction.merchantKey) ?? [];
    group.push(transaction);
    groups.set(transaction.merchantKey, group);
  }
  const candidates: RecurrenceCandidate[] = [];
  for (const [merchantKey, rows] of groups) {
    const previous = existingByKey.get(merchantKey);
    if (previous?.status === "ignored" || previous?.source === "user") continue;
    const ordered = [...rows].sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id));
    const monthlyCounts = new Map<string, number>();
    for (const row of ordered) monthlyCounts.set(row.date.slice(0, 7), (monthlyCounts.get(row.date.slice(0, 7)) ?? 0) + 1);
    if ([...monthlyCounts.values()].some((count) => count > 1)) continue;
    const latest = ordered.at(-1)!;
    const subscription = latest.categoryName === "Assinaturas";
    if (ordered.length < (subscription ? 2 : 3)) continue;
    const intervals = ordered.slice(1).map((row, index) => dayDifference(row.date, ordered[index]!.date));
    if (intervals.some((days) => days < 25 || days > 35)) continue;
    if (!amountWithinMedian(ordered.map((row) => row.amountCents))) continue;
    const dayOfMonth = median(ordered.map((row) => Number(row.date.slice(8, 10))));
    const previousAmount = ordered.length > 1 ? ordered.at(-2)!.amountCents : null;
    candidates.push({
      accountId: latest.accountId,
      kind: latest.amountCents > 0 ? "income" : subscription ? "subscription" : "fixed_bill",
      label: latest.merchantName || merchantKey,
      merchantKey,
      expectedAmountCents: latest.amountCents,
      previousAmountCents: previousAmount,
      frequency: "monthly",
      dayOfMonth,
      nextExpectedDate: expectedDate(today, latest.date, dayOfMonth),
      status: "active",
      source: "detected",
      transactionIds: ordered.map((row) => row.id),
    });
  }
  return candidates;
}
