import cron from "node-cron";
import { logger } from "../lib/logger";
import { evaluateAlertsForAllUsers } from "./alerts";
import { createWeeklySummariesForAllUsers } from "./weekly-summary";

export function startAlertSchedules() {
  const dailyAlerts = cron.schedule("0 9 * * *", async () => {
    try {
      await evaluateAlertsForAllUsers(new Date());
    } catch {
      logger.warn("Daily alert evaluation job failed");
    }
  }, { timezone: "America/Sao_Paulo", noOverlap: true });

  const weeklySummary = cron.schedule("0 20 * * 0", async () => {
    try {
      await createWeeklySummariesForAllUsers(new Date());
    } catch {
      logger.warn("Weekly summary job failed");
    }
  }, { timezone: "America/Sao_Paulo", noOverlap: true });

  return [dailyAlerts, weeklySummary];
}
