import { addDays, addMonths, localDate, monthDate } from "../lib/dates";

export type ProjectionAccount = {
  type: "checking" | "savings" | "credit_card" | "cash";
  balanceCents: number;
};

export type ProjectionRecurrence = {
  id: string;
  kind: "subscription" | "fixed_bill" | "income";
  status: "active" | "ignored";
  expectedAmountCents: number;
  nextExpectedDate: string;
  accountType: ProjectionAccount["type"] | null;
};

export type ProjectionTransaction = {
  date: string;
  amountCents: number;
  categoryKind: "expense" | "income" | "transfer" | "review" | string;
  accountType: ProjectionAccount["type"];
  isTransfer: boolean;
  isBillPayment: boolean;
  recurrenceId: string | null;
  deletedAt: Date | string | null;
};

export type ProjectionBill = {
  dueDate: string;
  totalCents: number;
  paidCents: number;
};

export type ProjectionInput = {
  accounts: ProjectionAccount[];
  recurrences: ProjectionRecurrence[];
  transactions: ProjectionTransaction[];
  bills: ProjectionBill[];
};

export type ProjectionResult = {
  month: string;
  accountBalanceCents: number;
  expectedIncomeCents: number;
  fixedExpensesCents: number;
  billsDueCents: number;
  dailySpendAverageCents: number;
  remainingDaysAfterToday: number;
  expectedDailySpendCents: number;
  projectedBalanceCents: number;
};

function daysInMonth(month: string): number {
  const [year, monthNumber] = month.split("-").map(Number);
  return new Date(Date.UTC(year!, monthNumber!, 0)).getUTCDate();
}

function hasOccurrenceInMonth(recurrenceId: string, transactions: ProjectionTransaction[], start: string, end: string): boolean {
  return transactions.some((transaction) =>
    transaction.recurrenceId === recurrenceId &&
    transaction.deletedAt === null &&
    transaction.date >= start &&
    transaction.date < end,
  );
}

export function calculateProjection(input: ProjectionInput, now: Date): ProjectionResult {
  const today = localDate(now);
  const month = today.slice(0, 7);
  const monthStart = monthDate(month, 1);
  const nextMonthStart = addMonths(monthStart, 1);
  const monthEnd = monthDate(month, daysInMonth(month));
  const daysRemaining = daysInMonth(month) - Number(today.slice(8, 10)) + 1;
  const remainingDaysAfterToday = daysRemaining - 1;
  const accountBalanceCents = input.accounts
    .filter((account) => account.type === "checking" || account.type === "savings")
    .reduce((total, account) => total + account.balanceCents, 0);

  const expectedIncomeCents = input.recurrences
    .filter((recurrence) =>
      recurrence.status === "active" &&
      recurrence.kind === "income" &&
      recurrence.nextExpectedDate <= monthEnd &&
      !hasOccurrenceInMonth(recurrence.id, input.transactions, monthStart, nextMonthStart),
    )
    .reduce((total, recurrence) => total + Math.abs(recurrence.expectedAmountCents), 0);

  const fixedExpensesCents = input.recurrences
    .filter((recurrence) =>
      recurrence.status === "active" &&
      (recurrence.kind === "subscription" || recurrence.kind === "fixed_bill") &&
      recurrence.accountType !== null &&
      recurrence.accountType !== "credit_card" &&
      recurrence.nextExpectedDate <= monthEnd &&
      !hasOccurrenceInMonth(recurrence.id, input.transactions, monthStart, nextMonthStart),
    )
    .reduce((total, recurrence) => total + Math.abs(recurrence.expectedAmountCents), 0);

  const billsDueCents = input.bills
    .filter((bill) => bill.dueDate >= today && bill.dueDate < nextMonthStart)
    .reduce((total, bill) => total + Math.max(0, bill.totalCents - bill.paidCents), 0);

  const lastThirtyDaysStart = addDays(today, -29);
  const dailySpendTotalCents = input.transactions
    .filter((transaction) =>
      transaction.date >= lastThirtyDaysStart &&
      transaction.date <= today &&
      transaction.deletedAt === null &&
      transaction.amountCents < 0 &&
      (transaction.categoryKind === "expense" || transaction.categoryKind === "review") &&
      transaction.accountType !== "credit_card" &&
      !transaction.isTransfer &&
      !transaction.isBillPayment &&
      !(transaction.recurrenceId !== null &&
        input.recurrences.some((recurrence) =>
          recurrence.id === transaction.recurrenceId && recurrence.status === "active",
        )),
    )
    .reduce((total, transaction) => total + Math.abs(transaction.amountCents), 0);
  const dailySpendAverageCents = Math.round(dailySpendTotalCents / 30);
  const expectedDailySpendCents = dailySpendAverageCents * remainingDaysAfterToday;
  const projectedBalanceCents =
    accountBalanceCents +
    expectedIncomeCents -
    fixedExpensesCents -
    billsDueCents -
    expectedDailySpendCents;

  return {
    month,
    accountBalanceCents,
    expectedIncomeCents,
    fixedExpensesCents,
    billsDueCents,
    dailySpendAverageCents,
    remainingDaysAfterToday,
    expectedDailySpendCents,
    projectedBalanceCents,
  };
}
