import { Router, type IRouter } from "express";
import { and, asc, eq, gte, inArray, isNull, lt, or } from "drizzle-orm";
import {
  GetBudgetsQueryParams,
  GetBudgetsResponse,
  SaveBudgetsBody,
  SaveBudgetsResponse,
  SuggestBudgetsQueryParams,
  SuggestBudgetsResponse,
} from "@workspace/api-zod";
import { budgets, categories, recurrences, transactions } from "@workspace/shared/schema";
import { db } from "../db/connection";
import { loadBudgetEntries } from "../db/queries/budgets";
import { apiError } from "../lib/errors";
import { requireAuth } from "../middlewares/security";
import { addMonths, monthDate } from "../lib/dates";
import { loadDashboardHome } from "../db/queries/dashboard";
import { evaluateUserAlerts } from "../jobs/alerts";
import { suggestBudgets } from "../services/budgets";

const router: IRouter = Router();
router.use(requireAuth);

router.get("/budgets", async (req, res): Promise<void> => {
  const parsed = GetBudgetsQueryParams.strict().safeParse(req.query);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Informe um mês válido no formato AAAA-MM.");
    return;
  }
  const data = await loadBudgetEntries(req.session.userId!, parsed.data.month);
  res.json(GetBudgetsResponse.parse({ data }));
});

router.put("/budgets", async (req, res): Promise<void> => {
  const parsed = SaveBudgetsBody.strict().safeParse(req.body);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Os limites informados são inválidos.");
    return;
  }
  const { month, items } = parsed.data;
  const categoryIds = items.map((item) => item.categoryId);
  if (new Set(categoryIds).size !== categoryIds.length) {
    apiError(res, 400, "VALIDATION_ERROR", "Cada categoria pode aparecer apenas uma vez.");
    return;
  }
  const userId = req.session.userId!;
  if (categoryIds.length) {
    const validCategories = await db.select({ id: categories.id }).from(categories).where(and(
      inArray(categories.id, categoryIds),
      eq(categories.kind, "expense"),
      or(isNull(categories.userId), eq(categories.userId, userId)),
    ));
    if (validCategories.length !== categoryIds.length) {
      apiError(res, 400, "VALIDATION_ERROR", "Uma ou mais categorias não estão disponíveis.");
      return;
    }
  }

  const now = new Date();
  await db.transaction(async (tx) => {
    await tx.delete(budgets).where(and(eq(budgets.userId, userId), eq(budgets.month, month)));
    if (items.length) {
      await tx.insert(budgets).values(items.map((item) => ({
        userId,
        month,
        categoryId: item.categoryId,
        limitCents: item.limitCents,
        createdAt: now,
        updatedAt: now,
      })));
    }
  });
  await evaluateUserAlerts(userId, now);
  const data = await loadBudgetEntries(userId, month);
  res.json(SaveBudgetsResponse.parse({ data }));
});

router.post("/budgets/suggest", async (req, res): Promise<void> => {
  const parsed = SuggestBudgetsQueryParams.strict().safeParse(req.query);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Informe um mês válido no formato AAAA-MM.");
    return;
  }
  const userId = req.session.userId!;
  const month = parsed.data.month;
  const targetStart = monthDate(month, 1);
  const historyStart = addMonths(targetStart, -3);
  const [categoryRows, transactionRows, fixedRows, dashboard] = await Promise.all([
    db.select({
      id: categories.id,
      name: categories.name,
      color: categories.color,
      kind: categories.kind,
    }).from(categories).where(and(
      eq(categories.kind, "expense"),
      or(isNull(categories.userId), eq(categories.userId, userId)),
    )).orderBy(asc(categories.sortOrder), asc(categories.name)),
    db.select({
      categoryId: transactions.categoryId,
      date: transactions.date,
      amountCents: transactions.amountCents,
      categoryKind: categories.kind,
      isTransfer: transactions.isTransfer,
      isBillPayment: transactions.isBillPayment,
      deletedAt: transactions.deletedAt,
    }).from(transactions).innerJoin(categories, and(
      eq(categories.id, transactions.categoryId),
      or(isNull(categories.userId), eq(categories.userId, userId)),
    )).where(and(
      eq(transactions.userId, userId),
      gte(transactions.date, historyStart),
      lt(transactions.date, targetStart),
    )),
    db.select({ categoryId: transactions.categoryId }).from(transactions)
      .innerJoin(recurrences, and(
        eq(recurrences.id, transactions.recurrenceId),
        eq(recurrences.userId, userId),
        eq(recurrences.kind, "fixed_bill"),
        eq(recurrences.status, "active"),
      ))
      .innerJoin(categories, and(
        eq(categories.id, transactions.categoryId),
        eq(categories.kind, "expense"),
        or(isNull(categories.userId), eq(categories.userId, userId)),
      ))
      .where(and(
        eq(transactions.userId, userId),
        isNull(transactions.deletedAt),
        gte(transactions.date, historyStart),
        lt(transactions.date, targetStart),
        eq(transactions.isTransfer, false),
        eq(transactions.isBillPayment, false),
      )),
    loadDashboardHome(userId, new Date()),
  ]);
  if (!dashboard) {
    apiError(res, 404, "USER_NOT_FOUND", "Não encontramos os dados da sua conta.");
    return;
  }
  const fixedCategoryIds = new Set(fixedRows.map((row) => row.categoryId));
  const variableBudgetCents = dashboard.allowance.variableBudgetCents;
  const capCents = variableBudgetCents === null
    ? null
    : variableBudgetCents + dashboard.allowance.fixedExpensesCents;
  const data = suggestBudgets({
    month,
    categories: categoryRows,
    transactions: transactionRows,
    fixedCategoryIds,
    capCents,
  });
  res.json(SuggestBudgetsResponse.parse({ data }));
});

export default router;
