import { and, eq, isNull, or, getTableColumns, type SQL } from "drizzle-orm";
import { transactions, accounts, categories, connections } from "@workspace/shared/schema";
import { db } from "../connection";

export function transactionQuery(userId: string, conditions: (SQL | undefined)[] = []) {
  return db.select({
    ...getTableColumns(transactions), accountName: accounts.name, institutionName: connections.institutionName,
    categoryName: categories.name, categoryKind: categories.kind, categoryColor: categories.color, categoryIcon: categories.icon,
  }).from(transactions)
    .innerJoin(accounts, and(eq(accounts.id, transactions.accountId), eq(accounts.userId, userId)))
    .innerJoin(connections, and(eq(connections.id, accounts.connectionId), eq(connections.userId, userId)))
    .innerJoin(categories, and(eq(categories.id, transactions.categoryId), or(isNull(categories.userId), eq(categories.userId, userId))))
    .where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt), ...conditions));
}
export async function findOwnedTransaction(userId: string, transactionId: string) {
  const [transaction] = await transactionQuery(userId, [eq(transactions.id, transactionId)]).limit(1);
  return transaction;
}
