export type AttemptWindow = { count: number; startedAt: number };
const WINDOW_MS = 15 * 60 * 1000;

export function evaluateLoginAttempt(previous: AttemptWindow | undefined, now: Date) {
  const current = !previous || now.getTime() - previous.startedAt >= WINDOW_MS
    ? { count: 0, startedAt: now.getTime() }
    : previous;
  return {
    allowed: current.count < 5,
    state: { ...current, count: current.count + 1 },
    retryAfterSeconds: Math.max(1, Math.ceil((current.startedAt + WINDOW_MS - now.getTime()) / 1000)),
  };
}
