const FLEXIBLE_REDUCTION_PRIORITY = ["Delivery", "Restaurantes", "Compras", "Lazer"];

export type BudgetCategory = {
  id: string;
  name: string;
  color: string;
  kind: "expense" | "income" | "transfer" | "review";
};

export type BudgetSpend = {
  categoryId: string;
  date: string;
  amountCents: number;
  categoryKind: string;
  isTransfer: boolean;
  isBillPayment: boolean;
  deletedAt: Date | string | null;
};

export type BudgetSuggestionItem = {
  categoryId: string;
  categoryName: string;
  color: string;
  medianCents: number;
  suggestedLimitCents: number;
  isFixedCategory: boolean;
};

export type BudgetSuggestion = {
  month: string;
  items: BudgetSuggestionItem[];
  capCents: number | null;
  totalCents: number;
  adjusted: boolean;
  explanation: string;
};

export type BudgetProgressInput = {
  id: string;
  categoryId: string;
  categoryName: string;
  color: string;
  month: string;
  limitCents: number;
};

function isCountableExpense(row: BudgetSpend): boolean {
  return row.deletedAt === null && row.categoryKind === "expense" &&
    row.amountCents < 0 && !row.isTransfer && !row.isBillPayment;
}

function monthsBefore(month: string): string[] {
  const [year, monthNumber] = month.split("-").map(Number);
  const base = new Date(Date.UTC(year!, monthNumber! - 1, 1));
  return [3, 2, 1].map((offset) => {
    const date = new Date(Date.UTC(base.getUTCFullYear(), base.getUTCMonth() - offset, 1));
    return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}`;
  });
}

function medianOfThree(values: [number, number, number]): number {
  return [...values].sort((a, b) => a - b)[1]!;
}

function distributeReduction(items: BudgetSuggestionItem[], amountCents: number): number {
  const total = items.reduce((sum, item) => sum + item.suggestedLimitCents, 0);
  const reduction = Math.min(total, amountCents);
  if (total === 0 || reduction === 0) return 0;

  const shares = items.map((item) => {
    const numerator = reduction * item.suggestedLimitCents;
    return {
      item,
      cut: Math.floor(numerator / total),
      remainder: numerator % total,
    };
  });
  let centsLeft = reduction - shares.reduce((sum, share) => sum + share.cut, 0);
  shares.sort((a, b) =>
    b.remainder - a.remainder ||
    a.item.categoryName.localeCompare(b.item.categoryName) ||
    a.item.categoryId.localeCompare(b.item.categoryId),
  );
  for (const share of shares) {
    if (centsLeft === 0) break;
    if (share.cut >= share.item.suggestedLimitCents) continue;
    share.cut++;
    centsLeft--;
  }
  for (const share of shares) share.item.suggestedLimitCents -= share.cut;
  return reduction - centsLeft;
}

export function suggestBudgets(input: {
  month: string;
  categories: BudgetCategory[];
  transactions: BudgetSpend[];
  fixedCategoryIds?: ReadonlySet<string>;
  capCents: number | null;
}): BudgetSuggestion {
  const referenceMonths = monthsBefore(input.month);
  const monthSet = new Set(referenceMonths);
  const totals = new Map<string, Map<string, number>>();
  for (const transaction of input.transactions) {
    if (!isCountableExpense(transaction) || !monthSet.has(transaction.date.slice(0, 7))) continue;
    const byMonth = totals.get(transaction.categoryId) ?? new Map<string, number>();
    byMonth.set(
      transaction.date.slice(0, 7),
      (byMonth.get(transaction.date.slice(0, 7)) ?? 0) + Math.abs(transaction.amountCents),
    );
    totals.set(transaction.categoryId, byMonth);
  }

  const items: BudgetSuggestionItem[] = input.categories
    .filter((category) => category.kind === "expense")
    .map((category) => {
      const byMonth = totals.get(category.id) ?? new Map<string, number>();
      const medianCents = medianOfThree([
        byMonth.get(referenceMonths[0]!) ?? 0,
        byMonth.get(referenceMonths[1]!) ?? 0,
        byMonth.get(referenceMonths[2]!) ?? 0,
      ]);
      return {
        categoryId: category.id,
        categoryName: category.name,
        color: category.color,
        medianCents,
        suggestedLimitCents: Math.ceil(medianCents / 1_000) * 1_000,
        isFixedCategory: input.fixedCategoryIds?.has(category.id) ?? false,
      };
    })
    .filter((item) => item.suggestedLimitCents > 0)
    .sort((a, b) => a.categoryName.localeCompare(b.categoryName) || a.categoryId.localeCompare(b.categoryId));

  let totalCents = items.reduce((sum, item) => sum + item.suggestedLimitCents, 0);
  let remainingReduction = input.capCents === null ? 0 : Math.max(0, totalCents - input.capCents);
  const adjusted = remainingReduction > 0;

  if (remainingReduction > 0) {
    const priorityGroup = items.filter((item) =>
      !item.isFixedCategory && FLEXIBLE_REDUCTION_PRIORITY.includes(item.categoryName),
    );
    remainingReduction -= distributeReduction(priorityGroup, remainingReduction);
    if (remainingReduction > 0) {
      const otherFlexible = items.filter((item) =>
        !item.isFixedCategory && !FLEXIBLE_REDUCTION_PRIORITY.includes(item.categoryName),
      );
      remainingReduction -= distributeReduction(otherFlexible, remainingReduction);
    }
  }

  totalCents = items.reduce((sum, item) => sum + item.suggestedLimitCents, 0);
  const fixedOverCap = input.capCents !== null && totalCents > input.capCents;
  return {
    month: input.month,
    items,
    capCents: input.capCents,
    totalCents,
    adjusted,
    explanation: !adjusted
      ? "Os limites usam a mediana dos três últimos meses completos, arredondada para cima em blocos de R$ 10."
      : fixedOverCap
        ? "Os limites variáveis foram reduzidos proporcionalmente, priorizando Delivery, Restaurantes, Compras e Lazer. Os compromissos fixos ainda excedem o valor disponível; ajuste a sugestão antes de salvar."
        : "A soma inicial excedia o valor disponível. Os limites não fixos foram reduzidos proporcionalmente, priorizando Delivery, Restaurantes, Compras e Lazer.",
  };
}

export function calculateBudgetProgress(
  budgets: BudgetProgressInput[],
  transactions: BudgetSpend[],
): Array<BudgetProgressInput & { spentCents: number; remainingCents: number; progressPercent: number }> {
  const spendByCategoryMonth = new Map<string, number>();
  for (const transaction of transactions) {
    if (!isCountableExpense(transaction)) continue;
    const key = `${transaction.date.slice(0, 7)}:${transaction.categoryId}`;
    spendByCategoryMonth.set(
      key,
      (spendByCategoryMonth.get(key) ?? 0) + Math.abs(transaction.amountCents),
    );
  }
  return budgets.map((budget) => {
    const spentCents = spendByCategoryMonth.get(`${budget.month}:${budget.categoryId}`) ?? 0;
    return {
      ...budget,
      spentCents,
      remainingCents: budget.limitCents - spentCents,
      progressPercent: budget.limitCents > 0 ? Math.round((spentCents / budget.limitCents) * 100) : spentCents > 0 ? 100 : 0,
    };
  });
}
