export const ASSISTANT_MODEL = "claude-sonnet-5-5";

type JsonSchema = {
  type: "object";
  properties: Record<string, unknown>;
  required?: string[];
  additionalProperties?: boolean;
};
export type AssistantToolSpec = { name: string; description: string; input_schema: JsonSchema };

const dateProperty = { type: "string", format: "date" };
const periodSchema = {
  type: "object",
  properties: { from: dateProperty, to: dateProperty },
  required: ["from", "to"],
  additionalProperties: false,
};

