const dateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const periodInput = z.object({ from: dateSchema, to: dateSchema }).strict().refine((value) => value.from <= value.to);
const summaryInput = z.object({
  from: dateSchema, to: dateSchema,
  groupBy: z.enum(["category", "merchant", "account", "week"]),
}).strict().refine((value) => value.from <= value.to);
const searchInput = z.object({
  query: z.string().max(200).optional(),
  categoryName: z.string().max(100).optional(),
  merchant: z.string().max(200).optional(),
  minCents: z.number().int().nonnegative().optional(),
  maxCents: z.number().int().nonnegative().optional(),
  from: dateSchema.optional(),
  to: dateSchema.optional(),
  limit: z.number().int().min(1).max(50).default(10),
}).strict().refine((value) => !value.from || !value.to || value.from <= value.to);
const balanceInput = z.object({}).strict();
const recurrenceInput = z.object({ kind: z.enum(["subscription", "fixed_bill", "income"]).optional() }).strict();
const upcomingBillsInput = z.object({ days: z.number().int().min(1).max(365).default(30) }).strict();
const installmentsInput = z.object({ months: z.number().int().min(1).max(24).default(12) }).strict();
const simulatePurchaseInput = z.object({
  amountCents: z.number().int().positive().max(100_000_000),
  installments: z.number().int().min(1).max(48),
}).strict();
const compareInput = z.object({
  periodA: periodInput,
  periodB: periodInput,
  groupBy: z.enum(["category", "merchant", "account", "week"]),
}).strict();
const budgetInput = z.object({ month: z.string().regex(/^\d{4}-(0[1-9]|1[0-2])$/) }).strict();

export type AssistantMaskingContext = {
  userName: string | null;
  people: AssistantPerson[];
  personNames: string[];
  privateNamesByKey: Map<string, string>;
};

export async function loadAssistantMaskingContext(userId: string): Promise<AssistantMaskingContext> {
  const [[user], peopleRows] = await Promise.all([
    db.select({ name: users.name }).from(users).where(eq(users.id, userId)).limit(1),
    db.select({ name: transactions.counterpartName, merchantKey: transactions.merchantKey })
      .from(transactions).where(and(
        eq(transactions.userId, userId),
        eq(transactions.counterpartType, "person"),
        isNotNull(transactions.counterpartName),
      )),
  ]);
  const people = [...new Map(peopleRows
    .filter((person): person is { name: string; merchantKey: string } => Boolean(person.name))
    .map((person) => [`${person.merchantKey}:${person.name}`, { name: person.name, merchantKey: person.merchantKey }])).values()];
  const map = assistantPersonMap(people);
  const personNames = [...new Set([...map.names, ...(user?.name ? [user.name] : [])])];
  return { userName: user?.name ?? null, people, personNames, privateNamesByKey: map.privateNamesByKey };
}

export function maskAssistantQuestion(message: string, context: AssistantMaskingContext): string {
  return maskAssistantUserMessage(message, context.userName, context.people);
}

function privateNamesForRows(rows: Array<{ counterpartType: string | null; counterpartName: string | null; merchantKey: string }>) {
  return Object.fromEntries(rows
    .filter((row) => row.counterpartType === "person" && row.counterpartName && /^PIX P-[a-f0-9]{6}$/i.test(row.merchantKey))
    .map((row) => [row.merchantKey.toUpperCase(), row.counterpartName!]));
}

function safeTransaction(row: Awaited<ReturnType<typeof transactionQuery>>[number], context: AssistantMaskingContext) {
  return maskAssistantTransaction(row, context.personNames);
}

function weekStart(date: string): string {
  const value = new Date(`${date}T00:00:00.000Z`);
  value.setUTCDate(value.getUTCDate() - ((value.getUTCDay() + 6) % 7));
  return value.toISOString().slice(0, 10);
}

function grouping(row: Awaited<ReturnType<typeof transactionQuery>>[number], groupBy: z.infer<typeof summaryInput>["groupBy"], context: AssistantMaskingContext) {
  if (groupBy === "category") return { key: row.categoryId, label: maskSensitiveText(row.categoryName, context.personNames) };
  if (groupBy === "merchant") {
    const safe = safeTransaction(row, context);
    const normalizedKey = row.merchantKey.toUpperCase();
    if (normalizedKey.startsWith("IFOOD")) return { key: "merchant:IFOOD", label: "iFood" };
    if (normalizedKey.startsWith("UBER EATS")) return { key: "merchant:UBER EATS", label: "Uber Eats" };
    if (normalizedKey.startsWith("UBER")) return { key: "merchant:UBER", label: "Uber" };
    if (normalizedKey.startsWith("NETFLIX")) return { key: "merchant:NETFLIX", label: "Netflix" };
    return { key: row.counterpartType === "person" ? row.merchantKey : (row.merchantKey || safe.merchantName), label: safe.merchantName };
  }
  if (groupBy === "account") return { key: row.accountId, label: maskSensitiveText(row.accountName, context.personNames) };
  const start = weekStart(row.date);
  return { key: start, label: start };
}

async function summaryForPeriod(
  userId: string,
  period: { from: string; to: string },
  groupBy: z.infer<typeof summaryInput>["groupBy"],
  context: AssistantMaskingContext,
) {
  const rows = await transactionQuery(userId, [gte(transactions.date, period.from), lte(transactions.date, period.to)])
    .orderBy(desc(transactions.date), desc(transactions.id)).limit(5000);
  const expenses = rows.filter((row) => isExpenseTransaction(row, row.categoryKind));
  const groups = new Map<string, { label: string; totalCents: number; count: number; transactionIds: string[] }>();
  for (const row of expenses) {
    const group = grouping(row, groupBy, context);
    const current = groups.get(group.key) ?? { label: group.label, totalCents: 0, count: 0, transactionIds: [] };
    current.totalCents += Math.abs(row.amountCents);
    current.count++;
    current.transactionIds.push(row.id);
    groups.set(group.key, current);
  }
  const data = [...groups.entries()].map(([key, value]) => ({ key, ...value }))
    .sort((a, b) => b.totalCents - a.totalCents || a.label.localeCompare(b.label, "pt-BR"));
  const visibleGroups = data.map((group) => ({ ...group, transactionIds: group.transactionIds.slice(0, 10) }));
  return {
    from: period.from,
    to: period.to,
    groupBy,
    totalCents: expenses.reduce((total, row) => total + Math.abs(row.amountCents), 0),
    count: expenses.length,
    groups: visibleGroups,
    transactionIds: visibleGroups.flatMap((group) => group.transactionIds),
    privateNamesByKey: privateNamesForRows(expenses),
  };
}

export function createAssistantToolExecutor(
  userId: string,
  now: Date,
  context: AssistantMaskingContext,
): AssistantToolExecutor {
  return async (name, rawInput): Promise<AssistantToolExecution> => {
    switch (name) {
      case "get_spending_summary": {
        const input = summaryInput.parse(rawInput);
        const result = await summaryForPeriod(userId, input, input.groupBy, context);
        return {
          data: { from: result.from, to: result.to, groupBy: result.groupBy, totalCents: result.totalCents, count: result.count, groups: result.groups },
          transactionIds: result.transactionIds,
          privateNamesByKey: result.privateNamesByKey,
        };
      }
      case "search_transactions": {
        const input = searchInput.parse(rawInput);
        const escaped = (value: string) => `%${value.replace(/[\\%_]/g, "\\$&")}%`;
        const conditions = [
          input.from ? gte(transactions.date, input.from) : undefined,
          input.to ? lte(transactions.date, input.to) : undefined,
          input.categoryName ? ilike(categories.name, escaped(input.categoryName)) : undefined,
          input.merchant ? or(ilike(transactions.merchantName, escaped(input.merchant)), ilike(transactions.merchantKey, escaped(input.merchant))) : undefined,
          input.query ? or(
            ilike(transactions.descriptionRaw, escaped(input.query)),
            ilike(transactions.merchantName, escaped(input.query)),
            ilike(transactions.merchantKey, escaped(input.query)),
          ) : undefined,
          input.minCents !== undefined ? gte(sql`abs(${transactions.amountCents})`, input.minCents) : undefined,
          input.maxCents !== undefined ? lte(sql`abs(${transactions.amountCents})`, input.maxCents) : undefined,
        ];
        const rows = await transactionQuery(userId, conditions).orderBy(desc(transactions.date), desc(transactions.id)).limit(input.limit);
        return {
          data: rows.map((row) => ({
            ...safeTransaction(row, context),
            descriptionQueryMatched: Boolean(input.query && row.descriptionRaw.toLocaleLowerCase().includes(input.query.toLocaleLowerCase())),
          })),
          transactionIds: rows.map((row) => row.id),
          privateNamesByKey: privateNamesForRows(rows),
        };
      }
      case "get_balances": {
        balanceInput.parse(rawInput);
        const rows = await db.select({
          id: accounts.id,
          type: accounts.type,
          name: accounts.name,
          balanceCents: accounts.balanceCents,
          creditLimitCents: accounts.creditLimitCents,
          availableLimitCents: accounts.availableLimitCents,
        }).from(accounts).where(eq(accounts.userId, userId)).orderBy(asc(accounts.name));
        return {
          data: rows.map((account) => ({ ...account, name: maskSensitiveText(account.name, context.personNames) })),
          transactionIds: [],
        };
      }
      case "get_daily_allowance": {
        balanceInput.parse(rawInput);
        const home = await loadDashboardHome(userId, now);
        return { data: home ? home.allowance : null, transactionIds: [] };
      }
      case "get_month_projection": {
        balanceInput.parse(rawInput);
        const home = await loadDashboardHome(userId, now);
        return { data: home ? home.projection : null, transactionIds: [] };
      }
      case "get_recurring": {
        const input = recurrenceInput.parse(rawInput);
        const allRows = await db.select({
          id: recurrences.id,
          kind: recurrences.kind,
          label: recurrences.label,
          merchantKey: recurrences.merchantKey,
          expectedAmountCents: recurrences.expectedAmountCents,
          previousAmountCents: recurrences.previousAmountCents,
          dayOfMonth: recurrences.dayOfMonth,
          nextExpectedDate: recurrences.nextExpectedDate,
          accountName: accounts.name,
        }).from(recurrences).leftJoin(accounts, and(eq(accounts.id, recurrences.accountId), eq(accounts.userId, userId)))
          .where(and(
            eq(recurrences.userId, userId),
            eq(recurrences.status, "active"),
          )).orderBy(asc(recurrences.nextExpectedDate), asc(recurrences.label));
        const rows = input.kind ? allRows.filter((row) => row.kind === input.kind) : allRows;
        const ids = rows.map((row) => row.id);
        const linked = ids.length ? await db.select({ id: transactions.id, recurrenceId: transactions.recurrenceId })
          .from(transactions).where(and(eq(transactions.userId, userId), inArray(transactions.recurrenceId, ids), isNull(transactions.deletedAt))) : [];
        const linkedByRecurrence = new Map<string, string[]>();
        for (const transaction of linked) {
          if (!transaction.recurrenceId) continue;
          const transactionIds = linkedByRecurrence.get(transaction.recurrenceId) ?? [];
          if (transactionIds.length < 10) transactionIds.push(transaction.id);
          linkedByRecurrence.set(transaction.recurrenceId, transactionIds);
        }
        const recurrenceKeys = new Set(rows.map((row) => row.merchantKey.toUpperCase()));
        return {
          data: {
            recurrences: rows.map((row) => {
            const { expectedAmountCents, previousAmountCents, ...recurrence } = row;
            return {
              ...recurrence,
              monthlyAmountCents: Math.abs(expectedAmountCents),
              previousAmountCents: previousAmountCents === null ? null : Math.abs(previousAmountCents),
              transactionIds: linkedByRecurrence.get(row.id) ?? [],
              label: /^PIX P-[a-f0-9]{6}$/i.test(row.merchantKey)
                ? row.merchantKey.toUpperCase()
                : maskSensitiveText(row.label, context.personNames),
              merchantKey: /^PIX P-[a-f0-9]{6}$/i.test(row.merchantKey)
                ? row.merchantKey.toUpperCase()
                : maskSensitiveText(row.merchantKey, context.personNames),
              accountName: row.accountName ? maskSensitiveText(row.accountName, context.personNames) : null,
            };
            }),
            noActiveRecurrences: allRows.length === 0,
            noMatchingRecurrences: rows.length === 0,
          },
          transactionIds: [...linkedByRecurrence.values()].flat(),
          privateNamesByKey: Object.fromEntries([...context.privateNamesByKey]
            .filter(([key]) => recurrenceKeys.has(key))),
        };
      }
      case "get_upcoming_bills": {
        const input = upcomingBillsInput.parse(rawInput);
        const today = localDate(now);
        const through = addDays(today, input.days);
        const [billRows, recurrenceRows] = await Promise.all([
          db.select({
            id: bills.id,
            dueDate: bills.dueDate,
            totalCents: bills.totalCents,
            paidCents: bills.paidCents,
            status: bills.status,
            accountName: accounts.name,
          }).from(bills).innerJoin(accounts, and(eq(accounts.id, bills.accountId), eq(accounts.userId, userId)))
            .where(and(eq(bills.userId, userId), gte(bills.dueDate, today), lte(bills.dueDate, through), sql`${bills.totalCents} > ${bills.paidCents}`))
            .orderBy(asc(bills.dueDate)),
          db.select({
            id: recurrences.id,
            label: recurrences.label,
            merchantKey: recurrences.merchantKey,
            expectedAmountCents: recurrences.expectedAmountCents,
            nextExpectedDate: recurrences.nextExpectedDate,
            accountName: accounts.name,
          }).from(recurrences).leftJoin(accounts, and(eq(accounts.id, recurrences.accountId), eq(accounts.userId, userId)))
            .where(and(eq(recurrences.userId, userId), eq(recurrences.status, "active"), eq(recurrences.kind, "fixed_bill"), gte(recurrences.nextExpectedDate, today), lte(recurrences.nextExpectedDate, through)))
            .orderBy(asc(recurrences.nextExpectedDate)),
        ]);
        const billsData = billRows.map((row) => ({
          ...row,
          remainingCents: Math.max(0, row.totalCents - row.paidCents),
          accountName: maskSensitiveText(row.accountName, context.personNames),
        }));
        const recurrencesData = recurrenceRows.map((row) => ({
          ...row,
          label: /^PIX P-[a-f0-9]{6}$/i.test(row.merchantKey)
            ? row.merchantKey.toUpperCase()
            : maskSensitiveText(row.label, context.personNames),
          merchantKey: /^PIX P-[a-f0-9]{6}$/i.test(row.merchantKey)
            ? row.merchantKey.toUpperCase()
            : maskSensitiveText(row.merchantKey, context.personNames),
          accountName: row.accountName ? maskSensitiveText(row.accountName, context.personNames) : null,
        }));
        return {
          data: {
            bills: billsData,
            fixedBills: recurrencesData,
            totalCents: billsData.reduce((sum, row) => sum + row.remainingCents, 0) +
              recurrencesData.reduce((sum, row) => sum + Math.abs(row.expectedAmountCents), 0),
          },
          transactionIds: [],
          privateNamesByKey: Object.fromEntries([...context.privateNamesByKey]
            .filter(([key]) => recurrenceRows.some((row) => row.merchantKey.toUpperCase() === key))),
        };
      }
      case "get_future_installments": {
        const input = installmentsInput.parse(rawInput);
        const rows = await transactionQuery(userId).orderBy(desc(transactions.date), desc(transactions.id)).limit(5000);
        const projection = calculateInstallments(rows.map((row) => ({
          id: row.id,
          accountId: row.accountId,
          accountName: row.accountName,
          date: row.date,
          descriptionRaw: row.descriptionRaw,
          merchantKey: row.merchantKey,
          merchantName: row.merchantName,
          amountCents: row.amountCents,
          installmentNumber: row.installmentNumber,
          installmentTotal: row.installmentTotal,
          installmentGroupKey: row.installmentGroupKey,
          deletedAt: row.deletedAt,
        })), input.months, now);
        const rowsById = new Map(rows.map((row) => [row.id, row]));
        const months = projection.months.map((month) => ({
          month: month.month,
          totalCents: month.totalCents,
          itemCount: month.items.length,
          itemsTruncated: month.items.length > 20,
          items: month.items.slice(0, 20).map((item) => {
            const transaction = item.transactionId ? rowsById.get(item.transactionId) : undefined;
            const safe = transaction ? safeTransaction(transaction, context) : null;
            const merchantName = safe?.merchantName ?? (
              /^PIX P-[a-f0-9]{6}$/i.test(item.merchantKey)
                ? item.merchantKey.toUpperCase()
                : maskSensitiveText(item.label, context.personNames)
            );
            return {
              date: item.date,
              amountCents: item.amountCents,
              installmentNumber: item.installmentNumber,
              installmentTotal: item.installmentTotal,
              projected: item.projected,
              merchantName,
              accountName: maskSensitiveText(item.accountName, context.personNames),
              transactionId: item.transactionId,
            };
          }),
        }));
        return {
          data: { months },
          transactionIds: months.flatMap((month) => month.items.flatMap((item) => item.transactionId ? [item.transactionId] : [])),
          privateNamesByKey: privateNamesForRows(rows),
        };
      }
      case "simulate_purchase": {
        const input = simulatePurchaseInput.parse(rawInput);
        const home = await loadDashboardHome(userId, now);
        if (!home) return { data: { error: "Não foi possível calcular a projeção." }, transactionIds: [] };
        const schedule = simulatePurchaseInstallments(input.amountCents, input.installments, localDate(now));
        const byMonth = new Map<string, { totalCents: number; installments: typeof schedule }>();
        for (const installment of schedule) {
          const month = installment.date.slice(0, 7);
          const current = byMonth.get(month) ?? { totalCents: 0, installments: [] };
          current.totalCents += Math.abs(installment.amountCents);
          current.installments.push(installment);
          byMonth.set(month, current);
        }
        const firstInstallmentCents = Math.abs(schedule[0]?.amountCents ?? 0);
        const after = calculateAllowanceWithAdditionalInstallment(home.allowance, firstInstallmentCents);
        return {
          data: {
            purchaseAmountCents: input.amountCents,
            installmentCount: input.installments,
            months: [...byMonth.entries()].map(([month, value]) => ({ month, ...value })),
            dailyAllowanceBeforeCents: home.allowance.dailyAllowanceCents,
            dailyAllowanceAfterCents: after.dailyAllowanceCents,
            allowanceStatusAfter: after.status,
          },
          transactionIds: [],
        };
      }
      case "compare_periods": {
        const input = compareInput.parse(rawInput);
        const [periodA, periodB] = await Promise.all([
          summaryForPeriod(userId, input.periodA, input.groupBy, context),
          summaryForPeriod(userId, input.periodB, input.groupBy, context),
        ]);
        const ids = [...new Set([...periodA.transactionIds, ...periodB.transactionIds])];
        const groupsA = new Map(periodA.groups.map((group) => [group.key, group]));
        const groupsB = new Map(periodB.groups.map((group) => [group.key, group]));
        const groupKeys = new Set([...groupsA.keys(), ...groupsB.keys()]);
        const groupDifferences = [...groupKeys].map((key) => {
          const groupA = groupsA.get(key);
          const groupB = groupsB.get(key);
          return {
            key,
            label: groupB?.label ?? groupA?.label ?? key,
            periodACents: groupA?.totalCents ?? 0,
            periodBCents: groupB?.totalCents ?? 0,
            differenceCents: (groupB?.totalCents ?? 0) - (groupA?.totalCents ?? 0),
          };
        }).sort((a, b) => Math.abs(b.differenceCents) - Math.abs(a.differenceCents) || a.label.localeCompare(b.label, "pt-BR"));
        return {
          data: {
            periodA: { from: periodA.from, to: periodA.to, totalCents: periodA.totalCents, count: periodA.count, groups: periodA.groups },
            periodB: { from: periodB.from, to: periodB.to, totalCents: periodB.totalCents, count: periodB.count, groups: periodB.groups },
            differenceCents: periodB.totalCents - periodA.totalCents,
            groupDifferences,
            groupBy: input.groupBy,
          },
          transactionIds: ids,
          privateNamesByKey: { ...periodA.privateNamesByKey, ...periodB.privateNamesByKey },
        };
      }
      case "get_budget_status": {
        const input = budgetInput.parse(rawInput);
        const start = monthDate(input.month, 1);
        const end = addMonths(start, 1);
        const [budgetRows, expenseRows] = await Promise.all([
          db.select({
            id: budgets.id,
            categoryId: budgets.categoryId,
            categoryName: categories.name,
            limitCents: budgets.limitCents,
          }).from(budgets).innerJoin(categories, and(eq(categories.id, budgets.categoryId), or(isNull(categories.userId), eq(categories.userId, userId))))
            .where(and(eq(budgets.userId, userId), eq(budgets.month, input.month))),
          transactionQuery(userId, [gte(transactions.date, start), lte(transactions.date, addDays(end, -1))]),
        ]);
        const spentByCategory = new Map<string, number>();
        const spendRows = expenseRows.filter((row) => isExpenseTransaction(row, row.categoryKind));
        for (const row of spendRows) {
          spentByCategory.set(row.categoryId, (spentByCategory.get(row.categoryId) ?? 0) + Math.abs(row.amountCents));
        }
        return {
          data: {
            month: input.month,
            budgets: budgetRows.map((row) => {
              const spentCents = spentByCategory.get(row.categoryId) ?? 0;
              return {
                id: row.id,
                categoryId: row.categoryId,
                categoryName: maskSensitiveText(row.categoryName, context.personNames),
                limitCents: row.limitCents,
                spentCents,
                remainingCents: row.limitCents - spentCents,
              };
            }),
          },
          transactionIds: [],
        };
      }
      case "get_debts": {
        balanceInput.parse(rawInput);
        const [debtRows, planRows] = await Promise.all([
          db.select({
            id: debts.id,
            name: debts.name,
            kind: debts.kind,
            balanceCents: debts.balanceCents,
            monthlyRateBps: debts.monthlyRateBps,
            minimumPaymentCents: debts.minimumPaymentCents,
            source: debts.source,
          }).from(debts).where(and(eq(debts.userId, userId), eq(debts.confirmed, true))).orderBy(desc(debts.balanceCents)),
          db.select({
            id: debtPlans.id,
            strategy: debtPlans.strategy,
            monthlyBudgetCents: debtPlans.monthlyBudgetCents,
            startedAt: debtPlans.startedAt,
          }).from(debtPlans).where(and(eq(debtPlans.userId, userId), eq(debtPlans.active, true)))
            .orderBy(desc(debtPlans.startedAt), desc(debtPlans.updatedAt)).limit(1),
        ]);
        return {
          data: {
            debts: debtRows.map((debt, index) => ({
              id: debt.id,
              label: `Dívida ${index + 1}`,
              kind: debt.kind,
              balanceCents: debt.balanceCents,
              monthlyRateBps: debt.monthlyRateBps,
              minimumPaymentCents: debt.minimumPaymentCents,
              source: debt.source,
            })),
            activePlan: planRows[0] ?? null,
          },
          transactionIds: [],
        };
      }
      default:
        return { data: { error: "Ferramenta indisponível." }, transactionIds: [] };
    }
  };
}

