import type { RequestHandler } from "express";
import { apiError } from "../lib/errors";

export const verifyOrigin: RequestHandler = (req, res, next) => {
  if (!["POST", "PUT", "PATCH", "DELETE"].includes(req.method) || req.path.startsWith("/webhooks/")) {
    next();
    return;
  }
  const origin = req.get("origin");
  const expected = `${req.protocol}://${req.host}`;
  if (!origin || origin !== expected) {
    apiError(res, 403, "ORIGIN_FORBIDDEN", "Esta requisição não foi permitida.");
    return;
  }
  next();
};

export const requireAuth: RequestHandler = (req, res, next) => {
  if (!req.session.userId) {
    apiError(res, 401, "UNAUTHENTICATED", "Entre na sua conta para continuar.");
    return;
  }
  next();
};

const requestWindows = new Map<string, { count: number; startsAt: number }>();
const assistantRequestWindows = new Map<string, { count: number; startsAt: number }>();

export const assistantRateLimit: RequestHandler = (req, res, next) => {
  const userId = req.session.userId;
  if (!userId) { next(); return; }
  const now = Date.now();
  for (const [key, window] of assistantRequestWindows) {
    if (now - window.startsAt >= 60_000) assistantRequestWindows.delete(key);
  }
  const window = assistantRequestWindows.get(userId) ?? { count: 0, startsAt: now };
  if (window.count >= 10) {
    res.set("Retry-After", String(Math.max(1, Math.ceil((window.startsAt + 60_000 - now) / 1000))));
    apiError(res, 429, "ASSISTANT_RATE_LIMITED", "Muitas perguntas em pouco tempo. Aguarde um momento.");
    return;
  }
  assistantRequestWindows.set(userId, { ...window, count: window.count + 1 });
  next();
};

export const apiRateLimit: RequestHandler = (req, res, next) => {
  const userId = req.session.userId;
  if (!userId) { next(); return; }
  const now = Date.now();
  for (const [key, window] of requestWindows) {
    if (now - window.startsAt >= 60_000) requestWindows.delete(key);
  }
  const window = requestWindows.get(userId) ?? { count: 0, startsAt: now };
  if (window.count >= 120) {
    res.set("Retry-After", String(Math.max(1, Math.ceil((window.startsAt + 60_000 - now) / 1000))));
    apiError(res, 429, "RATE_LIMITED", "Muitas requisições. Aguarde um momento.");
    return;
  }
  requestWindows.set(userId, { ...window, count: window.count + 1 });
  next();
};
