import { Router, type IRouter } from "express";
import { and, asc, eq } from "drizzle-orm";
import {
  CreateGoalBody,
  CreateGoalResponse,
  DeleteGoalParams,
  DeleteGoalResponse,
  GetGoalParams,
  GetGoalResponse,
  GetGoalsResponse,
  UpdateGoalBody,
  UpdateGoalParams,
  UpdateGoalResponse,
} from "@workspace/api-zod";
import { goals } from "@workspace/shared/schema";
import { db } from "../db/connection";
import { apiError } from "../lib/errors";
import { requireAuth } from "../middlewares/security";

const router: IRouter = Router();
router.use(requireAuth);

function dateOnly(value: Date | string | null | undefined): string | null {
  if (value === null || value === undefined) return null;
  return value instanceof Date ? value.toISOString().slice(0, 10) : value;
}

router.get("/goals", async (req, res): Promise<void> => {
  const rows = await db.select().from(goals)
    .where(eq(goals.userId, req.session.userId!))
    .orderBy(asc(goals.status), asc(goals.createdAt));
  res.json(GetGoalsResponse.parse({ data: rows }));
});

router.post("/goals", async (req, res): Promise<void> => {
  const parsed = CreateGoalBody.strict().safeParse(req.body);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Confira o nome e o valor da meta.");
    return;
  }
  const now = new Date();
  const [created] = await db.insert(goals).values({
    userId: req.session.userId!,
    name: parsed.data.name.trim(),
    targetCents: parsed.data.targetCents,
    targetDate: dateOnly(parsed.data.targetDate),
    savedCents: parsed.data.savedCents ?? 0,
    monthlyContributionCents: parsed.data.monthlyContributionCents ?? 0,
    status: "active",
    createdAt: now,
    updatedAt: now,
  }).returning();
  if (!created) {
    apiError(res, 500, "CREATE_FAILED", "Não foi possível criar a meta.");
    return;
  }
  res.status(201).json(CreateGoalResponse.parse({ data: created }));
});

router.get("/goals/:id", async (req, res): Promise<void> => {
  const parsed = GetGoalParams.strict().safeParse(req.params);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Meta inválida.");
    return;
  }
  const [goal] = await db.select().from(goals).where(and(
    eq(goals.id, parsed.data.id),
    eq(goals.userId, req.session.userId!),
  )).limit(1);
  if (!goal) {
    apiError(res, 404, "NOT_FOUND", "Meta não encontrada.");
    return;
  }
  res.json(GetGoalResponse.parse({ data: goal }));
});

router.patch("/goals/:id", async (req, res): Promise<void> => {
  const params = UpdateGoalParams.strict().safeParse(req.params);
  const body = UpdateGoalBody.strict().safeParse(req.body);
  if (!params.success || !body.success || Object.keys(body.data ?? {}).length === 0) {
    apiError(res, 400, "VALIDATION_ERROR", "Confira os dados da meta.");
    return;
  }
  const { targetDate, ...fields } = body.data;
  const update: Partial<typeof goals.$inferInsert> = {
    ...fields,
    updatedAt: new Date(),
  };
  if (body.data.name !== undefined) update.name = body.data.name.trim();
  if (targetDate !== undefined) update.targetDate = dateOnly(targetDate);
  const [updated] = await db.update(goals).set(update).where(and(
    eq(goals.id, params.data.id),
    eq(goals.userId, req.session.userId!),
  )).returning();
  if (!updated) {
    apiError(res, 404, "NOT_FOUND", "Meta não encontrada.");
    return;
  }
  res.json(UpdateGoalResponse.parse({ data: updated }));
});

router.delete("/goals/:id", async (req, res): Promise<void> => {
  const parsed = DeleteGoalParams.strict().safeParse(req.params);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Meta inválida.");
    return;
  }
  const deleted = await db.delete(goals).where(and(
    eq(goals.id, parsed.data.id),
    eq(goals.userId, req.session.userId!),
  )).returning({ id: goals.id });
  if (!deleted.length) {
    apiError(res, 404, "NOT_FOUND", "Meta não encontrada.");
    return;
  }
  res.json(DeleteGoalResponse.parse({ data: { ok: true } }));
});

export default router;
