export const TIMEZONE = "America/Sao_Paulo";
export function localDate(now: Date): string {
  return new Intl.DateTimeFormat("en-CA", { timeZone: TIMEZONE, year: "numeric", month: "2-digit", day: "2-digit" }).format(now);
}
export const asDate = (day: string) => new Date(`${day}T12:00:00Z`);
export function addDays(day: string, count: number): string {
  const value = asDate(day);
  value.setUTCDate(value.getUTCDate() + count);
  return value.toISOString().slice(0, 10);
}
export function addMonths(day: string, count: number): string {
  const value = asDate(day);
  const originalDay = value.getUTCDate();
  value.setUTCDate(1);
  value.setUTCMonth(value.getUTCMonth() + count);
  const last = new Date(Date.UTC(value.getUTCFullYear(), value.getUTCMonth() + 1, 0)).getUTCDate();
  value.setUTCDate(Math.min(originalDay, last));
  return value.toISOString().slice(0, 10);
}
export const monthDate = (month: string, day: number) => `${month.slice(0, 7)}-${String(day).padStart(2, "0")}`;
export function fifthBusinessDay(month: string): string {
  let day = monthDate(month, 1);
  let count = 0;
  while (true) {
    if (![0, 6].includes(asDate(day).getUTCDay())) count++;
    if (count === 5) return day;
    day = addDays(day, 1);
  }
}
