import { and, asc, desc, eq, getTableColumns, isNotNull, isNull, or } from "drizzle-orm";
import {
  accounts,
  bills,
  budgets,
  categories,
  connections,
  debtPlans,
  recurrences,
  transactions,
  users,
} from "@workspace/shared/schema";
import { db } from "../connection";
import { addDays, localDate, monthDate } from "../../lib/dates";
import { calculateInstallments } from "../../services/installments";
import { calculateAllowance } from "../../services/allowance";
import { calculateProjection } from "../../services/projection";
import { calculateBudgetProgress } from "../../services/budgets";

export async function loadDashboardHome(userId: string, now: Date) {
  const today = localDate(now);
  const month = today.slice(0, 7);
  const monthStart = monthDate(month, 1);
  const [userRows, connectionRows, accountRows, recurrenceRows, billRows, debtPlanRows, budgetRows, transactionRows] =
    await Promise.all([
      db.select({
        monthlyIncomeOverrideCents: users.monthlyIncomeOverrideCents,
        savingsTargetCents: users.savingsTargetCents,
      }).from(users).where(eq(users.id, userId)).limit(1),
      db.select({ id: connections.id }).from(connections).where(and(
        eq(connections.userId, userId),
        eq(connections.status, "active"),
        isNotNull(connections.lastSyncedAt),
      )).limit(1),
      db.select({
        id: accounts.id,
        name: accounts.name,
        type: accounts.type,
        balanceCents: accounts.balanceCents,
      }).from(accounts).where(eq(accounts.userId, userId)),
      db.select({
        id: recurrences.id,
        accountId: recurrences.accountId,
        accountName: accounts.name,
        accountType: accounts.type,
        kind: recurrences.kind,
        label: recurrences.label,
        merchantKey: recurrences.merchantKey,
        expectedAmountCents: recurrences.expectedAmountCents,
        previousAmountCents: recurrences.previousAmountCents,
        frequency: recurrences.frequency,
        dayOfMonth: recurrences.dayOfMonth,
        nextExpectedDate: recurrences.nextExpectedDate,
        status: recurrences.status,
        source: recurrences.source,
        createdAt: recurrences.createdAt,
        updatedAt: recurrences.updatedAt,
      }).from(recurrences).leftJoin(accounts, and(
        eq(accounts.id, recurrences.accountId),
        eq(accounts.userId, userId),
      )).where(eq(recurrences.userId, userId)).orderBy(asc(recurrences.nextExpectedDate), asc(recurrences.label)),
      db.select({
        ...getTableColumns(bills),
        accountName: accounts.name,
      }).from(bills).innerJoin(accounts, and(
        eq(accounts.id, bills.accountId),
        eq(accounts.userId, userId),
      )).where(eq(bills.userId, userId)),
      db.select({ monthlyBudgetCents: debtPlans.monthlyBudgetCents })
        .from(debtPlans)
        .where(and(eq(debtPlans.userId, userId), eq(debtPlans.active, true)))
        .orderBy(desc(debtPlans.startedAt), desc(debtPlans.updatedAt))
        .limit(1),
      db.select({
        id: budgets.id,
        categoryId: budgets.categoryId,
        categoryName: categories.name,
        color: categories.color,
        month: budgets.month,
        limitCents: budgets.limitCents,
      }).from(budgets).innerJoin(categories, and(
        eq(categories.id, budgets.categoryId),
        or(isNull(categories.userId), eq(categories.userId, userId)),
      )).where(and(eq(budgets.userId, userId), eq(budgets.month, month))),
      db.select({
        id: transactions.id,
        accountId: transactions.accountId,
        accountName: accounts.name,
        accountType: accounts.type,
        date: transactions.date,
        descriptionRaw: transactions.descriptionRaw,
        merchantKey: transactions.merchantKey,
        merchantName: transactions.merchantName,
        amountCents: transactions.amountCents,
        isTransfer: transactions.isTransfer,
        isBillPayment: transactions.isBillPayment,
        installmentNumber: transactions.installmentNumber,
        installmentTotal: transactions.installmentTotal,
        installmentGroupKey: transactions.installmentGroupKey,
        recurrenceId: transactions.recurrenceId,
        recurrenceStatus: recurrences.status,
        deletedAt: transactions.deletedAt,
        categoryId: categories.id,
        categoryName: categories.name,
        categoryKind: categories.kind,
        categoryColor: categories.color,
      }).from(transactions)
        .innerJoin(accounts, and(
          eq(accounts.id, transactions.accountId),
          eq(accounts.userId, userId),
        ))
        .innerJoin(categories, and(
          eq(categories.id, transactions.categoryId),
          or(isNull(categories.userId), eq(categories.userId, userId)),
        ))
        .leftJoin(recurrences, and(
          eq(recurrences.id, transactions.recurrenceId),
          eq(recurrences.userId, userId),
        ))
        .where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt))),
    ]);

  const user = userRows[0];
  if (!user) return null;

  const nextSevenDaysEnd = addDays(today, 6);
  const installmentRows = transactionRows.map((row) => ({
    id: row.id,
    accountId: row.accountId,
    accountName: row.accountName,
    date: row.date,
    descriptionRaw: row.descriptionRaw,
    merchantKey: row.merchantKey,
    merchantName: row.merchantName,
    amountCents: row.amountCents,
    installmentNumber: row.installmentNumber,
    installmentTotal: row.installmentTotal,
    installmentGroupKey: row.installmentGroupKey,
    deletedAt: row.deletedAt,
  }));
  const installmentItems = calculateInstallments(installmentRows, 1, now).months[0]?.items ?? [];
  const allowance = calculateAllowance({
    monthlyIncomeOverrideCents: user.monthlyIncomeOverrideCents,
    savingsTargetCents: user.savingsTargetCents,
    debtPlanMonthlyBudgetCents: debtPlanRows[0]?.monthlyBudgetCents ?? null,
    hasThreeCompleteMonths: connectionRows.length > 0,
    recurrences: recurrenceRows.map((row) => ({
      id: row.id,
      kind: row.kind,
      status: row.status,
      expectedAmountCents: row.expectedAmountCents,
    })),
    transactions: transactionRows.map((row) => ({
      date: row.date,
      amountCents: row.amountCents,
      categoryKind: row.categoryKind,
      isTransfer: row.isTransfer,
      isBillPayment: row.isBillPayment,
      installmentNumber: row.installmentNumber,
      installmentTotal: row.installmentTotal,
      installmentGroupKey: row.installmentGroupKey,
      recurrenceId: row.recurrenceId,
      deletedAt: row.deletedAt,
    })),
    installmentItems,
  }, now);
  const projection = calculateProjection({
    accounts: accountRows.map((account) => ({ type: account.type, balanceCents: account.balanceCents })),
    recurrences: recurrenceRows.map((row) => ({
      id: row.id,
      kind: row.kind,
      status: row.status,
      expectedAmountCents: row.expectedAmountCents,
      nextExpectedDate: row.nextExpectedDate,
      accountType: row.accountType,
    })),
    transactions: transactionRows.map((row) => ({
      date: row.date,
      amountCents: row.amountCents,
      categoryKind: row.categoryKind,
      accountType: row.accountType,
      isTransfer: row.isTransfer,
      isBillPayment: row.isBillPayment,
      recurrenceId: row.recurrenceId,
      deletedAt: row.deletedAt,
    })),
    bills: billRows.map((bill) => ({
      dueDate: bill.dueDate,
      totalCents: bill.totalCents,
      paidCents: bill.paidCents,
    })),
  }, now);

  const nextSevenDays = [
    ...recurrenceRows
      .filter((recurrence) =>
        recurrence.kind === "fixed_bill" &&
        recurrence.status === "active" &&
        recurrence.nextExpectedDate >= today &&
        recurrence.nextExpectedDate <= nextSevenDaysEnd,
      )
      .map((recurrence) => ({
        id: `recurrence:${recurrence.id}`,
        kind: "fixed_bill" as const,
        label: recurrence.label,
        date: recurrence.nextExpectedDate,
        amountCents: Math.abs(recurrence.expectedAmountCents),
        accountName: recurrence.accountName,
      })),
    ...billRows
      .filter((bill) =>
        bill.dueDate >= today &&
        bill.dueDate <= nextSevenDaysEnd &&
        bill.totalCents > bill.paidCents,
      )
      .map((bill) => ({
        id: `bill:${bill.id}`,
        kind: "bill" as const,
        label: `Fatura · ${bill.accountName}`,
        date: bill.dueDate,
        amountCents: Math.max(0, bill.totalCents - bill.paidCents),
        accountName: bill.accountName,
      })),
  ].sort((a, b) => a.date.localeCompare(b.date) || a.label.localeCompare(b.label));

  const spendByCategory = new Map<string, { categoryName: string; color: string; amountCents: number }>();
  for (const row of transactionRows) {
    if (
      row.date < monthStart ||
      row.date > today ||
      row.amountCents >= 0 ||
      (row.categoryKind !== "expense" && row.categoryKind !== "review") ||
      row.isTransfer ||
      row.isBillPayment
    ) continue;
    const current = spendByCategory.get(row.categoryId) ?? {
      categoryName: row.categoryName,
      color: row.categoryColor,
      amountCents: 0,
    };
    current.amountCents += Math.abs(row.amountCents);
    spendByCategory.set(row.categoryId, current);
  }
  const monthSpendByCategory = [...spendByCategory.entries()]
    .map(([categoryId, value]) => ({ categoryId, ...value }))
    .sort((a, b) => b.amountCents - a.amountCents);
  const subscriptions = recurrenceRows.filter((row) =>
    row.kind === "subscription" && row.status === "active",
  );
  const budgetProgress = calculateBudgetProgress(budgetRows, transactionRows);

  return {
    allowance,
    projection,
    balanceCents: projection.accountBalanceCents,
    nextSevenDays,
    monthSpendByCategory,
    budgets: budgetProgress,
    subscriptions,
  };
}
