import { and, eq, gte, lte, isNull, notInArray, inArray, sql } from "drizzle-orm";
import { accounts, auditLog, bills, categories, connections, transactions, users } from "@workspace/shared/schema";
import { db } from "../db/connection";
import { addDays, addMonths, asDate, localDate } from "../lib/dates";
import { identifyTransactions, normalizeTransaction } from "../services/normalization";
import { createProvider } from "../providers";
import { ProviderError, type FinancialDataProvider } from "../providers/types";
import { runPostSyncPipeline } from "./post-sync";
import { logger } from "../lib/logger";
import type { BatchClassifier } from "../assistant/categorization";
import { runAlertEvaluationInTransaction } from "./alerts";

export async function syncConnection(userId: string, connectionId: string, now: Date, options: {
  refresh?: boolean; provider?: FinancialDataProvider; classify?: BatchClassifier;
} = {}) {
  try {
    return await db.transaction(async (tx) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
      const [connection] = await tx.select().from(connections).where(and(eq(connections.id, connectionId), eq(connections.userId, userId))).limit(1);
      if (!connection || connection.status === "revoked") throw new ProviderError("CONNECTION_NOT_FOUND");
      const [user] = await tx.select().from(users).where(eq(users.id, userId)).limit(1);
      if (!user) throw new ProviderError("CONNECTION_NOT_FOUND");
      const all = await tx.select().from(connections).where(eq(connections.userId, userId));
      const provider = options.provider ?? createProvider(user, all, now);
      const itemId = connection.providerItemId ?? connection.id;
      if (options.refresh) {
        const [recent] = await tx.select({ id: auditLog.id }).from(auditLog).where(and(
          eq(auditLog.userId, userId), eq(auditLog.action, "connection_refresh"),
          sql`${auditLog.metadata}->>'connectionId' = ${connectionId}`,
          gte(auditLog.createdAt, new Date(now.getTime() - 3600000)),
        )).limit(1);
        if (recent) throw new ProviderError("REFRESH_RATE_LIMITED");
        await provider.refresh(itemId);
        await tx.insert(auditLog).values({ userId, action: "connection_refresh", metadata: { connectionId }, createdAt: now });
      }
      await tx.update(connections).set({ status: "syncing", updatedAt: now }).where(and(eq(connections.id, connectionId), eq(connections.userId, userId)));
      const metadata = await provider.getConnection(itemId);
      if (["error", "needs_reauth", "revoked"].includes(metadata.status)) throw new ProviderError(metadata.status === "needs_reauth" ? "NEEDS_REAUTH" : "PROVIDER_ERROR");
      const systemCategories = await tx.select().from(categories).where(isNull(categories.userId));
      const review = systemCategories.find((v) => v.kind === "review");
      const income = systemCategories.find((v) => v.name === "Outras receitas");
      const own = systemCategories.find((v) => v.name === "Transferência entre contas");
      if (!review || !income || !own) throw new Error("Run category seed before synchronization.");
      const today = localDate(now);
      const cutoff = connection.lastSyncedAt ? addDays(today, -40) : addMonths(localDate(connection.createdAt), -6);
      for (const external of await provider.listAccounts(itemId)) {
        const [account] = await tx.insert(accounts).values({ ...external, userId, connectionId }).onConflictDoUpdate({
          target: [accounts.connectionId, accounts.providerAccountId],
          set: { ...external, updatedAt: now },
        }).returning();
        const values = (await provider.listTransactions(external.providerAccountId, asDate(cutoff))).filter((v) => v.date >= cutoff);
        const syncThrough = values.reduce((latest, value) => value.date > latest ? value.date : latest, today);
        const identified = identifyTransactions(account.id, values, now);
        for (const { value, dedupeKey } of identified) {
          const normalized = normalizeTransaction(value, user.name ?? "", external.type, now);
          const imported = {
            providerTransactionId: value.providerTransactionId, providerStableId: value.providerStableId,
            providerCategory: value.providerCategory,
            date: value.date, descriptionRaw: value.description, merchantKey: normalized.merchantKey,
            merchantName: normalized.merchantName, amountCents: value.amountCents,
            paymentMethod: normalized.paymentMethod, counterpartType: value.counterpart?.type ?? null,
            counterpartName: value.counterpart?.name ?? null, counterpartDocMasked: normalized.counterpartDocMasked,
            installmentNumber: value.installment?.number ?? null, installmentTotal: value.installment?.total ?? null,
            deletedAt: null,
          };
          await tx.insert(transactions).values({
            ...imported, userId, accountId: account.id, dedupeKey,
            categoryId: normalized.ownPix ? own.id : value.amountCents > 0 ? income.id : review.id,
            categorySource: normalized.ownPix ? "system_rule" : "default", isTransfer: false,
          }).onConflictDoUpdate({
            target: [transactions.accountId, transactions.dedupeKey],
            // Do not overwrite user category/notes or any future pipeline results.
            set: { ...imported, updatedAt: now },
          });
        }
        await tx.update(transactions).set({ deletedAt: now, updatedAt: now }).where(and(
          eq(transactions.userId, userId), eq(transactions.accountId, account.id),
          gte(transactions.date, cutoff), lte(transactions.date, syncThrough), isNull(transactions.deletedAt),
          identified.length ? notInArray(transactions.dedupeKey, identified.map((v) => v.dedupeKey)) : undefined,
        ));
        if (external.type === "credit_card" && provider.listBills) {
          for (const externalBill of await provider.listBills(external.providerAccountId)) {
            const paid = values.filter((v) => v.providerBillId === externalBill.providerBillId && v.amountCents > 0 && /\bPAGAMENTO RECEBIDO\b/.test(v.description))
              .reduce((sum, v) => sum + v.amountCents, 0);
            const [existingBill] = await tx.select().from(bills).where(and(eq(bills.userId, userId), eq(bills.accountId, account.id), eq(bills.providerBillId, externalBill.providerBillId))).limit(1);
            const paidCents = externalBill.dueDate < cutoff ? existingBill?.paidCents ?? 0 : paid;
            const status = externalBill.closeDate > today ? "open" : paidCents >= externalBill.totalCents ? "paid" : paidCents > 0 ? "partially_paid" : "closed";
            const [bill] = await tx.insert(bills).values({ ...externalBill, paidCents, status, userId, accountId: account.id }).onConflictDoUpdate({
              target: [bills.accountId, bills.providerBillId], set: { ...externalBill, paidCents, status, updatedAt: now },
            }).returning();
            const keys = identified.filter((v) => v.value.providerBillId === externalBill.providerBillId).map((v) => v.dedupeKey);
            if (keys.length) await tx.update(transactions).set({ billId: bill.id }).where(and(
              eq(transactions.userId, userId), eq(transactions.accountId, account.id), inArray(transactions.dedupeKey, keys),
            ));
          }
        }
      }
      await runPostSyncPipeline({ tx, userId, now, classify: options.classify });
      const [result] = await tx.update(connections).set({
        status: "active", lastSyncedAt: now, lastErrorCode: null, updatedAt: now,
        institutionLogoUrl: metadata.institutionLogoUrl, consentExpiresAt: metadata.consentExpiresAt,
      }).where(and(eq(connections.id, connectionId), eq(connections.userId, userId))).returning();
      return result;
    });
  } catch (error) {
    const code = error instanceof ProviderError ? error.code : "SYNC_FAILED";
    if (code === "CONNECTION_NOT_FOUND") throw error;
    if (code === "REFRESH_RATE_LIMITED") {
      await db.transaction(async (tx) => {
        await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
        await tx.update(connections).set({ status: "active", updatedAt: now }).where(and(
          eq(connections.id, connectionId), eq(connections.userId, userId), eq(connections.status, "syncing"),
        ));
      });
      throw error;
    }
    await db.transaction(async (tx) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
      const [found] = await tx.select({ id: connections.id }).from(connections).where(and(eq(connections.id, connectionId), eq(connections.userId, userId))).limit(1);
      if (!found) return;
      await tx.update(connections).set({ status: code === "NEEDS_REAUTH" ? "needs_reauth" : "error", lastErrorCode: code, updatedAt: now })
        .where(and(eq(connections.id, connectionId), eq(connections.userId, userId)));
      try {
        await runAlertEvaluationInTransaction(tx, userId, now);
      } catch {
        logger.warn("Alert evaluation failed after synchronization error");
      }
    });
    throw error;
  }
}

const pending = new Map<string, Promise<unknown>>();
export function queueSync(userId: string, connectionId: string, options: { refresh?: boolean; delayMs?: number } = {}) {
  const key = `${userId}:${connectionId}`;
  if (pending.has(key)) return;
  const task = (async () => {
    if (options.delayMs) await new Promise((resolve) => setTimeout(resolve, options.delayMs));
    try { await syncConnection(userId, connectionId, new Date(), options); }
    catch { logger.warn("Synchronization did not complete"); }
    finally { pending.delete(key); }
  })();
  pending.set(key, task);
}
