import { Router, type IRouter, type Request } from "express";
import bcrypt from "bcrypt";
import { and, desc, eq, isNull, or, sql } from "drizzle-orm";
import {
  users, connections, accounts, transactions, categories, auditLog,
  signupSchema, loginSchema, type User,
} from "@workspace/shared/schema";
import { GetMeResponse, UpdateMeBody } from "@workspace/api-zod";
import { db, pool } from "../db/connection";
import { apiError } from "../lib/errors";
import { requireAuth } from "../middlewares/security";
import { evaluateLoginAttempt, type AttemptWindow } from "../services/login-limit";
import { exportTransactionsCsv } from "../services/account-export";
import { createProvider } from "../providers";

const router: IRouter = Router();
const loginAttempts = new Map<string, AttemptWindow>();
const COOKIE = "financas.sid";

async function publicUser(user: User) {
  const connected = await db.select({ id: connections.id }).from(connections).where(eq(connections.userId, user.id)).limit(1);
  return {
    id: user.id, name: user.name, email: user.email, plan: user.plan,
    monthlyIncomeOverrideCents: user.monthlyIncomeOverrideCents,
    savingsTargetCents: user.savingsTargetCents,
    aiQuestionsUsed: user.aiQuestionsUsed, aiQuestionsPeriod: user.aiQuestionsPeriod,
    hasConnections: connected.length > 0,
  };
}

function startSession(req: Request, userId: string): Promise<void> {
  return new Promise((resolve, reject) => req.session.regenerate((error) => {
    if (error) { reject(error); return; }
    req.session.userId = userId;
    req.session.save((saveError) => saveError ? reject(saveError) : resolve());
  }));
}

const normalizeBody = (body: Record<string, unknown>) => ({
  ...body,
  email: typeof body?.email === "string" ? body.email.trim().toLowerCase() : body?.email,
});

router.get("/config", (_req, res) => {
  res.json({ data: {
    demoMode: process.env.DEMO_MODE === "true",
    pluggySandbox: process.env.PLUGGY_SANDBOX === "true",
  } });
});

router.post("/auth/signup", async (req, res): Promise<void> => {
  const parsed = signupSchema.safeParse(normalizeBody(req.body));
  if (!parsed.success || (parsed.success && Buffer.byteLength(parsed.data.password) > 72)) {
    apiError(res, 400, "VALIDATION_ERROR", "Confira nome, e-mail, senha (8 a 72 bytes) e aceite dos termos.");
    return;
  }
  const { name, email, password } = parsed.data;
  const passwordHash = await bcrypt.hash(password, 12);
  const [user] = await db.insert(users).values({ name, email, passwordHash }).onConflictDoNothing({ target: users.email }).returning();
  if (!user) {
    apiError(res, 409, "EMAIL_IN_USE", "Já existe uma conta com este e-mail.");
    return;
  }
  await startSession(req, user.id);
  res.status(201).json({ data: { user: await publicUser(user) } });
});

router.post("/auth/login", async (req, res): Promise<void> => {
  const parsed = loginSchema.safeParse(normalizeBody(req.body));
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Informe um e-mail válido e sua senha.");
    return;
  }
  const now = new Date();
  // Entries expire after 15 minutes, including for non-existent accounts.
  for (const [key, value] of loginAttempts) {
    if (now.getTime() - value.startedAt >= 15 * 60 * 1000) loginAttempts.delete(key);
  }
  const attempt = evaluateLoginAttempt(loginAttempts.get(parsed.data.email), now);
  if (!attempt.allowed) {
    res.set("Retry-After", String(attempt.retryAfterSeconds));
    apiError(res, 429, "LOGIN_RATE_LIMITED", "Muitas tentativas. Tente novamente em 15 minutos.");
    return;
  }
  loginAttempts.set(parsed.data.email, attempt.state);
  const [user] = await db.select().from(users).where(eq(users.email, parsed.data.email)).limit(1);
  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
    apiError(res, 401, "INVALID_CREDENTIALS", "E-mail ou senha incorretos.");
    return;
  }
  loginAttempts.delete(parsed.data.email);
  await startSession(req, user.id);
  res.json({ data: { user: await publicUser(user) } });
});

router.get("/me", requireAuth, async (req, res): Promise<void> => {
  const [user] = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
  if (!user) {
    apiError(res, 401, "UNAUTHENTICATED", "Entre na sua conta para continuar.");
    return;
  }
  res.json({ data: { user: await publicUser(user) } });
});

router.patch("/me", requireAuth, async (req, res): Promise<void> => {
  const parsed = UpdateMeBody.strict().safeParse(req.body);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Informe uma renda mensal válida.");
    return;
  }
  const [user] = await db.update(users).set({
    monthlyIncomeOverrideCents: parsed.data.monthlyIncomeOverrideCents,
    updatedAt: new Date(),
  }).where(eq(users.id, req.session.userId!)).returning();
  if (!user) {
    apiError(res, 401, "UNAUTHENTICATED", "Entre na sua conta para continuar.");
    return;
  }
  res.json(GetMeResponse.parse({ data: { user: await publicUser(user) } }));
});

router.post("/me/export", requireAuth, async (req, res): Promise<void> => {
  if (req.body && Object.keys(req.body).length > 0) {
    apiError(res, 400, "VALIDATION_ERROR", "A exportação não recebe dados adicionais.");
    return;
  }
  const userId = req.session.userId!;
  const rows = await db.select({
    date: transactions.date,
    description: transactions.descriptionRaw,
    account: accounts.name,
    category: categories.name,
    amountCents: transactions.amountCents,
  }).from(transactions)
    .innerJoin(accounts, and(eq(accounts.id, transactions.accountId), eq(accounts.userId, userId)))
    .leftJoin(categories, and(
      eq(categories.id, transactions.categoryId),
      or(isNull(categories.userId), eq(categories.userId, userId)),
    ))
    .where(eq(transactions.userId, userId))
    .orderBy(desc(transactions.date), desc(transactions.createdAt));
  const csv = exportTransactionsCsv(rows.map((row) => ({
    ...row,
    account: row.account ?? "Conta indisponível",
  })));
  res.setHeader("Content-Type", "text/csv; charset=utf-8");
  res.setHeader("Content-Disposition", 'attachment; filename="financas-pessoais.csv"');
  res.status(200).send(csv);
});

router.delete("/me", requireAuth, async (req, res): Promise<void> => {
  const userId = req.session.userId!;
  const deletion = await db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
    const [user] = await tx.select().from(users).where(eq(users.id, userId)).limit(1);
    if (!user) return null;
    const ownedConnections = await tx.select().from(connections).where(eq(connections.userId, userId));
    const unsupported = ownedConnections.some((connection) => connection.provider === "pluggy");
    if (unsupported) return { user, connections: ownedConnections, unsupported: true };

    await tx.update(connections).set({ status: "revoked", updatedAt: new Date() })
      .where(eq(connections.userId, userId));
    return { user, connections: ownedConnections, unsupported: false };
  });
  if (!deletion) {
    apiError(res, 401, "UNAUTHENTICATED", "Entre na sua conta para continuar.");
    return;
  }
  if (deletion.unsupported) {
    apiError(res, 503, "PROVIDER_UNAVAILABLE", "Uma conexão não pode ser revogada neste momento. Nenhum dado foi excluído.");
    return;
  }

  const providerConnections = deletion.connections.filter((connection) => connection.provider === "mock" && connection.status !== "revoked");
  try {
    if (providerConnections.length) {
      const provider = createProvider(deletion.user, deletion.connections, new Date());
      for (const connection of providerConnections) {
        await provider.revoke(connection.providerItemId ?? connection.id);
      }
    }
  } catch {
    apiError(res, 502, "PROVIDER_REVOKE_FAILED", "Não foi possível revogar uma conexão. Entre novamente e tente excluir a conta outra vez.");
    return;
  }

  const deleted = await db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
    const [stillExists] = await tx.select({ id: users.id }).from(users).where(eq(users.id, userId)).limit(1);
    if (!stillExists) return false;
    await tx.execute(sql`delete from "session" where sess->>'userId' = ${userId}`);
    await tx.insert(auditLog).values({
      userId,
      action: "account_deleted",
      metadata: { revokedConnectionCount: providerConnections.length },
      createdAt: new Date(),
    });
    await tx.delete(users).where(eq(users.id, userId));
    return true;
  });
  if (!deleted) {
    apiError(res, 401, "UNAUTHENTICATED", "Entre na sua conta para continuar.");
    return;
  }
  await new Promise<void>((resolve, reject) => req.session.destroy((error) => error ? reject(error) : resolve()));
  res.clearCookie(COOKIE, { path: "/" });
  res.json({ data: { ok: true } });
});

router.post("/auth/logout", requireAuth, async (req, res): Promise<void> => {
  await new Promise<void>((resolve, reject) => req.session.destroy((error) => error ? reject(error) : resolve()));
  res.clearCookie(COOKIE, { path: "/" });
  res.json({ data: { ok: true } });
});

router.post("/auth/logout-all", requireAuth, async (req, res): Promise<void> => {
  const userId = req.session.userId!;
  await pool.query("DELETE FROM session WHERE sess->>'userId' = $1", [userId]);
  await new Promise<void>((resolve, reject) => req.session.destroy((error) => error ? reject(error) : resolve()));
  res.clearCookie(COOKIE, { path: "/" });
  res.json({ data: { ok: true } });
});

export default router;
