import { Router, type IRouter } from "express";
import { z } from "zod/v4";
import { randomUUID } from "node:crypto";
import { and, eq, gte, ne, sql } from "drizzle-orm";
import { accounts, auditLog, connections, users, type Connection } from "@workspace/shared/schema";
import { db } from "../db/connection";
import { requireAuth } from "../middlewares/security";
import { apiError } from "../lib/errors";
import { uuid, booleanQuery } from "../lib/validation";
import { queueSync } from "../jobs/sync";
import { createProvider } from "../providers";
import { BANK, DIGITAL } from "../providers/mock/generate";

const router: IRouter = Router();
router.use(requireAuth);
export function connectionView(connection: Connection, now: Date) {
  const elapsed = now.getTime() - connection.createdAt.getTime();
  return {
    ...connection,
    syncStage: connection.status === "active" ? "complete" : elapsed < 1300 ? "connecting" : elapsed < 2800 ? "fetching" : "organizing",
  };
}
router.get("/connections", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) { apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida."); return; }
  const rows = await db.select().from(connections).where(eq(connections.userId, req.session.userId!));
  res.json({ data: rows.map((v) => connectionView(v, new Date())) });
});
router.get("/connections/:id", async (req, res): Promise<void> => {
  const id = uuid.safeParse(req.params.id);
  if (!id.success || !z.object({}).strict().safeParse(req.query).success) { apiError(res, 400, "VALIDATION_ERROR", "Identificador inválido."); return; }
  const [row] = await db.select().from(connections).where(and(eq(connections.id, id.data), eq(connections.userId, req.session.userId!))).limit(1);
  if (!row) { apiError(res, 404, "NOT_FOUND", "Conexão não encontrada."); return; }
  res.json({ data: connectionView(row, new Date()) });
});
router.post("/connections", async (req, res): Promise<void> => {
  const parsed = z.object({ provider: z.literal("mock"), institution: z.enum([BANK, DIGITAL]) }).strict().safeParse(req.body);
  if (!parsed.success || !z.object({}).strict().safeParse(req.query).success) { apiError(res, 400, "VALIDATION_ERROR", "Escolha uma instituição válida."); return; }
  if (process.env.DATA_PROVIDER !== "mock") { apiError(res, 409, "PROVIDER_UNAVAILABLE", "Este provedor não está disponível."); return; }
  const userId = req.session.userId!;
  const now = new Date();
  const connection = await db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
    const [existing] = await tx.select().from(connections).where(and(
      eq(connections.userId, userId), eq(connections.institutionName, parsed.data.institution), ne(connections.status, "revoked"),
    )).limit(1);
    if (existing) return existing;
    const id = randomUUID();
    const [created] = await tx.insert(connections).values({
      id, userId, provider: "mock", providerItemId: id, institutionName: parsed.data.institution,
      status: "syncing", createdAt: now, updatedAt: now,
    }).returning();
    return created;
  });
  if (connection.status !== "active") queueSync(userId, connection.id, { delayMs: Math.max(0, 4000 - (now.getTime() - connection.createdAt.getTime())) });
  res.status(202).json({ data: connectionView(connection, now) });
});
router.post("/connections/:id/sync", async (req, res): Promise<void> => {
  const id = uuid.safeParse(req.params.id);
  const query = z.object({ refresh: booleanQuery.default(false) }).strict().safeParse(req.query);
  if (!id.success || !query.success) { apiError(res, 400, "VALIDATION_ERROR", "Requisição de sincronização inválida."); return; }
  const userId = req.session.userId!;
  const [connection] = await db.select().from(connections).where(and(eq(connections.id, id.data), eq(connections.userId, userId))).limit(1);
  if (!connection) { apiError(res, 404, "NOT_FOUND", "Conexão não encontrada."); return; }
  if (connection.status === "revoked") { apiError(res, 409, "CONNECTION_REVOKED", "Conecte a instituição novamente."); return; }
  const now = new Date();
  if (query.data.refresh) {
    const [recent] = await db.select({ id: auditLog.id }).from(auditLog).where(and(
      eq(auditLog.userId, userId), eq(auditLog.action, "connection_refresh"),
      sql`${auditLog.metadata}->>'connectionId' = ${connection.id}`,
      gte(auditLog.createdAt, new Date(now.getTime() - 3600000)),
    )).limit(1);
    if (recent) { res.set("Retry-After", "3600"); apiError(res, 429, "REFRESH_RATE_LIMITED", "A nova coleta pode ser solicitada uma vez por hora."); return; }
  }
  const [updated] = await db.update(connections).set({ status: "syncing", updatedAt: now })
    .where(and(eq(connections.id, connection.id), eq(connections.userId, userId))).returning();
  queueSync(userId, connection.id, { refresh: query.data.refresh });
  res.status(202).json({ data: connectionView(updated, now) });
});
router.delete("/connections/:id", async (req, res): Promise<void> => {
  const id = uuid.safeParse(req.params.id);
  const query = z.object({ keepHistory: booleanQuery.default(true) }).strict().safeParse(req.query);
  if (!id.success || !query.success) { apiError(res, 400, "VALIDATION_ERROR", "Requisição inválida."); return; }
  const userId = req.session.userId!;
  const result = await db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
    const all = await tx.select().from(connections).where(eq(connections.userId, userId));
    const connection = all.find((v) => v.id === id.data);
    if (!connection) return false;
    const [user] = await tx.select().from(users).where(eq(users.id, userId)).limit(1);
    await createProvider(user, all, new Date()).revoke(connection.providerItemId ?? connection.id);
    await tx.update(connections).set({ status: "revoked", updatedAt: new Date() }).where(and(eq(connections.id, connection.id), eq(connections.userId, userId)));
    if (!query.data.keepHistory) await tx.delete(accounts).where(and(eq(accounts.connectionId, connection.id), eq(accounts.userId, userId)));
    return true;
  });
  if (!result) { apiError(res, 404, "NOT_FOUND", "Conexão não encontrada."); return; }
  res.json({ data: { ok: true } });
});
export default router;
