import { localDate } from "../lib/dates";

export const FREE_ASSISTANT_QUESTION_LIMIT = 20;

export type AssistantPlan = "free" | "premium";
export type StoredAssistantUsage = {
  plan: AssistantPlan;
  aiQuestionsUsed: number;
  aiQuestionsPeriod: string | null;
};
export type AssistantUsage = {
  used: number;
  limit: number;
  remaining: number;
  period: string;
  plan: AssistantPlan;
};

export function assistantUsageFor(user: StoredAssistantUsage, now: Date): AssistantUsage {
  const period = localDate(now).slice(0, 7);
  const used = user.aiQuestionsPeriod === period ? Math.max(0, user.aiQuestionsUsed) : 0;
  const limit = user.plan === "free" ? FREE_ASSISTANT_QUESTION_LIMIT : 0;
  return {
    used,
    limit,
    remaining: user.plan === "free" ? Math.max(0, limit - used) : 0,
    period,
    plan: user.plan,
  };
}

export function canAskAssistant(usage: AssistantUsage): boolean {
  return usage.plan === "premium" || usage.used < FREE_ASSISTANT_QUESTION_LIMIT;
}

export function nextAssistantUsage(usage: AssistantUsage): AssistantUsage {
  if (!canAskAssistant(usage)) throw new Error("AI_LIMIT_REACHED");
  const used = usage.used + 1;
  return {
    ...usage,
    used,
    remaining: usage.plan === "free" ? Math.max(0, usage.limit - used) : 0,
  };
}
