import type { Connection, User } from "@workspace/shared/schema";
import type { FinancialDataProvider } from "./types";
import { MockProvider } from "./mock";
export function createProvider(user: User, allConnections: Connection[], now: Date): FinancialDataProvider {
  if (process.env.DATA_PROVIDER !== "mock") throw new Error("DATA_PROVIDER must be mock in this stage.");
  return new MockProvider({
    email: user.email, name: user.name ?? user.email,
    anchors: allConnections.filter((v) => v.provider === "mock").map((v) => ({
      itemId: v.providerItemId ?? v.id, institution: v.institutionName, connectedAt: v.createdAt,
    })),
  }, now);
}
