import { Router, type IRouter } from "express";
import { and, eq, getTableColumns } from "drizzle-orm";
import { z } from "zod/v4";
import { accounts, connections } from "@workspace/shared/schema";
import { db } from "../db/connection";
import { requireAuth } from "../middlewares/security";
import { uuid } from "../lib/validation";
import { apiError } from "../lib/errors";
const router: IRouter = Router();
router.use(requireAuth);
const fields = { ...getTableColumns(accounts), institutionName: connections.institutionName };
router.get("/accounts", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) { apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida."); return; }
  const userId = req.session.userId!;
  const data = await db.select(fields).from(accounts).innerJoin(connections, and(eq(accounts.connectionId, connections.id), eq(connections.userId, userId))).where(eq(accounts.userId, userId));
  res.json({ data });
});
router.get("/accounts/:id", async (req, res): Promise<void> => {
  const id = uuid.safeParse(req.params.id);
  if (!id.success || !z.object({}).strict().safeParse(req.query).success) { apiError(res, 400, "VALIDATION_ERROR", "Identificador inválido."); return; }
  const userId = req.session.userId!;
  const [data] = await db.select(fields).from(accounts).innerJoin(connections, and(eq(accounts.connectionId, connections.id), eq(connections.userId, userId)))
    .where(and(eq(accounts.userId, userId), eq(accounts.id, id.data))).limit(1);
  if (!data) { apiError(res, 404, "NOT_FOUND", "Conta não encontrada."); return; }
  res.json({ data });
});
export default router;
