import type { FinancialDataProvider } from "../types";
import { ProviderError } from "../types";
import { addMonths, asDate, localDate } from "../../lib/dates";
import { generateMockData, type MockContext } from "./generate";

export class MockProvider implements FinancialDataProvider {
  private data;
  private revoked = new Set<string>();
  private consentExpirations = new Map<string, Date>();
  constructor(private context: MockContext, private now: Date) {
    this.data = generateMockData(context, now);
  }
  async getConnection(itemId: string) {
    const anchor = this.context.anchors.find((value) => value.itemId === itemId);
    if (!anchor) throw new ProviderError("CONNECTION_NOT_FOUND");
    return {
      status: this.revoked.has(itemId) ? "revoked" as const : this.now.getTime() - anchor.connectedAt.getTime() < 4000 ? "syncing" as const : "active" as const,
      institutionName: anchor.institution, institutionLogoUrl: null,
       consentExpiresAt: this.consentExpirations.get(itemId) ?? asDate(addMonths(localDate(anchor.connectedAt), 12)), lastErrorCode: null,
    };
  }
  async listAccounts(itemId: string) {
    const ledger = this.data.find((v) => v.anchor.itemId === itemId);
    if (!ledger) throw new ProviderError("CONNECTION_NOT_FOUND");
    return ledger.accounts;
  }
  async listTransactions(accountId: string, from: Date) {
    return this.data.flatMap((v) => v.transactions[accountId] ?? []).filter((v) => v.date >= localDate(from));
  }
  async listBills(accountId: string) { return this.data.flatMap((v) => v.bills[accountId] ?? []); }
  async refresh(itemId: string) {
    await this.getConnection(itemId);
    this.consentExpirations.set(itemId, asDate(addMonths(localDate(this.now), 12)));
  }
  async revoke(itemId: string) { await this.getConnection(itemId); this.revoked.add(itemId); }
}
