import cron from "node-cron";
import { eq } from "drizzle-orm";
import { connections } from "@workspace/shared/schema";
import { db } from "../db/connection";
import { queueSync } from "./sync";
import { logger } from "../lib/logger";

export function startSyncSchedule() {
  const task = cron.schedule("0 */6 * * *", async () => {
    try {
      const active = await db.select().from(connections).where(eq(connections.status, "active"));
      for (const connection of active) queueSync(connection.userId, connection.id);
    } catch { logger.warn("Scheduled synchronization could not start"); }
  }, { timezone: "America/Sao_Paulo", noOverlap: true });
  // Recover jobs interrupted by a process restart. C is never replaced.
  void db.select().from(connections).where(eq(connections.status, "syncing")).then((rows) => {
    for (const row of rows) queueSync(row.userId, row.id, { delayMs: Math.max(0, 4000 - (Date.now() - row.createdAt.getTime())) });
  }).catch(() => logger.warn("Pending synchronization recovery failed"));
  return task;
}
