export type ExportableTransaction = {
  date: string;
  description: string;
  account: string;
  category: string | null;
  amountCents: number;
};

function csvCell(value: string): string {
  return /[;"\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

function brazilianDate(value: string): string {
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(value);
  return match ? `${match[3]}/${match[2]}/${match[1]}` : value;
}

function brazilianAmount(cents: number): string {
  const negative = cents < 0 ? "-" : "";
  const absolute = Math.abs(cents);
  return `${negative}${Math.floor(absolute / 100)},${String(absolute % 100).padStart(2, "0")}`;
}

export function exportTransactionsCsv(rows: ExportableTransaction[]): string {
  const header = ["data", "descrição", "conta", "categoria", "valor"];
  const body = rows.map((row) => [
    brazilianDate(row.date),
    row.description,
    row.account,
    row.category ?? "Sem categoria",
    brazilianAmount(row.amountCents),
  ]);
  return `\uFEFF${[header, ...body].map((record) => record.map((cell) => csvCell(String(cell))).join(";")).join("\r\n")}\r\n`;
}
