import { addMonths, localDate, monthDate } from "../lib/dates";

export type AllowanceRecurrence = {
  id: string;
  kind: "subscription" | "fixed_bill" | "income";
  status: "active" | "ignored";
  expectedAmountCents: number;
};

export type AllowanceTransaction = {
  date: string;
  amountCents: number;
  categoryKind: "expense" | "income" | "transfer" | "review" | string;
  isTransfer: boolean;
  isBillPayment: boolean;
  installmentNumber: number | null;
  installmentTotal: number | null;
  installmentGroupKey: string | null;
  recurrenceId: string | null;
  deletedAt: Date | string | null;
};

export type InstallmentAmount = { date: string; amountCents: number };

export type AllowanceInput = {
  monthlyIncomeOverrideCents: number | null;
  savingsTargetCents: number;
  debtPlanMonthlyBudgetCents: number | null;
  hasThreeCompleteMonths: boolean;
  recurrences: AllowanceRecurrence[];
  transactions: AllowanceTransaction[];
  installmentItems: InstallmentAmount[];
};

export type AllowanceResult = {
  month: string;
  daysInMonth: number;
  daysRemaining: number;
  monthlyIncomeCents: number | null;
  incomeSource: "override" | "recurrence" | "history" | "missing";
  incomeSuggestionCents: number | null;
  fixedExpensesCents: number;
  installmentsCents: number;
  savingsReserveCents: number;
  debtPlanCents: number;
  variableBudgetCents: number | null;
  variableSpendCents: number | null;
  availableCents: number | null;
  dailyAllowanceCents: number;
  firstDayAllowanceCents: number | null;
  amountOverBudgetCents: number;
  status: "ok" | "apertado" | "estourado" | "precisa_renda";
};

type AllowanceMetrics = Pick<AllowanceResult,
  "availableCents" | "dailyAllowanceCents" | "firstDayAllowanceCents" | "amountOverBudgetCents" | "status"
>;

function calculateAllowanceMetrics(
  variableBudgetCents: number,
  variableSpendCents: number,
  numberOfDays: number,
  daysRemaining: number,
): AllowanceMetrics {
  const availableCents = variableBudgetCents - variableSpendCents;
  const dailyAllowanceCents = Math.max(0, Math.floor(availableCents / daysRemaining));
  const firstDayAllowanceCents = Math.floor(variableBudgetCents / numberOfDays);
  return {
    availableCents,
    dailyAllowanceCents,
    firstDayAllowanceCents,
    amountOverBudgetCents: Math.max(0, -availableCents),
    status: availableCents < 0
      ? "estourado"
      : dailyAllowanceCents * 100 < firstDayAllowanceCents * 20
        ? "apertado"
        : "ok",
  };
}

function daysInMonth(month: string): number {
  const [year, monthNumber] = month.split("-").map(Number);
  return new Date(Date.UTC(year!, monthNumber!, 0)).getUTCDate();
}

function isIncome(transaction: AllowanceTransaction): boolean {
  return transaction.deletedAt === null &&
    !transaction.isTransfer &&
    !transaction.isBillPayment &&
    transaction.categoryKind === "income" &&
    transaction.amountCents > 0;
}

function incomeFromHistory(input: AllowanceInput, month: string): number | null {
  if (!input.hasThreeCompleteMonths) return null;
  const currentMonthStart = monthDate(month, 1);
  const historyStart = addMonths(currentMonthStart, -3);
  const historyTotalCents = input.transactions
    .filter((transaction) =>
      transaction.date >= historyStart &&
      transaction.date < currentMonthStart &&
      isIncome(transaction),
    )
    .reduce((total, transaction) => total + transaction.amountCents, 0);
  return Math.round(historyTotalCents / 3);
}

function inferredIncome(input: AllowanceInput, month: string): { amount: number | null; source: "recurrence" | "history" | "missing" } {
  const activeIncome = input.recurrences.filter((recurrence) =>
    recurrence.status === "active" && recurrence.kind === "income",
  );
  if (activeIncome.length > 0) {
    return {
      amount: activeIncome.reduce((total, recurrence) => total + Math.abs(recurrence.expectedAmountCents), 0),
      source: "recurrence",
    };
  }
  const historyIncome = incomeFromHistory(input, month);
  if (historyIncome !== null) return { amount: historyIncome, source: "history" };
  return { amount: null, source: "missing" };
}

function isInstallment(transaction: AllowanceTransaction): boolean {
  return transaction.installmentNumber !== null ||
    transaction.installmentTotal !== null ||
    transaction.installmentGroupKey !== null;
}

export function calculateAllowance(input: AllowanceInput, now: Date): AllowanceResult {
  const today = localDate(now);
  const month = today.slice(0, 7);
  const numberOfDays = daysInMonth(month);
  const daysRemaining = numberOfDays - Number(today.slice(8, 10)) + 1;
  const currentMonthStart = monthDate(month, 1);
  const activeRecurrenceIds = new Set(
    input.recurrences.filter((recurrence) => recurrence.status === "active").map((recurrence) => recurrence.id),
  );
  const inferred = inferredIncome(input, month);
  const incomeSuggestionCents = inferred.amount === null
    ? null
    : Math.round(inferred.amount / 10_000) * 10_000;
  const monthlyIncomeCents = input.monthlyIncomeOverrideCents ?? inferred.amount;
  const incomeSource = input.monthlyIncomeOverrideCents !== null ? "override" : inferred.source;

  const fixedExpensesCents = input.recurrences
    .filter((recurrence) =>
      recurrence.status === "active" &&
      (recurrence.kind === "subscription" || recurrence.kind === "fixed_bill"),
    )
    .reduce((total, recurrence) => total + Math.abs(recurrence.expectedAmountCents), 0);
  const installmentsCents = input.installmentItems
    .filter((item) => item.date.slice(0, 7) === month && item.amountCents < 0)
    .reduce((total, item) => total + Math.abs(item.amountCents), 0);
  const savingsReserveCents = input.savingsTargetCents;
  const debtPlanCents = input.debtPlanMonthlyBudgetCents ?? 0;

  if (monthlyIncomeCents === null) {
    return {
      month,
      daysInMonth: numberOfDays,
      daysRemaining,
      monthlyIncomeCents: null,
      incomeSource: "missing",
      incomeSuggestionCents,
      fixedExpensesCents,
      installmentsCents,
      savingsReserveCents,
      debtPlanCents,
      variableBudgetCents: null,
      variableSpendCents: null,
      availableCents: null,
      dailyAllowanceCents: 0,
      firstDayAllowanceCents: null,
      amountOverBudgetCents: 0,
      status: "precisa_renda",
    };
  }

  const variableBudgetCents =
    monthlyIncomeCents -
    fixedExpensesCents -
    installmentsCents -
    savingsReserveCents -
    debtPlanCents;
  const variableSpendCents = input.transactions
    .filter((transaction) => {
      const activeRecurrenceExpense = transaction.recurrenceId !== null &&
        activeRecurrenceIds.has(transaction.recurrenceId);
      return transaction.date >= currentMonthStart &&
        transaction.date <= today &&
        transaction.deletedAt === null &&
        transaction.amountCents < 0 &&
        (transaction.categoryKind === "expense" || transaction.categoryKind === "review") &&
        !transaction.isTransfer &&
        !transaction.isBillPayment &&
        !isInstallment(transaction) &&
        !activeRecurrenceExpense;
    })
    .reduce((total, transaction) => total + Math.abs(transaction.amountCents), 0);
  const metrics = calculateAllowanceMetrics(variableBudgetCents, variableSpendCents, numberOfDays, daysRemaining);

  return {
    month,
    daysInMonth: numberOfDays,
    daysRemaining,
    monthlyIncomeCents,
    incomeSource,
    incomeSuggestionCents,
    fixedExpensesCents,
    installmentsCents,
    savingsReserveCents,
    debtPlanCents,
    variableBudgetCents,
    variableSpendCents,
    ...metrics,
  };
}

export function calculateAllowanceWithAdditionalInstallment(
  current: AllowanceResult,
  additionalInstallmentCents: number,
): AllowanceResult {
  if (!Number.isSafeInteger(additionalInstallmentCents) || additionalInstallmentCents < 0) {
    throw new Error("Additional installment must be a non-negative integer.");
  }
  if (current.monthlyIncomeCents === null || current.variableBudgetCents === null || current.variableSpendCents === null) {
    return current;
  }
  const variableBudgetCents = current.variableBudgetCents - additionalInstallmentCents;
  const metrics = calculateAllowanceMetrics(
    variableBudgetCents,
    current.variableSpendCents,
    current.daysInMonth,
    current.daysRemaining,
  );
  return {
    ...current,
    installmentsCents: current.installmentsCents + additionalInstallmentCents,
    variableBudgetCents,
    ...metrics,
  };
}
