import { Router, type IRouter } from "express";
import { z } from "zod/v4";
import { and, eq, isNull, or, gte, lte, ilike, inArray, lt, desc, sql } from "drizzle-orm";
import { categories, transactions } from "@workspace/shared/schema";
import { db } from "../db/connection";
import { listQuery, cursorSchema } from "../lib/validation";
import { requireAuth } from "../middlewares/security";
import { findOwnedTransaction, transactionQuery } from "../db/repositories/transactions";
import { apiError } from "../lib/errors";
import { UpdateTransactionBody } from "@workspace/api-zod";
import { correctTransaction, CorrectionError } from "../db/repositories/transaction-corrections";

const router: IRouter = Router();
router.get("/categories", requireAuth, async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) { apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida."); return; }
  const data = await db.select().from(categories).where(or(isNull(categories.userId), eq(categories.userId, req.session.userId!))).orderBy(categories.sortOrder, categories.name);
  res.json({ data });
});
router.get("/transactions", requireAuth, async (req, res): Promise<void> => {
  const parsed = listQuery.safeParse(req.query);
  if (!parsed.success) { apiError(res, 400, "VALIDATION_ERROR", "Confira os filtros e o período."); return; }
  const query = parsed.data;
  let cursor: z.infer<typeof cursorSchema> | undefined;
  if (query.cursor) {
    try { cursor = cursorSchema.parse(JSON.parse(Buffer.from(query.cursor, "base64url").toString("utf8"))); }
    catch { apiError(res, 400, "VALIDATION_ERROR", "Cursor de paginação inválido."); return; }
  }
  const userId = req.session.userId!;
  const condition = [
    query.accountId ? eq(transactions.accountId, query.accountId) : undefined,
    query.categoryId ? eq(transactions.categoryId, query.categoryId) : undefined,
    query.from ? gte(transactions.date, query.from) : undefined,
    query.to ? lte(transactions.date, query.to) : undefined,
    query.q ? or(ilike(transactions.descriptionRaw, `%${query.q.replace(/[\\%_]/g, "\\$&")}%`), ilike(transactions.merchantName, `%${query.q.replace(/[\\%_]/g, "\\$&")}%`)) : undefined,
    query.ids ? inArray(transactions.id, query.ids) : undefined,
    query.needsReview ? inArray(transactions.categoryId, db.select({ id: categories.id }).from(categories).where(and(eq(categories.kind, "review"), or(isNull(categories.userId), eq(categories.userId, userId))))) : undefined,
  ];
  const rows = await transactionQuery(userId, [...condition, cursor ? or(lt(transactions.date, cursor.date), and(eq(transactions.date, cursor.date), lt(transactions.id, cursor.id))) : undefined])
    .orderBy(desc(transactions.date), desc(transactions.id)).limit(query.limit + 1);
  const hasMore = rows.length > query.limit;
  const data = rows.slice(0, query.limit);
  const last = data.at(-1);
  const totals = await db.select({ date: transactions.date, total: sql<string>`sum(${transactions.amountCents})` }).from(transactions)
    .where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt), ...condition)).groupBy(transactions.date);
  const [review] = await db.select({ count: sql<string>`count(*)` }).from(transactions).innerJoin(categories, eq(transactions.categoryId, categories.id))
    .where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt), eq(categories.kind, "review"), or(isNull(categories.userId), eq(categories.userId, userId))));
  res.json({
    data, nextCursor: hasMore && last ? Buffer.from(JSON.stringify({ date: last.date, id: last.id })).toString("base64url") : null,
    dayTotals: Object.fromEntries(totals.map((v) => [v.date, Number(v.total)])), reviewCount: Number(review.count),
  });
});
const correctionBody = UpdateTransactionBody.strict().refine((data) =>
  (data.categoryId !== undefined || data.isTransfer !== undefined || data.notes !== undefined)
  && (!data.applyToSimilar || data.categoryId !== undefined),
);
router.patch("/transactions/:id", requireAuth, async (req, res): Promise<void> => {
  const id = z.uuid().safeParse(req.params.id);
  const parsed = correctionBody.safeParse(req.body);
  if (!id.success || !parsed.success || !z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Confira os campos da transação.");
    return;
  }
  const userId = req.session.userId!;
  try {
    const updatedCount = await correctTransaction(userId, id.data, parsed.data, new Date());
    const data = await findOwnedTransaction(userId, id.data);
    res.json({ data, updatedCount });
  } catch (error) {
    if (error instanceof CorrectionError) { apiError(res, 404, error.code, error.code === "NOT_FOUND" ? "Transação não encontrada." : "Categoria indisponível."); return; }
    throw error;
  }
});
router.get("/transactions/:id", requireAuth, async (req, res): Promise<void> => {
  const id = z.uuid().safeParse(req.params.id);
  if (!id.success || !z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Identificador inválido.");
    return;
  }
  const transaction = await findOwnedTransaction(req.session.userId!, id.data);
  if (!transaction) {
    apiError(res, 404, "NOT_FOUND", "Transação não encontrada.");
    return;
  }
  res.json({ data: transaction });
});
export default router;
