import { z } from "zod/v4";
export const uuid = z.uuid();
export const booleanQuery = z.enum(["true", "false"]).transform((v) => v === "true");
export const listQuery = z.object({
  cursor: z.string().max(500).optional(),
  limit: z.coerce.number().int().min(1).max(100).default(50),
  accountId: uuid.optional(), categoryId: uuid.optional(),
  from: z.iso.date().optional(), to: z.iso.date().optional(),
  q: z.string().trim().max(200).optional(),
  needsReview: booleanQuery.optional(),
  ids: z.string().transform((v) => v.split(",")).pipe(z.array(uuid).min(1).max(100)).optional(),
}).strict().refine((v) => !v.from || !v.to || v.from <= v.to, "Período inválido");
export const cursorSchema = z.object({ date: z.iso.date(), id: uuid }).strict();
