import { createHash } from "node:crypto";
import type { ProviderTransaction } from "../providers/types";

export const sha1 = (value: string) => createHash("sha1").update(value).digest("hex");
export const plainName = (value: string) => value.normalize("NFD").replace(/\p{M}/gu, "").toUpperCase().trim().replace(/\s+/g, " ");
export const originalIdentity = (value: string) => value.toUpperCase().trim().replace(/\s+/g, " ");
export function normalizeDescription(value: string): string {
  return plainName(value)
    .replace(/\bPARC(?:ELA)?\s?\d{1,2}\s?(?:\/|DE)\s?\d{1,2}\b/g, " ")
    .replace(/\b\d{2}\/\d{2}(?:\/\d{2,4})?\b/g, " ")
    .replace(/[*.\-/]/g, " ").replace(/\s+/g, " ").trim();
}
function samePerson(a: string, b: string): boolean {
  const first = plainName(a).split(" ");
  const second = plainName(b).split(" ");
  return first.length >= 2 && second.length >= 2 && first[0] === second[0] && first.at(-1) === second.at(-1);
}
function title(value: string): string {
  return value.toLocaleLowerCase("pt-BR").split(" ").map((v) => v.length === 1 ? `${v.toUpperCase()}.` : v[0]?.toUpperCase() + v.slice(1)).join(" ");
}
export function normalizeTransaction(input: ProviderTransaction, userName: string, accountType: string, _now: Date) {
  const descriptionNorm = normalizeDescription(input.description);
  const paymentMethod = input.paymentMethod ?? (/\bPIX\b/.test(descriptionNorm) ? "pix" : /\bBOLETO\b/.test(descriptionNorm) ? "boleto" : /\bTED\b/.test(descriptionNorm) ? "ted" : accountType === "credit_card" ? "card" : "other");
  const personPix = paymentMethod === "pix" && input.counterpart?.type === "person";
  const ownPix = !!personPix && samePerson(input.counterpart!.name, userName);
  const merchantKey = ownPix ? "PIX PROPRIA" : personPix
    ? `PIX P-${sha1(plainName(input.counterpart!.name)).slice(0, 6)}`
    : descriptionNorm.split(" ").slice(0, 3).join(" ");
  let merchantName = title(descriptionNorm);
  if (personPix) merchantName = title(input.counterpart!.name);
  else if (/^IFOOD\b/.test(descriptionNorm)) merchantName = `iFood · ${title(descriptionNorm.replace(/^IFOOD\s*/, ""))}`;
  else if (/^UBER EATS\b/.test(descriptionNorm)) merchantName = `Uber Eats · ${title(descriptionNorm.replace(/^UBER EATS\s*/, ""))}`;
  else if (/^UBER\b/.test(descriptionNorm)) merchantName = "Uber";
  else if (/^NETFLIX\b/.test(descriptionNorm)) merchantName = "Netflix";
  const digits = input.counterpart?.document?.replace(/\D/g, "") ?? "";
  const counterpartDocMasked = !digits ? null : input.counterpart?.type === "person"
    ? digits.length === 11 ? `***.${digits.slice(3, 6)}.${digits.slice(6, 9)}-**` : null
    : input.counterpart?.document ?? null;
  return { descriptionNorm, merchantKey, merchantName, paymentMethod, counterpartDocMasked, ownPix };
}

export function identifyTransactions(accountId: string, values: ProviderTransaction[], _now: Date) {
  const ordinals = new Map<string, number>();
  return [...values].sort((a, b) => a.providerTransactionId.localeCompare(b.providerTransactionId)).map((value) => {
    const group = JSON.stringify([accountId, value.date, value.amountCents, originalIdentity(value.description)]);
    const ordinal = ordinals.get(group) ?? 0;
    ordinals.set(group, ordinal + 1);
    return {
      value,
      dedupeKey: value.providerStableId ? `p:${value.providerStableId}` : sha1(JSON.stringify([accountId, value.date, value.amountCents, originalIdentity(value.description), ordinal])),
    };
  });
}
