import { Router, type IRouter } from "express";
import { and, asc, desc, eq, sql } from "drizzle-orm";
import {
  ActivateDebtPlanBody,
  ActivateDebtPlanResponse,
  CreateDebtBody,
  CreateDebtResponse,
  DeleteDebtParams,
  DeleteDebtResponse,
  GetActiveDebtPlanResponse,
  GetDebtParams,
  GetDebtResponse,
  GetDebtsResponse,
  SimulateDebtsBody,
  SimulateDebtsResponse,
  UpdateDebtBody,
  UpdateDebtParams,
  UpdateDebtResponse,
} from "@workspace/api-zod";
import { accounts, debts, debtPlans } from "@workspace/shared/schema";
import { z } from "zod/v4";
import { db } from "../db/connection";
import { apiError } from "../lib/errors";
import { localDate } from "../lib/dates";
import { requireAuth } from "../middlewares/security";
import { DebtSimulationError, simulateDebtStrategies } from "../services/debts";

const router: IRouter = Router();
router.use(requireAuth);

const debtSimulationErrorOutput = z.object({
  error: z.object({
    code: z.enum(["BUDGET_BELOW_MINIMUMS", "BUDGET_BELOW_INTEREST"]),
    message: z.string(),
    requiredBudgetCents: z.number().int().nonnegative(),
  }),
});

async function listDebtRows(userId: string) {
  return db.select({
    id: debts.id,
    name: debts.name,
    kind: debts.kind,
    balanceCents: debts.balanceCents,
    monthlyRateBps: debts.monthlyRateBps,
    rateIsEstimated: debts.rateIsEstimated,
    minimumPaymentCents: debts.minimumPaymentCents,
    source: debts.source,
    accountId: debts.accountId,
    accountName: accounts.name,
    confirmed: debts.confirmed,
    createdAt: debts.createdAt,
    updatedAt: debts.updatedAt,
  }).from(debts).leftJoin(accounts, and(
    eq(accounts.id, debts.accountId),
    eq(accounts.userId, userId),
  )).where(eq(debts.userId, userId)).orderBy(desc(debts.confirmed), asc(debts.name));
}

async function confirmedDebtRows(userId: string) {
  return db.select({
    id: debts.id,
    name: debts.name,
    balanceCents: debts.balanceCents,
    monthlyRateBps: debts.monthlyRateBps,
    minimumPaymentCents: debts.minimumPaymentCents,
  }).from(debts).where(and(
    eq(debts.userId, userId),
    eq(debts.confirmed, true),
  )).orderBy(asc(debts.name));
}

function respondSimulationError(res: Parameters<typeof apiError>[0], error: DebtSimulationError): void {
  res.status(422).json(debtSimulationErrorOutput.parse({
    error: {
      code: error.code,
      message: error.message,
      requiredBudgetCents: error.requiredBudgetCents,
    },
  }));
}

router.get("/debts", async (req, res): Promise<void> => {
  const data = await listDebtRows(req.session.userId!);
  res.json(GetDebtsResponse.parse({ data }));
});

router.post("/debts", async (req, res): Promise<void> => {
  const parsed = CreateDebtBody.strict().safeParse(req.body);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Confira os dados da dívida.");
    return;
  }
  const userId = req.session.userId!;
  if (parsed.data.accountId) {
    const [ownedAccount] = await db.select({ id: accounts.id }).from(accounts).where(and(
      eq(accounts.id, parsed.data.accountId),
      eq(accounts.userId, userId),
    )).limit(1);
    if (!ownedAccount) {
      apiError(res, 400, "VALIDATION_ERROR", "A conta informada não pertence a este perfil.");
      return;
    }
  }
  const now = new Date();
  const [created] = await db.insert(debts).values({
    userId,
    name: parsed.data.name.trim(),
    kind: parsed.data.kind,
    balanceCents: parsed.data.balanceCents,
    monthlyRateBps: parsed.data.monthlyRateBps,
    rateIsEstimated: false,
    minimumPaymentCents: Math.min(parsed.data.balanceCents, parsed.data.minimumPaymentCents),
    source: "user",
    accountId: parsed.data.accountId ?? null,
    confirmed: true,
    createdAt: now,
    updatedAt: now,
  }).returning({ id: debts.id });
  const [result] = await listDebtRows(userId).then((rows) => rows.filter((row) => row.id === created?.id));
  if (!result) {
    apiError(res, 500, "CREATE_FAILED", "Não foi possível criar a dívida.");
    return;
  }
  res.status(201).json(CreateDebtResponse.parse({ data: result }));
});

router.get("/debts/:id", async (req, res): Promise<void> => {
  const parsed = GetDebtParams.strict().safeParse(req.params);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Dívida inválida.");
    return;
  }
  const [debt] = (await listDebtRows(req.session.userId!)).filter((row) => row.id === parsed.data.id);
  if (!debt) {
    apiError(res, 404, "NOT_FOUND", "Dívida não encontrada.");
    return;
  }
  res.json(GetDebtResponse.parse({ data: debt }));
});

router.patch("/debts/:id", async (req, res): Promise<void> => {
  const params = UpdateDebtParams.strict().safeParse(req.params);
  const body = UpdateDebtBody.strict().safeParse(req.body);
  if (!params.success || !body.success || Object.keys(body.data ?? {}).length === 0) {
    apiError(res, 400, "VALIDATION_ERROR", "Confira os dados da dívida.");
    return;
  }
  const update: Partial<typeof debts.$inferInsert> = {
    ...body.data,
    ...(body.data.monthlyRateBps === undefined ? {} : { rateIsEstimated: false }),
    updatedAt: new Date(),
  };
  if (body.data.name !== undefined) update.name = body.data.name.trim();
  if (body.data.balanceCents !== undefined) {
    const [current] = await db.select({ balanceCents: debts.balanceCents }).from(debts).where(and(
      eq(debts.id, params.data.id),
      eq(debts.userId, req.session.userId!),
    )).limit(1);
    if (!current) {
      apiError(res, 404, "NOT_FOUND", "Dívida não encontrada.");
      return;
    }
    update.balanceCents = body.data.balanceCents;
  }
  const [updated] = await db.update(debts).set(update).where(and(
    eq(debts.id, params.data.id),
    eq(debts.userId, req.session.userId!),
  )).returning({ id: debts.id });
  if (!updated) {
    apiError(res, 404, "NOT_FOUND", "Dívida não encontrada.");
    return;
  }
  const [result] = (await listDebtRows(req.session.userId!)).filter((row) => row.id === updated.id);
  res.json(UpdateDebtResponse.parse({ data: result }));
});

router.delete("/debts/:id", async (req, res): Promise<void> => {
  const parsed = DeleteDebtParams.strict().safeParse(req.params);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Dívida inválida.");
    return;
  }
  const deleted = await db.delete(debts).where(and(
    eq(debts.id, parsed.data.id),
    eq(debts.userId, req.session.userId!),
  )).returning({ id: debts.id });
  if (!deleted.length) {
    apiError(res, 404, "NOT_FOUND", "Dívida não encontrada.");
    return;
  }
  res.json(DeleteDebtResponse.parse({ data: { ok: true } }));
});

router.post("/debts/simulate", async (req, res): Promise<void> => {
  const parsed = SimulateDebtsBody.strict().safeParse(req.body);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Informe um orçamento mensal em centavos.");
    return;
  }
  try {
    const data = simulateDebtStrategies(await confirmedDebtRows(req.session.userId!), parsed.data.monthlyBudgetCents);
    res.json(SimulateDebtsResponse.parse({ data }));
  } catch (error) {
    if (error instanceof DebtSimulationError) {
      respondSimulationError(res, error);
      return;
    }
    if (error instanceof RangeError) {
      apiError(res, 400, "VALIDATION_ERROR", error.message);
      return;
    }
    throw error;
  }
});

router.get("/debt-plans", async (req, res): Promise<void> => {
  const [activePlan] = await db.select().from(debtPlans).where(and(
    eq(debtPlans.userId, req.session.userId!),
    eq(debtPlans.active, true),
  )).orderBy(desc(debtPlans.startedAt), desc(debtPlans.updatedAt)).limit(1);
  res.json(GetActiveDebtPlanResponse.parse({ data: activePlan ?? null }));
});

router.post("/debt-plans", async (req, res): Promise<void> => {
  const parsed = ActivateDebtPlanBody.strict().safeParse(req.body);
  if (!parsed.success || parsed.data.monthlyBudgetCents <= 0) {
    apiError(res, 400, "VALIDATION_ERROR", "Informe uma estratégia e um orçamento mensal maior que zero.");
    return;
  }
  const userId = req.session.userId!;
  const confirmed = await confirmedDebtRows(userId);
  if (confirmed.length === 0) {
    apiError(res, 400, "NO_CONFIRMED_DEBTS", "Confirme ao menos uma dívida antes de ativar o plano.");
    return;
  }
  try {
    simulateDebtStrategies(confirmed, parsed.data.monthlyBudgetCents);
  } catch (error) {
    if (error instanceof DebtSimulationError) {
      respondSimulationError(res, error);
      return;
    }
    throw error;
  }

  const now = new Date();
  const [created] = await db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${userId}, 0))`);
    await tx.update(debtPlans).set({ active: false, updatedAt: now })
      .where(and(eq(debtPlans.userId, userId), eq(debtPlans.active, true)));
    return tx.insert(debtPlans).values({
      userId,
      strategy: parsed.data.strategy,
      monthlyBudgetCents: parsed.data.monthlyBudgetCents,
      active: true,
      startedAt: localDate(now),
      createdAt: now,
      updatedAt: now,
    }).returning();
  });
  if (!created) {
    apiError(res, 500, "CREATE_FAILED", "Não foi possível ativar o plano.");
    return;
  }
  res.status(201).json(ActivateDebtPlanResponse.parse({ data: created }));
});

export default router;
