import { and, eq, inArray, isNull, ne, or } from "drizzle-orm";
import { categories, categoryRules, transactions, users } from "@workspace/shared/schema";
import { batchProcess } from "@workspace/integrations-anthropic-ai/batch";
import type { DatabaseTransaction } from "../db/types";
import { classifyBatch, type BatchClassifier } from "../assistant/categorization";
import { categorizationInput, maskSensitiveText } from "../assistant/masking";
import { finishCategorization, parseCategoryResponse, prepareCategorization, type CategoryPrediction } from "../services/categorization";
import { logger } from "../lib/logger";

export async function runCategorization(tx: DatabaseTransaction, userId: string, now: Date, classify: BatchClassifier = classifyBatch) {
  const [user] = await tx.select({ name: users.name }).from(users).where(eq(users.id, userId)).limit(1);
  if (!user) return;
  const catalog = await tx.select().from(categories).where(or(isNull(categories.userId), eq(categories.userId, userId)));
  const rules = await tx.select({ merchantKey: categoryRules.merchantKey, categoryId: categoryRules.categoryId }).from(categoryRules)
    .innerJoin(categories, and(eq(categories.id, categoryRules.categoryId), or(isNull(categories.userId), eq(categories.userId, userId))))
    .where(eq(categoryRules.userId, userId));
  const items = await tx.select().from(transactions).where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt), ne(transactions.categorySource, "user")));
  const { decisions, pending } = prepareCategorization(items, catalog, rules, now);
  const personNames = [user.name ?? "", ...items.filter((v) => v.counterpartType === "person").map((v) => v.counterpartName ?? "")];
  const names = catalog.filter((c) => c.userId === null || !maskSensitiveText(c.name, personNames).includes("[")).map((c) => c.name);
  const predictions: CategoryPrediction[] = [];
  // Sequential batches bound requests and preserve successful batches if another fails.
  for (let start = 0; start < pending.length; start += 50) {
    const batch = pending.slice(start, start + 50).map((v) => categorizationInput(v, user.name ?? "", now));
    let jsonAttempts = 0;
    try {
      const [result] = await batchProcess([batch], async (input) => {
        while (jsonAttempts < 2) {
          const text = await classify(input, names);
          jsonAttempts++;
          const parsed = parseCategoryResponse(text, input.map((v) => v.id), names, now);
          if (parsed) return parsed;
        }
        return [];
      }, { concurrency: 1, retries: 2, minTimeout: 500, maxTimeout: 2000 });
      predictions.push(...result);
    } catch {
      // No provider responses, IDs, descriptions, amounts or personal data in logs.
      logger.warn("AI categorization unavailable; using fallback");
    }
  }
  decisions.push(...finishCategorization(pending, predictions, catalog, now));
  const originals = new Map(items.map((item) => [item.id, item]));
  const groups = new Map<string, { decision: typeof decisions[number]; ids: string[] }>();
  for (const decision of decisions) {
    const original = originals.get(decision.id)!;
    if (original.categoryId === decision.categoryId && original.categorySource === decision.categorySource && original.categoryConfidence === decision.categoryConfidence) continue;
    const key = JSON.stringify([decision.categoryId, decision.categorySource, decision.categoryConfidence]);
    const group = groups.get(key) ?? { decision, ids: [] };
    group.ids.push(decision.id);
    groups.set(key, group);
  }
  for (const { decision, ids } of groups.values()) {
    await tx.update(transactions).set({ categoryId: decision.categoryId, categorySource: decision.categorySource, categoryConfidence: decision.categoryConfidence, updatedAt: now })
      .where(and(eq(transactions.userId, userId), inArray(transactions.id, ids), ne(transactions.categorySource, "user"), isNull(transactions.deletedAt)));
  }
}
