import type { DatabaseTransaction } from "../db/types";
import type { BatchClassifier } from "../assistant/categorization";
import { runCategorization } from "./categorization";
import { runFinancialRules } from "./financial-rules";
import { runAlertEvaluationInTransaction } from "./alerts";

export async function runPostSyncPipeline(context: { tx: DatabaseTransaction; userId: string; now: Date; classify?: BatchClassifier }): Promise<void> {
  await runCategorization(context.tx, context.userId, context.now, context.classify);
  await runFinancialRules(context.tx, context.userId, context.now);
  await runAlertEvaluationInTransaction(context.tx, context.userId, context.now);
}
