import { addDays, localDate } from "../lib/dates";
import { calculateProjection } from "./projection";

export const ALERT_TYPES = [
  "duplicate_charge",
  "unusual_spend",
  "subscription_price_change",
  "negative_projection",
  "bill_due",
  "budget_exceeded",
  "consent_expiring",
  "sync_error",
] as const;

export const ALERT_PREFERENCE_TYPES = [...ALERT_TYPES, "weekly_summary"] as const;
export type AlertType = (typeof ALERT_TYPES)[number];
export type AlertPreferenceType = (typeof ALERT_PREFERENCE_TYPES)[number];
export type AlertSeverity = "info" | "warning" | "critical";

export type AlertDraft = {
  type: AlertPreferenceType;
  severity: AlertSeverity;
  title: string;
  body: string;
  payload: Record<string, unknown>;
  dedupeKey: string;
};

export type AlertTransaction = {
  id: string;
  date: string;
  merchantKey: string;
  merchantName: string | null;
  accountId: string;
  accountName: string | null;
  accountType: "checking" | "savings" | "credit_card" | "cash";
  amountCents: number;
  categoryId: string;
  categoryName: string;
  categoryKind: "expense" | "income" | "transfer" | "review";
  isTransfer: boolean;
  isBillPayment: boolean;
  installmentNumber: number | null;
  installmentTotal: number | null;
  installmentGroupKey: string | null;
  recurrenceId: string | null;
  deletedAt: Date | null;
};

export type AlertRecurrence = {
  id: string;
  accountType: "checking" | "savings" | "credit_card" | "cash" | null;
  kind: "subscription" | "fixed_bill" | "income";
  label: string;
  status: "active" | "ignored";
  expectedAmountCents: number;
  previousAmountCents: number | null;
  nextExpectedDate: string;
};

export type AlertBill = {
  id: string;
  accountId: string;
  accountName: string;
  dueDate: string;
  totalCents: number;
  paidCents: number;
};

export type AlertConnection = {
  id: string;
  institutionName: string;
  status: string;
  consentExpiresAt: Date | null;
};

export type AlertBudget = { categoryId: string; limitCents: number };

export type AlertEvaluationData = {
  accounts: { id: string; name: string; type: AlertTransaction["accountType"]; balanceCents: number }[];
  transactions: AlertTransaction[];
  recurrences: AlertRecurrence[];
  bills: AlertBill[];
  budgets: AlertBudget[];
  connections: AlertConnection[];
};

const money = (cents: number) =>
  new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Math.abs(cents) / 100);
const installment = (row: AlertTransaction) =>
  row.installmentNumber !== null || row.installmentTotal !== null || row.installmentGroupKey !== null;
const normalExpense = (row: AlertTransaction) =>
  row.deletedAt === null && row.amountCents < 0 && row.categoryKind === "expense" &&
  !row.isTransfer && !row.isBillPayment && !installment(row) && row.recurrenceId === null;
const localStart = (day: string) => new Date(`${day}T03:00:00.000Z`);
const weekStart = (day: string) => {
  const weekday = new Date(`${day}T12:00:00.000Z`).getUTCDay();
  return addDays(day, -((weekday + 6) % 7));
};

export function alertInfoWeekBounds(now: Date): { start: Date; end: Date } {
  const startDay = weekStart(localDate(now));
  return { start: localStart(startDay), end: localStart(addDays(startDay, 7)) };
}

function medianTwice(values: number[]): number {
  const ordered = [...values].sort((a, b) => a - b);
  const middle = Math.floor(ordered.length / 2);
  return ordered.length % 2 === 1
    ? 2 * ordered[middle]!
    : ordered[middle - 1]! + ordered[middle]!;
}

function duplicateAlerts(rows: AlertTransaction[], today: string): AlertDraft[] {
  const groups = new Map<string, AlertTransaction[]>();
  for (const row of rows) {
    if (row.deletedAt !== null || row.date < addDays(today, -7) || row.date > today || row.amountCents >= 0 ||
      row.isTransfer || row.isBillPayment || installment(row) || row.recurrenceId !== null || !row.merchantKey) continue;
    const key = JSON.stringify([row.accountId, row.merchantKey, row.amountCents]);
    const group = groups.get(key) ?? [];
    group.push(row);
    groups.set(key, group);
  }

  const candidates: AlertDraft[] = [];
  for (const group of groups.values()) {
    const ordered = [...group].sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id));
    let cluster: AlertTransaction[] = [];
    const emit = () => {
      if (cluster.length < 2) return;
      const ids = cluster.map((row) => row.id).sort();
      const merchant = cluster[0]!.merchantName || cluster[0]!.merchantKey;
      candidates.push({
        type: "duplicate_charge", severity: "warning", title: "Cobrança duplicada?",
        body: `Há ${cluster.length} cobranças de ${merchant}, no valor de ${money(cluster[0]!.amountCents)}.`,
        payload: { transactionIds: ids, merchantKey: cluster[0]!.merchantKey, accountId: cluster[0]!.accountId },
        dedupeKey: `dup:${ids.join(",")}`,
      });
    };
    for (const row of ordered) {
      if (cluster.length && row.date > addDays(cluster[0]!.date, 2)) {
        emit();
        cluster = [];
      }
      cluster.push(row);
    }
    emit();
  }
  return candidates;
}

function unusualSpendAlerts(rows: AlertTransaction[], today: string): AlertDraft[] {
  const recent = rows.filter((row) => row.deletedAt === null && row.date >= addDays(today, -7) && row.date <= today);
  const candidates: AlertDraft[] = [];
  for (const row of recent) {
    if (!normalExpense(row) || Math.abs(row.amountCents) < 15_000) continue;
    const baseline = rows.filter((value) =>
      normalExpense(value) && value.categoryId === row.categoryId &&
      value.date >= addDays(row.date, -90) && value.date < row.date,
    );
    if (baseline.length < 5) continue;
    const medianByTwo = medianTwice(baseline.map((value) => Math.abs(value.amountCents)));
    if (BigInt(Math.abs(row.amountCents)) * 2n < BigInt(medianByTwo) * 3n) continue;
    const merchant = row.merchantName || row.merchantKey;
    candidates.push({
      type: "unusual_spend", severity: "info", title: "Gasto fora do padrão",
      body: `${merchant} ficou bem acima do padrão recente em ${row.categoryName}.`,
      payload: { transactionId: row.id, categoryId: row.categoryId, amountCents: Math.abs(row.amountCents) },
      dedupeKey: `unusual:${row.id}`,
    });
  }
  return candidates;
}

function subscriptionPriceAlerts(rows: AlertTransaction[], recurrences: AlertRecurrence[], today: string): AlertDraft[] {
  const candidates: AlertDraft[] = [];
  for (const recurrence of recurrences) {
    if (recurrence.status !== "active" || recurrence.kind !== "subscription" ||
      recurrence.previousAmountCents === null || recurrence.previousAmountCents === 0) continue;
    const latest = rows.filter((row) => row.deletedAt === null && row.recurrenceId === recurrence.id)
      .sort((a, b) => b.date.localeCompare(a.date) || b.id.localeCompare(a.id))[0];
    if (!latest || latest.date < addDays(today, -35) || latest.date > today) continue;
    const previous = Math.abs(recurrence.previousAmountCents);
    const current = Math.abs(recurrence.expectedAmountCents);
    if (Math.abs(current - previous) * 100 <= previous * 5) continue;
    const movement = current > previous ? "subiu" : "caiu";
    candidates.push({
      type: "subscription_price_change", severity: "info", title: "Mudança no preço da assinatura",
      body: `${recurrence.label} ${movement} de ${money(previous)} para ${money(current)}.`,
      payload: { recurrenceId: recurrence.id, occurrenceDate: latest.date },
      dedupeKey: `price:${recurrence.id}:${latest.date}`,
    });
  }
  return candidates;
}

export function evaluateAlerts(data: AlertEvaluationData, now: Date): AlertDraft[] {
  const today = localDate(now);
  const month = today.slice(0, 7);
  const candidates = [
    ...duplicateAlerts(data.transactions, today),
    ...unusualSpendAlerts(data.transactions, today),
    ...subscriptionPriceAlerts(data.transactions, data.recurrences, today),
  ];

  const projection = calculateProjection({
    accounts: data.accounts.map(({ type, balanceCents }) => ({ type, balanceCents })),
    recurrences: data.recurrences.map((row) => ({
      id: row.id, kind: row.kind, status: row.status, expectedAmountCents: row.expectedAmountCents,
      nextExpectedDate: row.nextExpectedDate, accountType: row.accountType,
    })),
    transactions: data.transactions.map((row) => ({
      date: row.date, amountCents: row.amountCents, categoryKind: row.categoryKind,
      accountType: row.accountType, isTransfer: row.isTransfer, isBillPayment: row.isBillPayment,
      recurrenceId: row.recurrenceId, deletedAt: row.deletedAt,
    })),
    bills: data.bills.map(({ dueDate, totalCents, paidCents }) => ({ dueDate, totalCents, paidCents })),
  }, now);
  if (projection.projectedBalanceCents < 0) {
    candidates.push({
      type: "negative_projection", severity: "critical", title: "Saldo previsto negativo",
      body: `No ritmo atual, sua conta pode fechar o mês em −${money(projection.projectedBalanceCents)}.`,
      payload: { month: projection.month, projectedBalanceCents: projection.projectedBalanceCents },
      dedupeKey: `neg:${projection.month}`,
    });
  }

  const threeDays = addDays(today, 3);
  for (const bill of data.bills) {
    const remainingCents = Math.max(0, bill.totalCents - bill.paidCents);
    if (bill.dueDate < today || bill.dueDate > threeDays || remainingCents === 0) continue;
    candidates.push({
      type: "bill_due", severity: "warning", title: "Fatura próxima do vencimento",
      body: `A fatura de ${bill.accountName} vence em ${bill.dueDate} e ainda há ${money(remainingCents)} em aberto.`,
      payload: { billId: bill.id, accountId: bill.accountId },
      dedupeKey: `bill:${bill.id}`,
    });
  }

  const monthStart = `${month}-01`;
  for (const budget of data.budgets) {
    const category = data.transactions.find((row) => row.categoryId === budget.categoryId);
    if (!category) continue;
    const spentCents = data.transactions.filter((row) =>
      row.deletedAt === null && row.categoryId === budget.categoryId && row.categoryKind === "expense" &&
      row.date >= monthStart && row.date <= today && row.amountCents < 0 && !row.isTransfer && !row.isBillPayment,
    ).reduce((sum, row) => sum + Math.abs(row.amountCents), 0);
    if (spentCents <= budget.limitCents) continue;
    candidates.push({
      type: "budget_exceeded", severity: "warning", title: `Limite de ${category.categoryName} ultrapassado`,
      body: `Você já gastou ${money(spentCents)} de ${money(budget.limitCents)} neste mês.`,
      payload: { categoryId: budget.categoryId, month, spentCents, limitCents: budget.limitCents },
      dedupeKey: `budget:${budget.categoryId}:${month}`,
    });
  }

  for (const connection of data.connections) {
    if (connection.consentExpiresAt && connection.status !== "revoked") {
      const expiresAt = connection.consentExpiresAt;
      const expiresDate = localDate(expiresAt);
      if (expiresDate >= today && expiresDate <= addDays(today, 15)) {
        candidates.push({
          type: "consent_expiring", severity: "warning", title: "Acesso bancário prestes a expirar",
          body: `O acesso a ${connection.institutionName} expira em ${expiresDate}.`,
          payload: { connectionId: connection.id, expiresAt: expiresAt.toISOString() },
          dedupeKey: `consent:${connection.id}:${expiresAt.toISOString()}`,
        });
      }
    }
    if (connection.status === "error" || connection.status === "needs_reauth") {
      candidates.push({
        type: "sync_error", severity: "critical", title: "A conexão precisa de atenção",
        body: `Não foi possível atualizar os dados de ${connection.institutionName}.`,
        payload: { connectionId: connection.id },
        dedupeKey: `sync:${connection.id}:${today}`,
      });
    }
  }
  return candidates;
}

export function selectAlertDrafts(
  candidates: AlertDraft[],
  preferences: Partial<Record<AlertPreferenceType, boolean>>,
  existingDedupeKeys: ReadonlySet<string>,
  infoUsedThisWeek: number,
): AlertDraft[] {
  const selected: AlertDraft[] = [];
  const seen = new Set(existingDedupeKeys);
  let infoCount = infoUsedThisWeek;
  for (const candidate of candidates) {
    if (preferences[candidate.type] === false || seen.has(candidate.dedupeKey)) continue;
    if (candidate.severity === "info" && candidate.type !== "weekly_summary" && infoCount >= 3) continue;
    selected.push(candidate);
    seen.add(candidate.dedupeKey);
    if (candidate.severity === "info" && candidate.type !== "weekly_summary") infoCount++;
  }
  return selected;
}
