export type DebtKind = "card_revolving" | "overdraft" | "personal_loan" | "other";
export type DebtStrategy = "avalanche" | "snowball";

export type DebtSimulationInput = {
  id: string;
  name: string;
  balanceCents: number;
  monthlyRateBps: number;
  minimumPaymentCents: number;
};

export type DebtStrategyResult = {
  months: number;
  totalInterestCents: number;
  payoffOrder: string[];
  paidOff: boolean;
  monthlySchedule: Array<{ month: number; balanceCents: number }>;
};

export class DebtSimulationError extends Error {
  constructor(
    readonly code: "BUDGET_BELOW_MINIMUMS" | "BUDGET_BELOW_INTEREST",
    readonly requiredBudgetCents: number,
  ) {
    super(code === "BUDGET_BELOW_MINIMUMS"
      ? "O orçamento mensal não cobre os pagamentos mínimos das dívidas."
      : "O orçamento mensal não supera os juros do primeiro mês.");
    this.name = "DebtSimulationError";
  }
}

export type DebtDetectionAccount = {
  id: string;
  name: string;
  type: "checking" | "savings" | "credit_card" | "cash";
  balanceCents: number;
};

export type DebtDetectionBill = {
  accountId: string;
  dueDate: string;
  totalCents: number;
  paidCents: number;
  minimumPaymentCents: number | null;
};

export type ExistingDetectedDebt = {
  id: string;
  accountId: string | null;
  kind: DebtKind;
  source: "detected" | "user";
  confirmed: boolean;
  monthlyRateBps: number;
  rateIsEstimated: boolean;
};

export type DebtDetectionCandidate = {
  accountId: string;
  name: string;
  kind: "card_revolving" | "overdraft";
  balanceCents: number;
  monthlyRateBps: number;
  rateIsEstimated: boolean;
  minimumPaymentCents: number;
};

export type DebtDetectionPlan = {
  upserts: Array<{
    candidate: DebtDetectionCandidate;
    existing: ExistingDetectedDebt | null;
    preserveRate: boolean;
  }>;
  removeIds: string[];
  zeroIds: string[];
};

function roundedInterest(balanceCents: number, monthlyRateBps: number): number {
  return Number((BigInt(balanceCents) * BigInt(monthlyRateBps) + 5_000n) / 10_000n);
}

function strategyOrder(debts: DebtSimulationInput[], strategy: DebtStrategy): DebtSimulationInput[] {
  return [...debts].sort((a, b) => {
    const priority = strategy === "avalanche"
      ? b.monthlyRateBps - a.monthlyRateBps || a.balanceCents - b.balanceCents
      : a.balanceCents - b.balanceCents || b.monthlyRateBps - a.monthlyRateBps;
    return priority || a.name.localeCompare(b.name) || a.id.localeCompare(b.id);
  });
}

export function simulateDebtStrategy(
  debts: DebtSimulationInput[],
  monthlyBudgetCents: number,
  strategy: DebtStrategy,
): DebtStrategyResult {
  if (!Number.isSafeInteger(monthlyBudgetCents) || monthlyBudgetCents < 0) {
    throw new RangeError("monthlyBudgetCents must be a non-negative integer.");
  }
  const remaining = debts
    .filter((debt) => debt.balanceCents > 0)
    .map((debt) => ({ ...debt }));
  if (remaining.some((debt) =>
    !Number.isSafeInteger(debt.balanceCents) || debt.balanceCents < 0 ||
    !Number.isSafeInteger(debt.monthlyRateBps) || debt.monthlyRateBps < 0 ||
    !Number.isSafeInteger(debt.minimumPaymentCents) || debt.minimumPaymentCents < 0,
  )) throw new RangeError("Debt amounts and rates must be non-negative integers.");
  if (remaining.length === 0) {
    return { months: 0, totalInterestCents: 0, payoffOrder: [], paidOff: true, monthlySchedule: [] };
  }

  const firstMonthInterest = remaining.reduce(
    (sum, debt) => sum + roundedInterest(debt.balanceCents, debt.monthlyRateBps),
    0,
  );
  const firstMonthBalances = remaining.map((debt) =>
    debt.balanceCents + roundedInterest(debt.balanceCents, debt.monthlyRateBps),
  );
  const firstMonthMinimums = remaining.reduce((sum, debt, index) =>
    sum + Math.min(firstMonthBalances[index]!, debt.minimumPaymentCents), 0,
  );
  if (monthlyBudgetCents < firstMonthMinimums) {
    throw new DebtSimulationError("BUDGET_BELOW_MINIMUMS", firstMonthMinimums);
  }
  if (monthlyBudgetCents <= firstMonthInterest) {
    throw new DebtSimulationError("BUDGET_BELOW_INTEREST", firstMonthInterest + 1);
  }

  const originalById = new Map(remaining.map((debt) => [debt.id, debt]));
  const payoffOrder: string[] = [];
  const paidOffIds = new Set<string>();
  const monthlySchedule: Array<{ month: number; balanceCents: number }> = [];
  let totalInterestCents = 0;
  let months = 0;

  for (let month = 1; month <= 360; month++) {
    for (const debt of remaining) {
      const interest = roundedInterest(debt.balanceCents, debt.monthlyRateBps);
      debt.balanceCents += interest;
      totalInterestCents += interest;
    }

    const ordered = strategyOrder(remaining, strategy);
    let budgetLeft = monthlyBudgetCents;
    for (const debt of ordered) {
      const payment = Math.min(debt.balanceCents, debt.minimumPaymentCents);
      debt.balanceCents -= payment;
      budgetLeft -= payment;
    }

    for (const debt of ordered) {
      if (budgetLeft <= 0) break;
      if (debt.balanceCents === 0) continue;
      const payment = Math.min(debt.balanceCents, budgetLeft);
      debt.balanceCents -= payment;
      budgetLeft -= payment;
    }

    for (const debt of ordered) {
      if (debt.balanceCents === 0 && !paidOffIds.has(debt.id)) {
        paidOffIds.add(debt.id);
        payoffOrder.push(originalById.get(debt.id)!.name);
      }
    }

    const balanceCents = remaining.reduce((sum, debt) => sum + debt.balanceCents, 0);
    monthlySchedule.push({ month, balanceCents });
    months = month;
    if (balanceCents === 0) break;
  }

  return {
    months,
    totalInterestCents,
    payoffOrder,
    paidOff: remaining.every((debt) => debt.balanceCents === 0),
    monthlySchedule,
  };
}

export function simulateDebtStrategies(debts: DebtSimulationInput[], monthlyBudgetCents: number) {
  return {
    avalanche: simulateDebtStrategy(debts, monthlyBudgetCents, "avalanche"),
    snowball: simulateDebtStrategy(debts, monthlyBudgetCents, "snowball"),
  };
}

export function planDetectedDebts(input: {
  today: string;
  accounts: DebtDetectionAccount[];
  bills: DebtDetectionBill[];
  existingDebts: ExistingDetectedDebt[];
}): DebtDetectionPlan {
  const existing = input.existingDebts.filter((debt) => debt.source === "detected");
  const existingByKey = new Map(existing.map((debt) => [`${debt.accountId ?? ""}:${debt.kind}`, debt]));
  const candidates: DebtDetectionCandidate[] = [];

  for (const account of input.accounts) {
    if (account.type === "credit_card") {
      const latestOverdue = input.bills
        .filter((bill) => bill.accountId === account.id && bill.dueDate < input.today)
        .sort((a, b) => b.dueDate.localeCompare(a.dueDate))[0];
      if (latestOverdue && latestOverdue.paidCents > 0 && latestOverdue.paidCents < latestOverdue.totalCents) {
        candidates.push({
          accountId: account.id,
          name: account.name,
          kind: "card_revolving",
          balanceCents: latestOverdue.totalCents - latestOverdue.paidCents,
          monthlyRateBps: 1_200,
          rateIsEstimated: true,
          minimumPaymentCents: Math.min(
            latestOverdue.totalCents - latestOverdue.paidCents,
            latestOverdue.minimumPaymentCents ?? 0,
          ),
        });
      }
    }
    if (account.type === "checking" && account.balanceCents < 0) {
      candidates.push({
        accountId: account.id,
        name: `Cheque especial · ${account.name}`,
        kind: "overdraft",
        balanceCents: Math.abs(account.balanceCents),
        monthlyRateBps: 800,
        rateIsEstimated: true,
        minimumPaymentCents: 0,
      });
    }
  }

  const candidateKeys = new Set<string>();
  const upserts = candidates.map((candidate) => {
    const key = `${candidate.accountId}:${candidate.kind}`;
    candidateKeys.add(key);
    const prior = existingByKey.get(key) ?? null;
    return { candidate, existing: prior, preserveRate: prior?.confirmed === true };
  });
  const removeIds: string[] = [];
  const zeroIds: string[] = [];
  for (const debt of existing) {
    if (debt.accountId === null || candidateKeys.has(`${debt.accountId}:${debt.kind}`)) continue;
    if (debt.confirmed) zeroIds.push(debt.id);
    else removeIds.push(debt.id);
  }
  return { upserts, removeIds, zeroIds };
}
