export type ProviderConnection = {
  status: "syncing" | "active" | "error" | "needs_reauth" | "revoked";
  institutionName: string;
  institutionLogoUrl: string | null;
  consentExpiresAt: Date | null;
  lastErrorCode: string | null;
};
export type ProviderAccount = {
  providerAccountId: string;
  type: "checking" | "savings" | "credit_card";
  name: string;
  balanceCents: number;
  creditLimitCents: number | null;
  availableLimitCents: number | null;
  billCloseDate: string | null;
  billDueDate: string | null;
};
export type ProviderTransaction = {
  providerTransactionId: string;
  providerStableId: string | null;
  date: string;
  description: string;
  amountCents: number;
  paymentMethod: "pix" | "boleto" | "card" | "ted" | "debit" | "other" | null;
  counterpart: { type: "person" | "company"; name: string; document: string | null } | null;
  installment: { number: number; total: number } | null;
  providerCategory: string | null;
  providerBillId: string | null;
};
export type ProviderBill = {
  providerBillId: string;
  closeDate: string;
  dueDate: string;
  totalCents: number;
  minimumPaymentCents: number | null;
};
export interface FinancialDataProvider {
  createConnectToken?(userId: string): Promise<string>;
  getConnection(providerItemId: string): Promise<ProviderConnection>;
  listAccounts(providerItemId: string): Promise<ProviderAccount[]>;
  listTransactions(providerAccountId: string, from: Date): Promise<ProviderTransaction[]>;
  listBills?(providerAccountId: string): Promise<ProviderBill[]>;
  refresh(providerItemId: string): Promise<void>;
  revoke(providerItemId: string): Promise<void>;
}
export class ProviderError extends Error {
  constructor(public code: string) { super(code); }
}
