import { Router, type IRouter } from "express";
import { and, asc, eq, getTableColumns, isNull } from "drizzle-orm";
import { z } from "zod/v4";
import { accounts, bills, recurrences, transactions } from "@workspace/shared/schema";
import { GetBillsResponse, GetFutureInstallmentsQueryParams, GetFutureInstallmentsResponse, GetRecurrencesResponse } from "@workspace/api-zod";
import { db } from "../db/connection";
import { requireAuth } from "../middlewares/security";
import { apiError } from "../lib/errors";
import { calculateInstallments } from "../services/installments";

const router: IRouter = Router();
router.use(requireAuth);

router.get("/recurrences", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const userId = req.session.userId!;
  const rows = await db.select({
    id: recurrences.id, accountId: recurrences.accountId, accountName: accounts.name,
    kind: recurrences.kind, label: recurrences.label, merchantKey: recurrences.merchantKey,
    expectedAmountCents: recurrences.expectedAmountCents, previousAmountCents: recurrences.previousAmountCents,
    frequency: recurrences.frequency, dayOfMonth: recurrences.dayOfMonth, nextExpectedDate: recurrences.nextExpectedDate,
    status: recurrences.status, source: recurrences.source, createdAt: recurrences.createdAt, updatedAt: recurrences.updatedAt,
  }).from(recurrences).leftJoin(accounts, and(eq(accounts.id, recurrences.accountId), eq(accounts.userId, userId)))
    .where(eq(recurrences.userId, userId)).orderBy(asc(recurrences.nextExpectedDate), asc(recurrences.label));
  res.json(GetRecurrencesResponse.parse({ data: rows }));
});

router.get("/installments/future", async (req, res): Promise<void> => {
  const parsed = GetFutureInstallmentsQueryParams.strict().safeParse(req.query);
  if (!parsed.success) {
    apiError(res, 400, "VALIDATION_ERROR", "Informe um período de 1 a 24 meses.");
    return;
  }
  const userId = req.session.userId!;
  const rows = await db.select({ ...getTableColumns(transactions), accountName: accounts.name })
    .from(transactions).innerJoin(accounts, and(eq(accounts.id, transactions.accountId), eq(accounts.userId, userId)))
    .where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt)));
  const result = calculateInstallments(rows, parsed.data.months, new Date());
  res.json(GetFutureInstallmentsResponse.parse({ data: { months: result.months } }));
});

router.get("/bills", async (req, res): Promise<void> => {
  if (!z.object({}).strict().safeParse(req.query).success) {
    apiError(res, 400, "VALIDATION_ERROR", "Consulta inválida.");
    return;
  }
  const userId = req.session.userId!;
  const rows = await db.select({
    id: bills.id, accountId: bills.accountId, accountName: accounts.name,
    providerBillId: bills.providerBillId, closeDate: bills.closeDate, dueDate: bills.dueDate,
    totalCents: bills.totalCents, minimumPaymentCents: bills.minimumPaymentCents,
    paidCents: bills.paidCents, status: bills.status, createdAt: bills.createdAt, updatedAt: bills.updatedAt,
  }).from(bills).innerJoin(accounts, and(eq(accounts.id, bills.accountId), eq(accounts.userId, userId)))
    .where(eq(bills.userId, userId)).orderBy(asc(bills.dueDate), asc(bills.closeDate));
  res.json(GetBillsResponse.parse({ data: rows }));
});

export default router;
